1	/**
2	 * Agent-runtime main entry point.
3	 *
4	 * Lifecycle:
5	 *   bootstrap (once) → polling loop:
6	 *     pull workspaces → eligibility → claim → run-claude → sleep → repeat
7	 *
8	 * idle_sleep_seconds controls the loop behaviour (read from agent.yaml):
9	 *   0   → single-shot mode: one cycle then exit (for external schedulers)
10	 *   >0  → continuous: loops indefinitely, sleeping idle_sleep_seconds between cycles
11	 *
12	 * Exit codes:
13	 *   0  normal exit (task ran, idle cycle, or kill-switch off)
14	 *   2  agent.yaml invalid
15	 *   3  git clone/pull failed (bootstrap only — per-cycle pull failures never exit)
16	 *   4  unexpected fatal error
17	 */
18	
19	import { existsSync, readFileSync } from "node:fs";
20	import { join } from "node:path";
21	import { parse as parseYaml } from "yaml";
22	import { runBootstrap } from "./bootstrap/bootstrap.js";
23	import { resolveSSHKey } from "./resolve-ssh-key.js";
24	import { workspaceYamlPath, taskYamlAbsPath, taskBranchName } from "./paths.js";
25	import { findEligibleTasks } from "./eligibility/match.js";
26	import { claimTask } from "./claim/claim-task.js";
27	import { openWorkspacePr, parseGitHubCoords } from "./claim/open-workspace-pr.js";
28	import type { Task } from "./types/task.js";
29	import { generateAgentContext } from "./bootstrap/agent-context.js";
30	import { fetchRagContext } from "./bootstrap/fetch-rag-context.js";
31	import { runClaude } from "./loop/run-claude.js";
32	import { resolveModel } from "./config/resolve-model-policy.js";
33	import { parseModelOverrides } from "./config/parse-model-overrides.js";
34	import type { ModelPolicy } from "./config/resolve-model-policy.js";
35	import { pullWorkspaces } from "./poll/pull-workspaces.js";
36	import { runAgentLoop, type CycleOutcome } from "./poll/agent-loop.js";
37	import { checkInReviewPrs } from "./poll/check-in-review-prs.js";
38	import { handleMergeConflicts } from "./pr-response/auto-rebase.js";
39	import { handleDraftReviews } from "./pr-response/dispatch-draft-review.js";
40	import { handleMergedPrs, handleWorkspacePrRecoveries } from "./poll/handle-merged-prs.js";
41	
42	// ── Helpers ───────────────────────────────────────────────────────────────────
43	
44	function requireEnv(name: string): string {
45	  const val = process.env[name];
46	  if (!val) throw new Error(`Required environment variable ${name} is not set`);
47	  return val;
48	}
49	
50	/** Extract repo name from SSH or HTTPS URL (strips .git suffix). */
51	function extractRepoName(url: string): string {
52	  const match = /\/([^/]+?)(?:\.git)?$/.exec(url);
53	  return match?.[1] ?? url;
54	}
55	
56	/** Emit a structured JSON event to stdout. */
57	function emit(event: Record<string, unknown>): void {
58	  console.log(JSON.stringify({ at: new Date().toISOString(), ...event }));
59	}
60	
61	/**
62	 * Given a task's repo ID and the workspace.yaml from the management workspace,
63	 * resolve the local filesystem path where that repo is cloned.
64	 *
65	 * Bootstrap (step 5b) guarantees that process.env[VAR] is set for every
66	 * local_path: env:<VAR> declaration before main() reaches this call.
67	 */
68	function resolveRepoLocalPath(
69	  workspaceRoot: string,
70	  repoId: string,
71	): string {
72	  type RepoEntry = { id: string; github: string; local_path?: string };
73	  const yaml = parseYaml(
74	    readFileSync(workspaceYamlPath(workspaceRoot), "utf-8"),
75	  ) as { repos: RepoEntry[] };
76	
77	  const repo = yaml.repos.find((r) => r.id === repoId);
78	  if (!repo) throw new Error(`Repo "${repoId}" not found in workspace.yaml`);
79	
80	  if (!repo.local_path?.startsWith("env:")) {
81	    throw new Error(
82	      `Repo "${repoId}" has no "local_path: env:<VAR>" declaration in workspace.yaml. ` +
83	      `Bootstrap is responsible for setting the env var before this point.`,
84	    );
85	  }
86	
87	  const envVar = repo.local_path.slice(4);
88	  const val = process.env[envVar];
89	  if (!val) {
90	    throw new Error(
91	      `Env var ${envVar} is not set — bootstrap should have populated it for repo "${repoId}".`,
92	    );
93	  }
94	  return val;
95	}
96	
97	/**
98	 * Resolve the base branch for a repo ID from workspace.yaml.
99	 * Defaults to "main" if not declared.
100	 */
101	function resolveRepoBaseBranch(
102	  workspaceRoot: string,
103	  repoId: string,
104	): string {
105	  type RepoEntry = { id: string; base_branch?: string };
106	  const yaml = parseYaml(
107	    readFileSync(workspaceYamlPath(workspaceRoot), "utf-8"),
108	  ) as { repos: RepoEntry[] };
109	
110	  const repo = yaml.repos.find((r) => r.id === repoId);
111	  if (!repo) throw new Error(`Repo "${repoId}" not found in workspace.yaml`);
112	  return repo.base_branch ?? "main";
113	}
114	
115	/**
116	 * Read the task YAML for a given feature/task and return its repo field.
117	 */
118	function resolveTaskRepoId(
119	  workspaceRoot: string,
120	  featureId: string,
121	  taskId: string,
122	): string {
123	  const task = parseYaml(
124	    readFileSync(taskYamlAbsPath(workspaceRoot, featureId, taskId), "utf-8"),
125	  ) as { repo: string };
126	  if (!task.repo) throw new Error(`Task ${taskId} has no repo field`);
127	  return task.repo;
128	}
129	
130	/**
131	 * Load the workspace-level model_policy from workspace.yaml.
132	 * Returns a minimal fallback policy if the field is absent (e.g. older workspaces).
133	 */
134	function loadWorkspaceModelPolicy(workspaceRoot: string): ModelPolicy {
135	  const yaml = parseYaml(
136	    readFileSync(workspaceYamlPath(workspaceRoot), "utf-8"),
137	  ) as { model_policy?: ModelPolicy };
138	
139	  if (yaml.model_policy) return yaml.model_policy;
140	
141	  // Sensible fallback so the runtime never hard-errors on a missing policy.
142	  const defaultPhase = {
143	    allowed: ["claude-sonnet-4-6"],
144	    default: "claude-sonnet-4-6",
145	  };
146	  return {
147	    implementation: defaultPhase,
148	    self_review: defaultPhase,
149	    pr_description: defaultPhase,
150	    suggested_next_step: { allowed: ["claude-haiku-4-5-20251001"], default: "claude-haiku-4-5-20251001" },
151	  };
152	}
153	
154	
155	/**
156	 * Parse the GitHub owner/repo and base branch for the management repo declared
157	 * in workspace.yaml. Used to call openWorkspacePr after a successful claim.
158	 */
159	function parseManagementRepoCoords(
160	  workspaceRoot: string,
161	): { owner: string; repo: string; baseBranch: string } {
162	  type RepoEntry = { id: string; github: string; local_path?: string; base_branch?: string };
163	  const yaml = parseYaml(
164	    readFileSync(workspaceYamlPath(workspaceRoot), "utf-8"),
165	  ) as { management_repo: string; repos: RepoEntry[] };
166	
167	  const mgmtId = yaml.management_repo;
168	  const mgmtRepo = yaml.repos.find((r) => r.id === mgmtId);
169	  if (!mgmtRepo) {
170	    throw new Error(`Management repo "${mgmtId}" not found in workspace.yaml repos`);
171	  }
172	  const { owner, repo } = parseGitHubCoords(mgmtRepo.github);
173	  return { owner, repo, baseBranch: mgmtRepo.base_branch ?? "main" };
174	}
175	
176	// ── Main ──────────────────────────────────────────────────────────────────────
177	
178	async function main(): Promise<number> {
179	  // ── 1. Read required environment ─────────────────────────────────────────
180	  let agentYamlPath: string;
181	  let workflowLocalPath: string;
182	  let workspacesRoot: string;
183	  let gitAuthorEmail: string;
184	
185	  try {
186	    agentYamlPath = requireEnv("AGENT_YAML_PATH");
187	    workflowLocalPath = requireEnv("WORKFLOW_LOCAL_PATH");
188	    workspacesRoot = requireEnv("WORKSPACES_ROOT");
189	    gitAuthorEmail = requireEnv("GIT_AUTHOR_EMAIL");
190	  } catch (e) {
191	    emit({ type: "fatal_missing_env", details: (e as Error).message });
192	    return 4;
193	  }
194	
195	  const gitAuthorName = process.env.GIT_AUTHOR_NAME ?? gitAuthorEmail;
196	
197	  // ── SSH key resolution ────────────────────────────────────────────────────
198	  // Preferred: SSH_PRIVATE_KEY env var (raw PEM) — write to temp file 0400.
199	  // Fallback:  SSH_KEY_PATH env var pointing to a file already present.
200	  // Neither:   warn and proceed; SSH-only repos will fail at clone time.
201	  const sshResolution = resolveSSHKey(process.env);
202	  const sshKeyPath = sshResolution.sshKeyPath;
203	  if (sshResolution.warned) {
204	    emit({ type: "warn_no_ssh_key", note: "Neither SSH_PRIVATE_KEY nor SSH_KEY_PATH is set. SSH-only git operations will fail." });
205	  }
206	
207	  // ── 2. Bootstrap (once at container start) ────────────────────────────────
208	  const bootstrapResult = await runBootstrap({
209	    agentYamlPath,
210	    workflowLocalPath,
211	    workflowUrl: process.env.WORKFLOW_URL,
212	    workspacesRoot,
213	    sshKeyPath,
214	  });
215	
216	  if (bootstrapResult.exitCode !== 0) return bootstrapResult.exitCode;
217	
218	  const config = bootstrapResult.config!;
219	
220	  // Kill switch already handled inside runBootstrap (exits 0).
221	  // If we get here, config.enabled is true.
222	
223	  // ── 3. Build the per-cycle scan+claim+run function ────────────────────────
224	  const githubToken = process.env.GITHUB_TOKEN ?? "";
225	  if (!githubToken) {
226	    emit({ type: "warn_no_github_token" });
227	  }
228	
229	  // Tracks the last time the in_review PR poll ran (ms since epoch, or null).
230	  let lastPrPollAt: number | null = null;
231	
232	  async function runOneCycle(): Promise<CycleOutcome> {
233	    // ── 3a. Pull latest workspace state ──────────────────────────────────────
234	    const pullResults = pullWorkspaces({
235	      watchUrls: config.watches,
236	      sshKeyPath,
237	      workspacesRoot,
238	      workflowUrl: process.env.WORKFLOW_URL,
239	      workflowLocalPath,
240	      emit,
241	    });
242	
243	    // Build a set of workspaces that failed to pull — skip scanning them.
244	    const haltedUrls = new Set(
245	      pullResults
246	        .filter((r) => r.outcome === "halt" || r.outcome === "warn")
247	        .map((r) => r.url),
248	    );
249	
250	    // ── 3b. Scan remaining workspaces for an eligible task ────────────────────
251	    // Track outcome separately so the in_review pass always runs after.
252	    let outcome: CycleOutcome = "idle";
253	
254	    // Collect workspace paths that were pulled successfully (for in_review poll).
255	    const pulledWorkspaceRoots: string[] = [];
256	
257	    outerLoop:
258	    for (const watchUrl of config.watches) {
259	      if (haltedUrls.has(watchUrl)) continue;
260	
261	      const workspaceLocalPath = join(workspacesRoot, extractRepoName(watchUrl));
262	      pulledWorkspaceRoots.push(workspaceLocalPath);
263	
264	      if (!existsSync(workspaceLocalPath)) {
265	        emit({ type: "workspace_not_found", workspace_url: watchUrl, local_path: workspaceLocalPath });
266	        continue;
267	      }
268	
269	      // Find eligible tasks in this workspace.
270	      let eligibleTasks;
271	      try {
272	        eligibleTasks = findEligibleTasks(config, workspaceLocalPath, workflowLocalPath);
273	      } catch (e) {
274	        emit({ type: "eligibility_error", workspace_url: watchUrl, details: String(e) });
275	        continue;
276	      }
277	
278	      if (eligibleTasks.length === 0) {
279	        emit({ type: "no_eligible_tasks", workspace_url: watchUrl });
280	        continue;
281	      }
282	
283	      // Try each task in order until one is claimed.
284	      for (const { task, featureId } of eligibleTasks) {
285	        // ── Claim ─────────────────────────────────────────────────────────────
286	        const claimResult = await claimTask({
287	          workspaceRoot: workspaceLocalPath,
288	          taskId: task.id,
289	          featureId,
290	          gitAuthorEmail,
291	          gitAuthorName,
292	          sshKeyPath,
293	          jitterMaxSeconds: config.jitter_max_seconds,
294	        });
295	
296	        const taskBranch = taskBranchName(featureId, task.id);
297	
298	        if (!claimResult.won) {
299	          if (claimResult.reason !== "branch_blocked_recovery") {
300	            emit({ type: "claim_lost", task_id: task.id, feature_id: featureId, reason: claimResult.reason });
301	            continue;
302	          }
303	          emit({ type: "task_blocked_recovery_detected", task_id: task.id, feature_id: featureId });
304	          const _recoveredTask = parseYaml(
305	            readFileSync(taskYamlAbsPath(workspaceLocalPath, featureId, task.id), "utf-8"),
306	          ) as Task;
307	          void _recoveredTask;
308	        } else {
309	          emit({ type: "task_claimed", task_id: task.id, feature_id: featureId });
310	        }
311	
312	        // ── Open management-repo PR (non-fatal) ───────────────────────────────
313	        if (githubToken) {
314	          try {
315	            const mgmtCoords = parseManagementRepoCoords(workspaceLocalPath);
316	            await openWorkspacePr({
317	              workspaceRoot: workspaceLocalPath,
318	              featureId,
319	              taskId: task.id,
320	              branch: taskBranch,
321	              baseBranch: mgmtCoords.baseBranch,
322	              githubToken,
323	              repoOwner: mgmtCoords.owner,
324	              repoName: mgmtCoords.repo,
325	              gitAuthorEmail,
326	              gitAuthorName,
327	              sshKeyPath,
328	            });
329	            emit({ type: "workspace_pr_opened", task_id: task.id, feature_id: featureId });
330	          } catch (e) {
331	            emit({ type: "workspace_pr_failed", task_id: task.id, feature_id: featureId, details: String(e) });
332	          }
333	        }
334	
335	        // ── Load model policy + resolve task repo path ────────────────────────
336	        const workspaceModelPolicy = loadWorkspaceModelPolicy(workspaceLocalPath);
337	        const taskRepoRoot = resolveRepoLocalPath(workspaceLocalPath, task.repo);
338	
339	        // ── Resolve implementation model + parse task-level overrides ─────────
340	        const tasksMdPath = join(workspaceLocalPath, "docs", "features", featureId, "tasks.md");
341	        let taskModelOverrides = {};
342	        try {
343	          const tasksMdContent = readFileSync(tasksMdPath, "utf-8");
344	          taskModelOverrides = parseModelOverrides(tasksMdContent, task.id);
345	        } catch {
346	          // Non-fatal — use workspace defaults if tasks.md is unreadable.
347	        }
348	        const implementationModel = resolveModel(
349	          workspaceModelPolicy,
350	          taskModelOverrides,
351	          "implementation",
352	          task.id,
353	        );
354	
355	        // ── Generate agent context ─────────────────────────────────────────────
356	        const baseAgentContext = generateAgentContext({
357	          taskId: task.id,
358	          featureId,
359	          taskTitle: task.title,
360	          taskBranch,
361	          taskRepo: task.repo,
362	          taskRepoRoot,
363	          workspaceRoot: workspaceLocalPath,
364	          gitAuthorEmail,
365	          gitAuthorName,
366	          implementationModel,
367	        });
368	
369	        // ── Pre-inject RAG context ─────────────────────────────────────────────
370	        // The runtime is the authoritative writer of the rag_pre_flight task-log
371	        // entry — runClaude appends it before spawning Claude and audits it on
372	        // exit, so the agent cannot fabricate or omit RAG injection metadata.
373	        const mcpRagUrl = process.env.MCP_RAG_URL;
374	        const workspaceYaml = parseYaml(
375	          readFileSync(workspaceYamlPath(workspaceLocalPath), "utf-8"),
376	        ) as { workspace_id: string };
377	        const ragQuery = `${task.title} ${featureId}`;
378	        const ragPreFlight = await fetchRagContext(
379	          mcpRagUrl,
380	          ragQuery,
381	          workspaceYaml.workspace_id,
382	        );
383	        const agentContext = ragPreFlight.block
384	          ? `${baseAgentContext}\n\n${ragPreFlight.block}`
385	          : baseAgentContext;
386	
387	        // ── Run claude ─────────────────────────────────────────────────────────
388	        const runResult = await runClaude({
389	          taskId: task.id,
390	          featureId,
391	          workspaceRoot: workspaceLocalPath,
392	          taskRepoRoot,
393	          workflowLocalPath,
394	          agentContext,
395	          maxTurns: config.budget.max_iterations,
396	          maxTokens: config.budget.max_tokens_per_task,
397	          sshKeyPath,
398	          gitAuthorEmail,
399	          taskBranch,
400	          logSinkEnabled: config.log_sink.enabled,
401	          ragPreFlight: {
402	            query: ragQuery,
403	            injected: ragPreFlight.injected,
404	            summary: ragPreFlight.summary,
405	          },
406	        });
407	
408	        emit({ type: "task_run_complete", task_id: task.id, feature_id: featureId, outcome: runResult.outcome });
409	        outcome = "ran_task";
410	        // Break out of both loops — but still complete the in_review pass below.
411	        break outerLoop;
412	      }
413	    }
414	
415	    // ── 3c. In-review PR poll ─────────────────────────────────────────────────
416	    // Runs after every ready-task pass, regardless of whether a task was claimed.
417	    // Skipped if it ran within pr_poll_interval_seconds.
418	    if (githubToken) {
419	      const prPollIntervalMs =
420	        (config.pr_poll_interval_seconds ?? config.idle_sleep_seconds ?? 60) * 1000;
421	      const now = Date.now();
422	
423	      if (lastPrPollAt === null || now - lastPrPollAt >= prPollIntervalMs) {
424	        if (pulledWorkspaceRoots.length > 0) lastPrPollAt = now;
425	        try {
426	          const { prResults, workspacePrRecoveries } = await checkInReviewPrs({
427	            workspaceRoots: pulledWorkspaceRoots,
428	            githubToken,
429	            emit,
430	          });
431	
432	          // ── T3: Auto-rebase for mergeable === false tasks ──────────────────────
433	          // Run per workspace so the resolver closures have the correct root.
434	          for (const wsRoot of pulledWorkspaceRoots) {
435	            const wsResults = prResults.filter((r) => r.workspaceRoot === wsRoot);
436	            if (wsResults.some((r) => r.mergeable === false)) {
437	              await handleMergeConflicts({
438	                prResults: wsResults,
439	                workspaceRoot: wsRoot,
440	                resolveImplRepoRoot: (repoId) =>
441	                  resolveRepoLocalPath(wsRoot, repoId),
442	                resolveImplBaseBranch: (repoId) =>
443	                  resolveRepoBaseBranch(wsRoot, repoId),
444	                resolveTaskRepoId: (featureId, taskId) =>
445	                  resolveTaskRepoId(wsRoot, featureId, taskId),
446	                gitAuthorEmail,
447	                gitAuthorName,
448	                sshKeyPath,
449	                emit,
450	              });
451	            }
452	          }
453	
454	          // ── T4: Review dispatch for tasks with open comments ──────────────────
455	          // Run per workspace so the resolver closures have the correct root.
456	          for (const wsRoot of pulledWorkspaceRoots) {
457	            const wsResults = prResults.filter((r) => r.workspaceRoot === wsRoot);
458	            if (wsResults.some((r) => r.hasOpenComments === true)) {
459	              const wsModelPolicy = loadWorkspaceModelPolicy(wsRoot);
460	              await handleDraftReviews({
461	                prResults: wsResults,
462	                workspaceRoot: wsRoot,
463	                resolveImplRepoRoot: (repoId) =>
464	                  resolveRepoLocalPath(wsRoot, repoId),
465	                resolveTaskRepoId: (featureId, taskId) =>
466	                  resolveTaskRepoId(wsRoot, featureId, taskId),
467	                resolveImplementationModel: (featureId, taskId) => {
468	                  try {
469	                    const tasksMdPath = join(wsRoot, "docs", "features", featureId, "tasks.md");
470	                    const content = readFileSync(tasksMdPath, "utf-8");
471	                    const overrides = parseModelOverrides(content, taskId);
472	                    return resolveModel(wsModelPolicy, overrides, "implementation", taskId);
473	                  } catch {
474	                    return resolveModel(wsModelPolicy, {}, "implementation", taskId);
475	                  }
476	                },
477	                gitAuthorEmail,
478	                gitAuthorName,
479	                sshKeyPath,
480	                workflowLocalPath,
481	                maxTurns: config.budget.max_iterations,
482	                maxTokens: config.budget.max_tokens_per_task,
483	                logSinkEnabled: config.log_sink.enabled,
484	                emit,
485	              });
486	            }
487	          }
488	
489	          // ── Merge completion for merged implementation PRs ─────────────────────
490	          // Run per workspace so each handler operates on its own management repo.
491	          for (const wsRoot of pulledWorkspaceRoots) {
492	            const wsResults = prResults.filter((r) => r.workspaceRoot === wsRoot);
493	            if (wsResults.some((r) => r.merged === true)) {
494	              const mgmtCoords = parseManagementRepoCoords(wsRoot);
495	              await handleMergedPrs({
496	                prResults: wsResults,
497	                workspaceRoot: wsRoot,
498	                mgmtRepoOwner: mgmtCoords.owner,
499	                mgmtRepoName: mgmtCoords.repo,
500	                mgmtBaseBranch: mgmtCoords.baseBranch,
501	                githubToken,
502	                gitAuthorEmail,
503	                gitAuthorName,
504	                sshKeyPath,
505	                emit,
506	              });
507	            }
508	          }
509	
510	          // ── Workspace PR recovery for done tasks whose workspace PR failed ────
511	          // Grouped by workspace so each call targets the correct management repo.
512	          for (const wsRoot of pulledWorkspaceRoots) {
513	            const wsRecoveries = workspacePrRecoveries.filter(
514	              (r) => r.workspaceRoot === wsRoot,
515	            );
516	            if (wsRecoveries.length > 0) {
517	              const mgmtCoords = parseManagementRepoCoords(wsRoot);
518	              await handleWorkspacePrRecoveries({
519	                recoveries: wsRecoveries,
520	                mgmtRepoOwner: mgmtCoords.owner,
521	                mgmtRepoName: mgmtCoords.repo,
522	                mgmtBaseBranch: mgmtCoords.baseBranch,
523	                githubToken,
524	                gitAuthorEmail,
525	                gitAuthorName,
526	                sshKeyPath,
527	                emit,
528	              });
529	            }
530	          }
531	        } catch (e) {
532	          emit({ type: "in_review_poll_error", details: String(e) });
533	        }
534	      }
535	    }
536	
537	    return outcome;
538	  }
539	
540	  // ── 4. Run the polling loop ───────────────────────────────────────────────
541	  await runAgentLoop({ config, runCycle: runOneCycle, emit });
542	
543	  return 0;
544	}
545	
546	main()
547	  .then((code) => process.exit(code))
548	  .catch((e) => {
549	    try {
550	      console.log(
551	        JSON.stringify({
552	          type: "fatal_error",
553	          details: (e as Error).message ?? String(e),
554	          at: new Date().toISOString(),
555	        }),
556	      );
557	    } catch {
558	      /* cannot emit — last resort */
559	    }
560	    process.exit(4);
561	  });
562

