1	/**
2	 * T5: Claude Code CLI subprocess invocation.
3	 *
4	 * Replaces the raw Anthropic SDK tool-use loop (run-task.ts) with a thin
5	 * wrapper around `claude -p <agentContext> --max-turns <n>`. After the
6	 * subprocess exits, the task YAML is read to determine the outcome.
7	 *
8	 * Token audit (D3 option X / Y):
9	 *   Attempt to find a JSON usage line in stdout. If found and total tokens
10	 *   exceed maxTokens, override the outcome to budget_exceeded. If the format
11	 *   is not found, emit budget_audit_skipped and continue (option Y).
12	 */
13	
14	import { spawn, execSync } from "node:child_process";
15	import { mkdirSync, appendFileSync, readFileSync, writeFileSync, existsSync, readdirSync, rmSync, copyFileSync, lstatSync } from "node:fs";
16	import { join } from "node:path";
17	import { homedir } from "node:os";
18	import { parse as parseYaml, stringify as yamlStringify } from "yaml";
19	import type { Task, BlockedReason, TaskLogEntry } from "../types/task.js";
20	import { taskYamlAbsPath, taskYamlRelPath, featureLogsDirPath, logFileRelPath } from "../paths.js";
21	import { deriveLogPath, toSafeIso } from "../logging/log-sink.js";
22	import { redactSecrets } from "../logging/redact-secrets.js";
23	import { buildGitEnv, buildGitCommitEnv } from "../git-env.js";
24	
25	// ── Public types ──────────────────────────────────────────────────────────────
26	
27	export type RunClaudeResult =
28	  | { outcome: "in_review" }
29	  | { outcome: "blocked"; reason: string; details?: unknown };
30	
31	/**
32	 * RAG pre-flight metadata supplied by the caller.
33	 *
34	 * When present, runClaude appends a `rag_pre_flight` log entry to the task YAML
35	 * before spawning Claude and audits the entry on exit. This makes RAG injection
36	 * non-forgeable: the runtime — not the agent — writes the audit record, and
37	 * the runtime verifies the record survives Claude's mutations untouched.
38	 */
39	export interface RagPreFlight {
40	  /** The query string passed to the RAG server. */
41	  query: string;
42	  /** True iff at least one chunk was retrieved. */
43	  injected: boolean;
44	  /**
45	   * Deterministic summary string. Must match one of the patterns enforced by
46	   * `auditRagPreFlight` — see `fetchRagContext` for the vocabulary.
47	   */
48	  summary: string;
49	}
50	
51	export interface RunClaudeOpts {
52	  taskId: string;
53	  featureId: string;
54	  workspaceRoot: string;
55	  taskRepoRoot: string;
56	  /** Absolute path to the workflow repo (contains technical_skills/). */
57	  workflowLocalPath: string;
58	  agentContext: string;
59	  maxTurns: number;
60	  maxTokens: number;
61	  sshKeyPath: string | undefined;
62	  gitAuthorEmail: string;
63	  taskBranch: string;
64	  /** When true, write captured stdout to the JSONL log file and commit+push. */
65	  logSinkEnabled: boolean;
66	  /**
67	   * Optional. When provided, write a `rag_pre_flight` log entry before
68	   * spawning Claude and audit it on exit. Omit for runClaude callers that
69	   * don't need RAG accountability (e.g. PR review dispatch).
70	   */
71	  ragPreFlight?: RagPreFlight;
72	}
73	
74	// ── Helpers ───────────────────────────────────────────────────────────────────
75	
76	function emit(event: Record<string, unknown>): void {
77	  console.log(JSON.stringify({ at: new Date().toISOString(), ...event }));
78	}
79	
80	/**
81	 * Option B — Pre-flight toolchain check.
82	 *
83	 * Detects which package manager / runtime the repo needs by inspecting
84	 * well-known lock files and manifests, then verifies each required tool
85	 * exists via `which`. Returns the list of missing tool names (empty = all OK).
86	 *
87	 * This runs before spawning claude so zero tokens are spent when the
88	 * container image is missing a tool.
89	 */
90	const TOOLCHAIN_MARKERS: Array<{ file: string; tool: string }> = [
91	  { file: "yarn.lock",        tool: "yarn"    },
92	  { file: "pnpm-lock.yaml",   tool: "pnpm"    },
93	  { file: "go.mod",           tool: "go"      },
94	  { file: "requirements.txt", tool: "python3" },
95	  { file: "pyproject.toml",   tool: "python3" },
96	  { file: "Cargo.toml",       tool: "cargo"   },
97	];
98	
99	function checkRequiredTools(taskRepoRoot: string): string[] {
100	  const missing: string[] = [];
101	  const checked = new Set<string>();
102	
103	  for (const { file, tool } of TOOLCHAIN_MARKERS) {
104	    if (checked.has(tool)) continue;
105	    if (!existsSync(join(taskRepoRoot, file))) continue;
106	    checked.add(tool);
107	    try {
108	      execSync(`which ${tool}`, { stdio: "pipe" });
109	    } catch {
110	      missing.push(tool);
111	    }
112	  }
113	
114	  return missing;
115	}
116	
117	/**
118	 * Option A — Hard-stop instruction appended to every agent context.
119	 *
120	 * Safety net for tools the pre-flight doesn't know about (e.g. jq, forge,
121	 * custom CLIs). If the agent hits a 127 exit code for any tool, it must
122	 * block immediately instead of burning turns trying workarounds.
123	 */
124	const MISSING_TOOL_INSTRUCTION = `
125	
126	## Hard stop rule — missing tools
127	If any shell command exits with code 127 ("command not found"), do NOT attempt to install it, use an alternative, or work around it in any way. This is a container environment problem that the runtime must fix — the agent cannot fix it. Immediately set the task status to \`blocked\`, set \`blocked_reason\` to \`missing_tool\`, record which tool was missing in \`blocked_details\`, and stop.`;
128	
129	/**
130	 * Copy the workspace CLAUDE.md to ~/.claude/CLAUDE.md so Claude Code picks up
131	 * workspace rules (commit identity, no co-authorship, no GPG, no gh CLI) regardless
132	 * of which implementation repo it is running against.
133	 */
134	function copyWorkspaceClaude(workspaceRoot: string): void {
135	  const src = join(workspaceRoot, "CLAUDE.md");
136	  if (!existsSync(src)) {
137	    emit({ type: "workspace_claude_md_missing", workspace_root: workspaceRoot });
138	    return;
139	  }
140	  const destDir = join(homedir(), ".claude");
141	  mkdirSync(destDir, { recursive: true });
142	  copyFileSync(src, join(destDir, "CLAUDE.md"));
143	}
