455	/**
456	 * Write captured claude stdout to the per-run JSONL log file and commit+push.
457	 * The file contains: run_started event, raw claude output, run_ended event.
458	 * Raw claude output lines are written as-is — they may or may not be JSON.
459	 */
460	function flushLogAndPush(
461	  workspaceRoot: string,
462	  featureId: string,
463	  taskId: string,
464	  taskBranch: string,
465	  runStartIso: string,
466	  gitAuthorEmail: string,
467	  stdout: string,
468	  outcome: string,
469	  sshKeyPath: string | undefined,
470	): void {
471	  const logPath = deriveLogPath(workspaceRoot, featureId, taskId, runStartIso);
472	  mkdirSync(featureLogsDirPath(workspaceRoot, featureId, taskId), { recursive: true });
473	
474	  // Header event — written synchronously so partial logs are still useful.
475	  appendFileSync(
476	    logPath,
477	    JSON.stringify({ at: runStartIso, by: gitAuthorEmail, type: "run_started" }) + "\n",
478	  );
479	
480	  // Raw claude output (may be plain text or JSON events).
481	  // Redact secrets before writing — curl headers and bash commands in tool_use
482	  // inputs can contain API tokens verbatim.
483	  if (stdout) {
484	    const redacted = redactSecrets(stdout);
485	    appendFileSync(logPath, redacted);
486	    if (!redacted.endsWith("\n")) appendFileSync(logPath, "\n");
487	  }
488	
489	  // Footer event.
490	  appendFileSync(
491	    logPath,
492	    JSON.stringify({ at: new Date().toISOString(), by: gitAuthorEmail, type: "run_ended", details: { outcome } }) + "\n",
493	  );
494	
495	  const logFilename = `${toSafeIso(runStartIso)}.jsonl`;
496	  const relPath = logFileRelPath(featureId, taskId, logFilename);
497	  const gitAuthorName = process.env.GIT_AUTHOR_NAME ?? gitAuthorEmail;
498	  const env = buildGitCommitEnv(gitAuthorEmail, gitAuthorName, sshKeyPath);
499	  const GIT_PUSH_TIMEOUT = 30_000;
500	
501	  // Ensure we are on the feature branch regardless of what Claude's skills
502	  // may have done to the management repo HEAD during execution.
503	  const gitOpts = { env, stdio: "pipe" as const, timeout: GIT_PUSH_TIMEOUT };
504	  execSync(`git -C "${workspaceRoot}" checkout "${taskBranch}"`, gitOpts);
505	  execSync(`git -C "${workspaceRoot}" add "${relPath}"`, gitOpts);
506	  execSync(`git -C "${workspaceRoot}" commit -m "chore: flush task log ${taskId}"`, gitOpts);
507	  execSync(`git -C "${workspaceRoot}" push origin "${taskBranch}"`, gitOpts);
508	}
