1	/**
2	 * T3: GitHub API PR creation and dedup for the management (workspace) repo.
3	 *
4	 * Opens a PR from the task branch to baseBranch on the management repo at
5	 * claim time. If an open PR already exists on the branch, reuses it
6	 * (idempotent — safe to call on re-claim or after a blocked recovery).
7	 *
8	 * HTTP calls use curl via spawnSync (no gh CLI, matching pr-create convention).
9	 * Authentication: Authorization: token <githubToken>.
10	 * JSON bodies are passed as array args to spawnSync — no shell interpolation.
11	 */
12	
13	import { execSync, spawnSync } from "node:child_process";
14	import { readFileSync, writeFileSync } from "node:fs";
15	import { parse as parseYaml, stringify as yamlStringify } from "yaml";
16	import type { Task } from "../types/task.js";
17	import { taskYamlAbsPath, taskYamlRelPath } from "../paths.js";
18	import { buildGitCommitEnv } from "../git-env.js";
19	
20	// ── Public types ──────────────────────────────────────────────────────────────
21	
22	export interface OpenWorkspacePrOpts {
23	  /** Absolute path to the management (workspace) repo root. */
24	  workspaceRoot: string;
25	  /** Feature directory ID (e.g. "task-branch-lifecycle"). */
26	  featureId: string;
27	  /** Task ID (e.g. "T3"). */
28	  taskId: string;
29	  /** Task branch name, e.g. "feature/task-branch-lifecycle-T3". */
30	  branch: string;
31	  /** PR target branch, e.g. "main". */
32	  baseBranch: string;
33	  /** GitHub personal access token. */
34	  githubToken: string;
35	  /** GitHub repo owner, parsed from workspace.yaml management repo SSH URL. */
36	  repoOwner: string;
37	  /** GitHub repo name, parsed from workspace.yaml management repo SSH URL. */
38	  repoName: string;
39	  /** GIT_AUTHOR_EMAIL for the workspace_pr commit. Defaults to "agent@unknown". */
40	  gitAuthorEmail?: string;
41	  /** GIT_AUTHOR_NAME for the workspace_pr commit. Defaults to gitAuthorEmail. */
42	  gitAuthorName?: string;
43	  /** SSH private key path for git push. Omit to rely on ambient SSH config. */
44	  sshKeyPath?: string;
45	  /**
46	   * Skip git add/commit/push for the YAML update.
47	   * The YAML is still written to disk.
48	   * Intended for unit tests that do not set up a real git repo.
49	   */
50	  skipGit?: boolean;
51	}
52	
53	export interface OpenWorkspacePrResult {
54	  prUrl: string;
55	  prNumber: number;
56	  /** True if an existing open PR was reused; false if a new PR was created. */
57	  alreadyExisted: boolean;
58	}
59	
60	// ── parseGitHubCoords ─────────────────────────────────────────────────────────
61	
62	/**
63	 * Extract GitHub owner and repo name from an SSH remote URL.
64	 *
65	 * Accepts:
66	 *   git@github.com:owner/repo.git
67	 *   git@github.com:owner/repo
68	 *
69	 * Throws a descriptive error for non-matching URLs (e.g. HTTPS or malformed).
70	 */
71	export function parseGitHubCoords(sshUrl: string): { owner: string; repo: string } {
72	  const match = /git@github\.com:([^/]+)\/([^.]+)(?:\.git)?$/.exec(sshUrl);
73	  if (!match) {
74	    throw new Error(
75	      `Cannot parse GitHub owner/repo from URL: "${sshUrl}". ` +
76	        `Expected SSH format: git@github.com:<owner>/<repo>[.git]`,
77	    );
78	  }
79	  return { owner: match[1], repo: match[2] };
80	}
81	
82	// ── Internal helpers ──────────────────────────────────────────────────────────
83	
84	interface PrListItem {
85	  html_url: string;
86	  number: number;
87	}
88	
89	/**
90	 * Call the GitHub REST API via curl. Arguments are passed as an array to
91	 * spawnSync to avoid shell injection.
92	 *
93	 * Throws if curl fails or the response is not valid JSON.
94	 */
95	function curlJson(args: string[]): unknown {
96	  const result = spawnSync("curl", args, {
97	    encoding: "utf-8",
98	    stdio: ["ignore", "pipe", "pipe"],
99	  });
100	  if (result.error) throw result.error;
101	  const stdout = result.stdout ?? "";
102	  if (!stdout.trim()) {
103	    throw new Error(
104	      `curl returned empty response. stderr: ${result.stderr ?? ""}`,
105	    );
106	  }
107	  try {
108	    return JSON.parse(stdout);
109	  } catch {
110	    throw new Error(`curl response is not valid JSON: ${stdout}`);
111	  }
112	}
113	
114	
115	// ── Public API ────────────────────────────────────────────────────────────────
116	
117	/**
118	 * Open a PR on the management repo from the task branch to baseBranch.
119	 *
120	 * Idempotent: if an open PR already exists on the branch it is reused rather
121	 * than creating a duplicate.
122	 *
123	 * On success, writes `task.workspace_pr = { url, status: "open" }` to the
124	 * task YAML and commits+pushes the change to the task branch (unless
125	 * `skipGit` is true).
126	 */
127	export async function openWorkspacePr(
128	  opts: OpenWorkspacePrOpts,
129	): Promise<OpenWorkspacePrResult> {
130	  const {
131	    workspaceRoot,
132	    featureId,
133	    taskId,
134	    branch,
135	    baseBranch,
136	    githubToken,
137	    repoOwner,
138	    repoName,
139	    gitAuthorEmail = "agent@unknown",
140	    gitAuthorName = gitAuthorEmail,
141	    sshKeyPath,
142	    skipGit = false,
143	  } = opts;
144	
145	  // Read task YAML upfront: title needed for PR subject; object reused for write.
146	  const taskPath = taskYamlAbsPath(workspaceRoot, featureId, taskId);
147	  const task = parseYaml(readFileSync(taskPath, "utf-8")) as Task;
148	
149	  // ── 1. Check for existing open PR ─────────────────────────────────────────
150	  const encodedHead = encodeURIComponent(`${repoOwner}:${branch}`);
151	  const listUrl =
152	    `https://api.github.com/repos/${repoOwner}/${repoName}/pulls` +
153	    `?head=${encodedHead}&state=open`;
154	
155	  const pullsList = curlJson([
156	    "-s",
157	    "-H",
158	    `Authorization: token ${githubToken}`,
159	    "-H",
160	    "Accept: application/vnd.github+json",
161	    listUrl,
162	  ]) as PrListItem[];
163	
164	  let prUrl: string;
165	  let prNumber: number;
166	  let alreadyExisted: boolean;
167	
168	  if (Array.isArray(pullsList) && pullsList.length > 0) {
169	    // ── 2a. Reuse existing open PR ─────────────────────────────────────────
170	    prUrl = pullsList[0].html_url;
171	    prNumber = pullsList[0].number;
172	    alreadyExisted = true;
173	  } else {
174	    // ── 2b. Create new PR ──────────────────────────────────────────────────
175	    const prTitle = `feat(${taskId}): ${task.title}`;
176	    const prBody =
177	      `Task: ${taskId}\nFeature: ${featureId}\nBranch: \`${branch}\``;
178	    const createUrl =
179	      `https://api.github.com/repos/${repoOwner}/${repoName}/pulls`;
180	    const requestBody = JSON.stringify({
181	      title: prTitle,
182	      body: prBody,
183	      head: branch,
184	      base: baseBranch,
185	    });
186	
187	    const created = curlJson([
188	      "-s",
189	      "-X",
190	      "POST",
191	      "-H",
192	      `Authorization: token ${githubToken}`,
193	      "-H",
194	      "Accept: application/vnd.github+json",
195	      "-H",
196	      "Content-Type: application/json",
197	      "-d",
198	      requestBody,
199	      createUrl,
200	    ]) as { html_url?: string; number?: number };
201	
202	    if (!created.html_url || !created.number) {
203	      throw new Error(
204	        `GitHub API PR creation failed. Response: ${JSON.stringify(created)}`,
205	      );
206	    }
207	
208	    prUrl = created.html_url;
209	    prNumber = created.number;
210	    alreadyExisted = false;
211	  }
212	
213	  // ── 3. Write workspace_pr to task YAML ────────────────────────────────────
214	  task.workspace_pr = { url: prUrl, status: "open" };
215	  writeFileSync(taskPath, yamlStringify(task), "utf-8");
216	
217	  // ── 4. Commit and push YAML update to task branch ─────────────────────────
218	  if (!skipGit) {
219	    const env = buildGitCommitEnv(gitAuthorEmail, gitAuthorName, sshKeyPath);
220	    const relPath = taskYamlRelPath(featureId, taskId);
221	
222	    execSync(`git -C "${workspaceRoot}" add "${relPath}"`, {
223	      env,
224	      stdio: "pipe",
225	    });
226	    execSync(
227	      `git -C "${workspaceRoot}" commit -m "chore(${taskId}): open workspace PR"`,
228	      { env, stdio: "pipe" },
229	    );
230	    execSync(`git -C "${workspaceRoot}" push origin "${branch}"`, {
231	      env,
232	      stdio: "pipe",
233	    });
234	  }
235	
236	  return { prUrl, prNumber, alreadyExisted };
237	}
