1	/**
2	 * Zero-token eligibility matcher.
3	 *
4	 * Determines which tasks in a workspace are eligible for this agent to claim.
5	 * Uses only filesystem reads and regex — no LLM calls, zero Anthropic tokens.
6	 *
7	 * Eligibility criteria (all must pass):
8	 *   1. task.status === "ready"
9	 *   2. All task IDs in depends_on are "done" (within the same feature)
10	 *   3. task.repo is one of the repos declared in workspace.yaml
11	 *   4. The workspace's management repo URL is in agent.watches
12	 *   5. Every slug in ### Required skills exists as a directory under
13	 *      workflowRoot/technical_skills/<slug>/
14	 *
15	 * Tasks that fail criterion 5 emit a `task_skipped_missing_skill` event to
16	 * stdout and remain "ready" (not blocked) — the issue is a workflow-repo
17	 * authoring error, not a task-scope error.
18	 */
19	
20	import { readFileSync, existsSync, readdirSync } from "node:fs";
21	import { join } from "node:path";
22	import { parse as parseYaml } from "yaml";
23	import type { AgentConfig } from "../config/validate-agent-yaml.js";
24	import type { Task } from "../types/task.js";
25	import { parseTasksMd } from "./parse-tasks-md.js";
26	import {
27	  workspaceYamlPath,
28	  featuresRoot,
29	  TASKS_DIR,
30	  TASKS_MD,
31	  skillDirPath,
32	  localSkillDirPath,
33	  taskBranchName,
34	  taskYamlRelPath,
35	} from "../paths.js";
36	import { tryReadTaskFromBranch } from "../task-branch-state.js";
37	
38	// ---------------------------------------------------------------------------
39	// Workspace config types (minimal — only what the matcher needs)
40	// ---------------------------------------------------------------------------
41	
42	interface WorkspaceRepo {
43	  id: string;
44	  github: string;
45	}
46	
47	interface WorkspaceConfig {
48	  management_repo: string;
49	  repos: WorkspaceRepo[];
50	}
51	
52	// ---------------------------------------------------------------------------
53	// Event types emitted to stdout
54	// ---------------------------------------------------------------------------
55	
56	/** Emitted when a task is skipped because a required skill is missing from the workflow repo. */
57	export interface TaskSkippedMissingSkillEvent {
58	  type: "task_skipped_missing_skill";
59	  taskId: string;
60	  featureId: string;
61	  missingSkills: string[];
62	}
63	
64	function emitSkippedMissingSkill(event: TaskSkippedMissingSkillEvent): void {
65	  console.log(JSON.stringify(event));
66	}
67	
68	// ---------------------------------------------------------------------------
69	// Internal helpers
70	// ---------------------------------------------------------------------------
71	
72	/** Parse workspace.yaml from the given workspace root. */
73	function loadWorkspaceConfig(workspaceRoot: string): WorkspaceConfig {
74	  const yamlPath = workspaceYamlPath(workspaceRoot);
75	  if (!existsSync(yamlPath)) {
76	    throw new Error(`workspace.yaml not found at ${yamlPath}`);
77	  }
78	  return parseYaml(readFileSync(yamlPath, "utf-8")) as WorkspaceConfig;
79	}
80	
81	/** Return true if the skill directory exists in the workflow repo or the workspace-local override. */
82	function skillDirExists(workflowRoot: string, workspaceRoot: string, slug: string): boolean {
83	  return existsSync(skillDirPath(workflowRoot, slug)) || existsSync(localSkillDirPath(workspaceRoot, slug));
84	}
85	
86	/** Return the numeric part of a task ID for sorting (T5 → 5). */
87	function taskNumericId(taskId: string): number {
88	  return parseInt(taskId.replace(/^T/, ""), 10);
89	}
90	
91	// ---------------------------------------------------------------------------
92	// Feature scanning
93	// ---------------------------------------------------------------------------
94	
95	interface FeatureTaskEntry {
96	  task: Task;
97	  featureId: string;
98	  requiredSkills: string[];
99	}
100	
101	/**
102	 * Load all tasks from a single feature directory.
103	 * Returns one entry per task YAML file found under tasks/.
104	 */
105	function loadFeatureTasks(
106	  featurePath: string,
107	  featureId: string,
108	): FeatureTaskEntry[] {
109	  const tasksDir = join(featurePath, TASKS_DIR);
110	  if (!existsSync(tasksDir)) return [];
111	
112	  // Parse tasks.md skill map (may be absent — treated as "all tasks have no skills")
113	  const tasksMdPath = join(featurePath, TASKS_MD);
114	  const skillMap = existsSync(tasksMdPath)
115	    ? parseTasksMd(readFileSync(tasksMdPath, "utf-8"))
116	    : {};
117	
118	  // Load T*.yaml files
119	  let taskFiles: string[];
120	  try {
121	    taskFiles = readdirSync(tasksDir).filter((f) => /^T\d+\.yaml$/.test(f));
122	  } catch {
123	    return [];
124	  }
125	
126	  return taskFiles.flatMap((fileName) => {
127	    let task: Task;
128	    try {
129	      task = parseYaml(
130	        readFileSync(join(tasksDir, fileName), "utf-8"),
131	      ) as Task;
132	    } catch (e: unknown) {
133	      process.stderr.write(
134	        JSON.stringify({ type: "task_yaml_parse_error", featureId, file: fileName, details: String(e) }) + "\n",
135	      );
136	      return [];
137	    }
138	
139	    const skillEntry = skillMap[task.id];
140	    // skillEntry undefined → task not in tasks.md (treated as no skills required)
141	    // skillEntry present → use its requiredSkills
142	    // Task omitted from map (malformed) → skillEntry is undefined here too, but
143	    // parseTasksMd already emitted the warning; we treat it as null so the matcher skips it
144	    const requiredSkills = skillEntry !== undefined ? skillEntry.requiredSkills : [];
145	
146	    return [{ task, featureId, requiredSkills }];
147	  });
148	}
149	
150	/**
151	 * Scan all features under workspaceRoot/docs/features/.
152	 * Returns all task entries found.
153	 */
154	function scanAllFeatures(workspaceRoot: string): FeatureTaskEntry[] {
155	  const docsPath = featuresRoot(workspaceRoot);
156	  if (!existsSync(docsPath)) return [];
157	
158	  let featureDirs: string[];
159	  try {
160	    featureDirs = readdirSync(docsPath, { withFileTypes: true })
161	      .filter((e) => e.isDirectory())
162	      .map((e) => e.name);
163	  } catch {
164	    return [];
165	  }
166	
167	  const entries: FeatureTaskEntry[] = [];
168	  for (const featureId of featureDirs) {
169	    const featurePath = join(docsPath, featureId);
170	    entries.push(...loadFeatureTasks(featurePath, featureId));
171	  }
172	  return entries;
173	}
174	
175	// ---------------------------------------------------------------------------
176	// Public API
177	// ---------------------------------------------------------------------------
178	
179	/** A task that passed all eligibility criteria, with its owning feature ID. */
180	export interface EligibleTask {
181	  task: Task;
182	  featureId: string;
183	}
184	
185	/**
186	 * Find all tasks in the given workspace that this agent is eligible to claim.
187	 *
188	 * @param agentConfig   - Validated agent configuration (watches, budget, etc.).
189	 * @param workspaceRoot - Local filesystem path to the cloned workspace repo.
190	 * @param workflowRoot  - Local filesystem path to the cloned workflow repo
191	 *                        (contains technical_skills/).
192	 * @returns Eligible tasks sorted by numeric task ID ascending. Empty array if
193	 *          the workspace is not watched or has no eligible tasks.
194	 */
195	export function findEligibleTasks(
196	  agentConfig: AgentConfig,
197	  workspaceRoot: string,
198	  workflowRoot: string,
199	): EligibleTask[] {
200	  // ── 1. Load workspace config ────────────────────────────────────────────
201	  const workspaceConfig = loadWorkspaceConfig(workspaceRoot);
202	
203	  // ── 2. Watches match ────────────────────────────────────────────────────
204	  // Verify this workspace's management repo is in agent.watches.
205	  const managementRepoId = workspaceConfig.management_repo;
206	  const managementRepo = workspaceConfig.repos.find(
207	    (r) => r.id === managementRepoId,
208	  );
209	  if (!managementRepo) {
210	    throw new Error(
211	      `management_repo "${managementRepoId}" declared in workspace.yaml but not found in repos[]`,
212	    );
213	  }
214	
215	  const watchedUrls = new Set(agentConfig.watches);
216	  if (!watchedUrls.has(managementRepo.github)) {
217	    // This workspace is not watched by this agent — no eligible tasks
218	    return [];
219	  }
