1	/**
2	 * Merge-completion handler.
3	 *
4	 * When the in_review poll reports `merged: true` for a task's implementation
5	 * PR, this handler:
6	 *
7	 *   1. Reads the live task state from the feature branch (idempotency guard).
8	 *   2. Checks out and syncs the feature branch on the management repo.
9	 *   3. Updates the task YAML: status → done, pr.status → merged, done log entry.
10	 *   4. Applies the auto-ready rule: scans sibling task YAMLs in the same
11	 *      feature and transitions todo → ready for any whose depends_on list is
12	 *      now fully satisfied.
13	 *   5. Commits all YAML changes (completing task + newly-ready tasks) in one
14	 *      commit and pushes to the feature branch.  On push rejection, attempts
15	 *      a fetch+rebase recovery; if the rebase has conflicts, spawns Claude to
16	 *      resolve the YAML markers.  On persistent failure, emits
17	 *      pr_merge_done_blocked and skips the workspace PR merge.
18	 *   6. Merges the management-repo PR (workspace_pr) via the GitHub REST API.
19	 *      Errors here are non-fatal — the task YAML done state is preserved.
20	 */
21	
22	import { execSync, spawnSync, spawn } from "node:child_process";
23	import { readFileSync, writeFileSync, readdirSync } from "node:fs";
24	import { join } from "node:path";
25	import { parse as parseYaml, stringify as yamlStringify } from "yaml";
26	import type { Task } from "../types/task.js";
27	import { taskYamlAbsPath, taskYamlRelPath, featuresRoot, TASKS_DIR } from "../paths.js";
28	import type { PrStatusResult, WorkspacePrRecovery } from "./check-in-review-prs.js";
29	import { parsePrUrl } from "./check-in-review-prs.js";
30	import { buildGitCommitEnv } from "../git-env.js";
31	import { tryReadTaskFromBranch } from "../task-branch-state.js";
32	import { taskBranchName } from "../paths.js";
33	
34	// ── Public types ──────────────────────────────────────────────────────────────
35	
36	export interface HandleMergedPrsOptions {
37	  /** Results from checkInReviewPrs — only those with merged === true are processed. */
38	  prResults: PrStatusResult[];
39	  /** Absolute path to the management (workspace) repo root. */
40	  workspaceRoot: string;
41	  /** GitHub owner of the management repo (for workspace PR merge call). */
42	  mgmtRepoOwner: string;
43	  /** GitHub repo name of the management repo. */
44	  mgmtRepoName: string;
45	  /** Base branch of the management repo (default: "main"). Used for rebase-before-merge. */
46	  mgmtBaseBranch?: string;
47	  /** GitHub personal access token. */
48	  githubToken: string;
49	  /** GIT_AUTHOR_EMAIL for commits and log entries. */
50	  gitAuthorEmail: string;
51	  /** GIT_AUTHOR_NAME for commits. Defaults to gitAuthorEmail. */
52	  gitAuthorName: string;
53	  /** SSH private key path for git push operations. */
54	  sshKeyPath?: string;
55	  /** Structured event emitter for observability. */
56	  emit: (event: Record<string, unknown>) => void;
57	  /**
58	   * Optional override for spawning Claude to resolve YAML conflict markers.
59	   * Receives the prompt string, the workspace cwd, and the process env.
60	   * Returns true if resolution succeeded, false otherwise.
61	   */
62	  invokeClaudeForResolution?: (
63	    prompt: string,
64	    cwd: string,
65	    env: NodeJS.ProcessEnv,
66	  ) => Promise<boolean>;
67	  /**
68	   * Optional override for checking whether the workspace PR is mergeable.
69	   * Returns true (mergeable), false (conflicting — skip merge), or null (unknown — proceed).
70	   * Defaults to querying the GitHub REST API.
71	   */
72	  checkMergeability?: (
73	    owner: string,
74	    repo: string,
75	    pullNumber: number,
76	    githubToken: string,
77	  ) => boolean | null;
78	}
79	
80	// ── Internal helpers ──────────────────────────────────────────────────────────
81	
82	/**
83	 * Query the GitHub REST API for the current mergeability of a PR.
84	 * Returns true (MERGEABLE), false (CONFLICTING), or null (UNKNOWN / error).
85	 */
86	export function fetchPrMergeability(
87	  mgmtRepoOwner: string,
88	  mgmtRepoName: string,
89	  prNumber: number,
90	  githubToken: string,
91	): boolean | null {
92	  const url = `https://api.github.com/repos/${mgmtRepoOwner}/${mgmtRepoName}/pulls/${prNumber}`;
93	  const result = spawnSync(
94	    "curl",
95	    [
96	      "-s", "-X", "GET",
97	      "-H", `Authorization: token ${githubToken}`,
98	      "-H", "Accept: application/vnd.github+json",
99	      url,
100	    ],
101	    { encoding: "utf-8", stdio: ["ignore", "pipe", "pipe"] },
102	  );
103	
104	  if (result.error || !result.stdout?.trim()) return null;
105	  try {
106	    const data = JSON.parse(result.stdout) as { mergeable?: boolean | null };
107	    return data.mergeable ?? null;
108	  } catch {
109	    return null;
110	  }
111	}
112	
113	/**
114	 * Call the GitHub REST API to merge a pull request.
115	 * Returns success/failure with full response details on failure.
116	 */
117	export function mergeWorkspacePrViaApi(
118	  mgmtRepoOwner: string,
119	  mgmtRepoName: string,
120	  prNumber: number,
121	  githubToken: string,
122	): { success: boolean; details: string } {
123	  const url = `https://api.github.com/repos/${mgmtRepoOwner}/${mgmtRepoName}/pulls/${prNumber}/merge`;
124	  const body = JSON.stringify({ merge_method: "squash" });
125	
126	  const result = spawnSync(
127	    "curl",
128	    [
129	      "-s", "-X", "PUT",
130	      "-H", `Authorization: token ${githubToken}`,
131	      "-H", "Accept: application/vnd.github+json",
132	      "-H", "Content-Type: application/json",
133	      "-d", body,
134	      url,
135	    ],
136	    { encoding: "utf-8", stdio: ["ignore", "pipe", "pipe"] },
137	  );
138	
139	  if (result.error) {
140	    return { success: false, details: String(result.error) };
141	  }
142	  const stdout = result.stdout ?? "";
143	  if (!stdout.trim()) {
144	    return { success: false, details: `curl returned empty response. stderr: ${result.stderr ?? ""}` };
145	  }
146	
147	  try {
148	    const data = JSON.parse(stdout) as { merged?: boolean; message?: string };
149	    if (data.merged === true) {
150	      return { success: true, details: "" };
151	    }
152	    return { success: false, details: JSON.stringify(data) };
153	  } catch {
154	    return { success: false, details: `Non-JSON response: ${stdout}` };
155	  }
156	}
157	
158	/**
159	 * Return files that currently have conflict markers via `git diff --name-only --diff-filter=U`.
160	 */
161	function listConflictedFiles(
162	  repoRoot: string,
163	  env: NodeJS.ProcessEnv,
164	): string[] {
165	  try {
166	    const output = execSync(
167	      `git -C "${repoRoot}" diff --name-only --diff-filter=U`,
168	      { env, encoding: "utf-8", stdio: ["ignore", "pipe", "pipe"] },
169	    ).trim();
170	    return output ? output.split("\n") : [];
171	  } catch {
172	    return [];
173	  }
174	}
175	
176	/**
177	 * Build a Claude prompt for resolving YAML task file conflict markers.
178	 * Instructs Claude to keep the local done/ready status and merge log arrays.
179	 */
180	function buildYamlConflictResolutionPrompt(
181	  repoRoot: string,
182	  conflictedFiles: string[],
183	): string {
184	  const fileList = conflictedFiles.map((f) => `- ${f}`).join("\n");
185	  return (
186	    `You are resolving git merge conflicts in YAML task files in the repository at ${repoRoot}.\n` +
187	    `The following files contain conflict markers (<<<<<<<, =======, >>>>>>>):\n\n` +
188	    fileList +
189	    `\n\nFor each file:\n` +
190	    `1. Read the file contents (which include conflict markers).\n` +
191	    `2. Resolve the conflict markers using these rules:\n` +
192	    `   - Keep the LOCAL (<<<<<<< HEAD) values for status, pr.status, execution fields.\n` +
193	    `   - Merge the log arrays from BOTH sides — include all entries from both HEAD and the incoming branch, sorted by the "at" timestamp.\n` +
194	    `   - For all other scalar fields, keep the LOCAL value.\n` +
195	    `3. Write the fully resolved YAML content back to disk.\n\n` +
196	    `IMPORTANT:\n` +
197	    `- Do NOT run git add or git commit — only write the resolved file contents.\n` +
198	    `- Do NOT modify any files that are not listed above.\n` +
199	    `- After writing all files, respond with a brief summary of what was resolved.`
200	  );
201	}
202	
203	/**
204	 * Default implementation: spawns Claude CLI to resolve YAML conflict markers.
205	 */
206	async function defaultInvokeClaudeForResolution(
207	  prompt: string,
208	  cwd: string,
209	  env: NodeJS.ProcessEnv,
210	): Promise<boolean> {
211	  return new Promise((resolve) => {
212	    const child = spawn(
213	      "claude",
214	      [
215	        "-p", prompt,
216	        "--max-turns", "5",
217	        "--output-format", "stream-json",
218	        "--verbose",
219	        "--dangerously-skip-permissions",
220	      ],
221	      { cwd, env, stdio: ["ignore", "pipe", "pipe"] },
222	    );
223	
224	    child.stdout.pipe(process.stdout);
225	    child.stderr.pipe(process.stderr);
226	
227	    child.on("close", (code) => resolve(code === 0));
228	    child.on("error", () => resolve(false));
229	  });
230	}
231	
232	// ── Public API ────────────────────────────────────────────────────────────────
233	
234	/**
235	 * Iterate poll results where `merged === true` and close out each task:
236	 * mark done, activate unblocked dependents, and merge the workspace PR.
237	 */
238	export async function handleMergedPrs(opts: HandleMergedPrsOptions): Promise<void> {
239	  const {
240	    prResults,
241	    workspaceRoot,
242	    mgmtRepoOwner,
243	    mgmtRepoName,
244	    mgmtBaseBranch = "main",
245	    githubToken,
246	    gitAuthorEmail,
247	    gitAuthorName,
248	    sshKeyPath,
249	    emit,
250	  } = opts;
251	
252	  const mergedResults = prResults.filter((r) => r.merged === true);
253	  if (mergedResults.length === 0) return;
254	
255	  const env = buildGitCommitEnv(gitAuthorEmail, gitAuthorName, sshKeyPath);
256	  const invoker = opts.invokeClaudeForResolution ?? defaultInvokeClaudeForResolution;
257	
258	  for (const result of mergedResults) {
259	    const { taskId, featureId } = result;
260	    const taskBranch = taskBranchName(featureId, taskId);
261	    const relPath = taskYamlRelPath(featureId, taskId);
262	
263	    // ── 1. Idempotency guard: read live task state from feature branch ─────────
264	    const liveTask = tryReadTaskFromBranch(workspaceRoot, taskBranch, relPath);
265	    if (!liveTask) {
266	      emit({
267	        type: "pr_merge_skip",
268	        task_id: taskId,
269	        feature_id: featureId,
270	        reason: "task_branch_not_found",
271	      });
272	      continue;
273	    }
274	
275	    if (liveTask.status !== "in_review") {
276	      emit({
277	        type: "pr_merge_skip",
278	        task_id: taskId,
279	        feature_id: featureId,
280	        reason: `task_already_${liveTask.status}`,
281	      });
282	      continue;
283	    }
284	
285	    // ── 2. Checkout and sync feature branch ───────────────────────────────────
286	    try {
287	      execSync(`git -C "${workspaceRoot}" fetch origin`, { env, stdio: "pipe" });
288	      execSync(`git -C "${workspaceRoot}" checkout "${taskBranch}"`, { env, stdio: "pipe" });
289	      execSync(`git -C "${workspaceRoot}" pull --rebase origin "${taskBranch}"`, { env, stdio: "pipe" });
290	    } catch (e) {
291	      emit({
292	        type: "pr_merge_done_blocked",
293	        task_id: taskId,
294	        feature_id: featureId,
295	        reason: "branch_sync_failed",
296	        details: String(e),
297	      });
298	      continue;
299	    }
300	
301	    // ── 3. Update task YAML on disk ───────────────────────────────────────────
302	    const now = new Date().toISOString();
303	    let task: Task;
304	    try {
305	      task = parseYaml(
306	        readFileSync(taskYamlAbsPath(workspaceRoot, featureId, taskId), "utf-8"),
307	      ) as Task;
308	    } catch (e) {
309	      emit({
310	        type: "pr_merge_done_blocked",
311	        task_id: taskId,
312	        feature_id: featureId,
313	        reason: "task_yaml_read_failed",
314	        details: String(e),
315	      });
316	      continue;
317	    }
318	
319	    // Second idempotency check after checkout (guards against races).
320	    if (task.status !== "in_review") {
321	      emit({
322	        type: "pr_merge_skip",
323	        task_id: taskId,
324	        feature_id: featureId,
325	        reason: `task_already_${task.status}_after_checkout`,
326	      });
327	      continue;
328	    }
329	
330	    task.status = "done";
331	    task.pr = { ...task.pr, status: "merged" };
332	    task.execution.last_updated_by = gitAuthorEmail;
333	    task.execution.last_updated_at = now;
334	    task.log.push({
335	      action: "done",
336	      by: gitAuthorEmail,
337	      at: now,
338	      note: "Implementation PR merged — automated close-out by pr-merge loop.",
339	    });
340	
341	    writeFileSync(
342	      taskYamlAbsPath(workspaceRoot, featureId, taskId),
343	      yamlStringify(task),
344	      "utf-8",
345	    );
346	
347	    // ── 4. Auto-ready rule: activate sibling tasks whose deps are now satisfied
348	    const allRelPaths: string[] = [relPath];
349	    const tasksDir = join(featuresRoot(workspaceRoot), featureId, TASKS_DIR);
350	
351	    let siblingFiles: string[] = [];
352	    try {
353	      siblingFiles = readdirSync(tasksDir).filter(
354	        (f) => /^T\d+\.yaml$/.test(f) && f !== `${taskId}.yaml`,
355	      );
356	    } catch { /* best-effort — skip auto-ready if tasks dir unreadable */ }
357	
358	    // Build a status map for dependency resolution.
359	    // Start with the just-completed task (now done).
360	    const taskStatusMap = new Map<string, string>([[taskId, "done"]]);
361	    for (const sibFile of siblingFiles) {
362	      try {
363	        const sibTask = parseYaml(
364	          readFileSync(join(tasksDir, sibFile), "utf-8"),
365	        ) as Task;
366	        taskStatusMap.set(sibTask.id, sibTask.status);
367	      } catch { /* skip unreadable files */ }
368	    }
369	
370	    for (const sibFile of siblingFiles) {
371	      try {
372	        const sibPath = join(tasksDir, sibFile);
373	        const sibTask = parseYaml(readFileSync(sibPath, "utf-8")) as Task;
374	
375	        // Only consider todo tasks that depend on the just-completed task.
376	        if (sibTask.status !== "todo") continue;
377	        if (!Array.isArray(sibTask.depends_on) || !sibTask.depends_on.includes(taskId)) continue;
378	
379	        // All deps must now be done.
380	        const allDepsDone = sibTask.depends_on.every(
381	          (depId) => taskStatusMap.get(depId) === "done",
382	        );
383	        if (!allDepsDone) continue;
384	
385	        const sibNow = new Date().toISOString();
386	        sibTask.status = "ready";
387	        sibTask.log.push({
388	          action: "ready",
389	          by: gitAuthorEmail,
390	          at: sibNow,
391	          note: `Task activated — dependency ${taskId} merged and marked done.`,
392	        });
393	
394	        writeFileSync(sibPath, yamlStringify(sibTask), "utf-8");
395	        allRelPaths.push(taskYamlRelPath(featureId, sibTask.id));
396	
397	        emit({
398	          type: "task_auto_readied",
399	          task_id: sibTask.id,
400	          feature_id: featureId,
401	          activated_by: taskId,
402	        });
403	      } catch { /* skip individual sibling errors */ }
404	    }
405	
406	    // ── 5. Commit + push with rebase-and-resolve on rejection ─────────────────
407	    let pushSucceeded = false;
408	
409	    try {
410	      for (const rp of allRelPaths) {
411	        execSync(`git -C "${workspaceRoot}" add "${rp}"`, { env, stdio: "pipe" });
412	      }
413	      execSync(
414	        `git -C "${workspaceRoot}" commit -m "chore(${taskId}): mark done + activate unblocked tasks"`,
415	        { env, stdio: "pipe" },
416	      );
417	    } catch (e) {
418	      emit({
419	        type: "pr_merge_done_blocked",
420	        task_id: taskId,
421	        feature_id: featureId,
422	        reason: "commit_failed",
423	        details: String(e),
424	      });
425	      continue;
426	    }
427	
428	    const firstPush = spawnSync(
429	      "git",
430	      ["-C", workspaceRoot, "push", "origin", taskBranch],
431	      { env, encoding: "utf-8" },
432	    );
433	
434	    if (firstPush.status === 0) {
435	      pushSucceeded = true;
436	    } else {
437	      // Push rejected — attempt fetch + rebase recovery.
438	      try {
439	        execSync(`git -C "${workspaceRoot}" fetch origin`, { env, stdio: "pipe" });
440	      } catch (e) {
441	        emit({
442	          type: "pr_merge_done_blocked",
443	          task_id: taskId,
444	          feature_id: featureId,
445	          reason: "fetch_failed_during_push_recovery",
446	          details: String(e),
447	        });
448	        continue;
449	      }
450	
451	      const rebaseResult = spawnSync(
452	        "git",
453	        ["-C", workspaceRoot, "rebase", `origin/${taskBranch}`],
454	        { env, encoding: "utf-8" },
455	      );
456	
457	      if (rebaseResult.status === 0) {
458	        // Clean rebase — retry push.
459	        const retryPush = spawnSync(
460	          "git",
461	          ["-C", workspaceRoot, "push", "origin", taskBranch],
462	          { env, encoding: "utf-8" },
463	        );
464	        if (retryPush.status === 0) {
465	          pushSucceeded = true;
466	        } else {
467	          emit({
468	            type: "pr_merge_done_blocked",
469	            task_id: taskId,
470	            feature_id: featureId,
471	            reason: "push_rejected_after_clean_rebase",
472	            details: retryPush.stderr ?? "",
473	          });
474	          continue;
475	        }
476	      } else {
477	        // Conflicted rebase — spawn Claude to resolve YAML conflict markers.
478	        const conflictedFiles = listConflictedFiles(workspaceRoot, env);
479	        const prompt = buildYamlConflictResolutionPrompt(workspaceRoot, conflictedFiles);
480	
481	        let resolveSucceeded = false;
482	        try {
483	          resolveSucceeded = await invoker(prompt, workspaceRoot, env);
484	        } catch { /* fall through to block */ }
485	
486	        if (resolveSucceeded) {
