interface RagResult {
  content: string;
  score: number;
  metadata: Record<string, unknown>;
}

interface RagQueryResponse {
  results: RagResult[];
}

/**
 * Outcome of the runtime's pre-flight RAG fetch.
 *
 * The runtime is the authoritative writer of the `rag_pre_flight` task-log
 * entry — the agent cannot forge or skip this. `summary` follows a fixed
 * vocabulary so the entry is machine-checkable:
 *
 *   - `Retrieved <N> chunks: <topics>`         — success (≥1 chunk)
 *   - `tool_unavailable: <reason>`             — MCP_RAG_URL unset / no server
 *   - `tool_call_failed: <error>`              — fetch threw / non-2xx
 *   - `query_returned_no_chunks`               — fetch ok, empty results
 */
export interface RagPreFlight {
  /** Markdown block to inject into the agent prompt. Empty when no chunks. */
  block: string;
  /** Deterministic summary for the task-log entry. Never free-form. */
  summary: string;
  /** True iff at least one chunk was retrieved. */
  injected: boolean;
}

/**
 * Fetch RAG context from the rag-server REST endpoint before invoking Claude.
 * Always resolves with a `RagPreFlight` describing what happened — never throws,
 * never returns ambiguous "" so the runtime can write an honest audit entry.
 */
export async function fetchRagContext(
  ragBaseUrl: string | undefined,
  query: string,
  workspaceId: string,
  topK = 5,
): Promise<RagPreFlight> {
  if (!ragBaseUrl) {
    return {
      block: "",
      summary: "tool_unavailable: MCP_RAG_URL not set",
      injected: false,
    };
  }

  let response: Response;
  try {
    response = await fetch(`${ragBaseUrl}/query`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ query, workspace_id: workspaceId, top_k: topK }),
      signal: AbortSignal.timeout(3000),
    });
  } catch (err) {
    const msg = err instanceof Error ? err.message : String(err);
    return {
      block: "",
      summary: `tool_call_failed: ${msg}`,
      injected: false,
    };
  }

  if (!response.ok) {
    return {
      block: "",
      summary: `tool_call_failed: HTTP ${response.status}`,
      injected: false,
    };
  }

  let data: RagQueryResponse;
  try {
    data = (await response.json()) as RagQueryResponse;
  } catch (err) {
    const msg = err instanceof Error ? err.message : String(err);
    return {
      block: "",
      summary: `tool_call_failed: invalid JSON — ${msg}`,
      injected: false,
    };
  }

  if (!data.results || data.results.length === 0) {
    return {
      block: "",
      summary: "query_returned_no_chunks",
      injected: false,
    };
  }

  const blocks = data.results.map((r) => `${r.content}\n---`).join("\n");
  const block = `## RAG Context\n\n${blocks}\n`;

  // Build a short topic list from the top results. Prefer a source path field,
  // then any title-like metadata; fall back to a leading content snippet so the
  // summary is always informative even when the RAG server's metadata schema
  // doesn't expose path-shaped fields.
  const topics = data.results
    .slice(0, 3)
    .map((r) => {
      const meta = r.metadata ?? {};
      const labelled =
        (meta.source_path as string | undefined) ??
        (meta.source as string | undefined) ??
        (meta.path as string | undefined) ??
        (meta.file_path as string | undefined) ??
        (meta.title as string | undefined) ??
        (meta.document_id as string | undefined) ??
        (meta.url as string | undefined);
      if (labelled) return String(labelled);
      const snippet = (r.content ?? "").trim().slice(0, 40).replace(/\s+/g, " ");
      return snippet ? `"${snippet}..."` : "chunk";
    })
    .join(", ");

  return {
    block,
    summary: `Retrieved ${data.results.length} chunks: ${topics}`,
    injected: true,
  };
}

