1	/**
2	 * T3: Auto-rebase handler.
3	 *
4	 * When the in_review poll (T2) reports `mergeable: false` for a task, this
5	 * handler:
6	 *
7	 *   1. Claims the rebase work via a first-push-wins mechanism: appends a
8	 *      `rebase_started` log entry to the task YAML on the management-repo
9	 *      feature branch and pushes. If the push is rejected, another agent
10	 *      claimed first — skip this cycle (`rebase_claim_lost`).
11	 *
12	 *   2. In the implementation repo: `git fetch origin` then
13	 *      `git rebase origin/<base_branch>`.
14	 *
15	 *   3. Clean rebase (exit 0):
16	 *        - `git push --force-with-lease` the impl branch.
17	 *        - Update task YAML: `conflict_state: resolved`, append
18	 *          `rebase_completed` log entry.
19	 *        - Push the management repo feature branch.
20	 *        - Emit `rebase_completed`.
21	 *
22	 *   4. Conflicted rebase (exit ≠ 0) — three-tier logic:
23	 *
24	 *      a. If ALL conflicted files are in files the agent authored on this
25	 *         branch (`git diff --name-only origin/<base>...HEAD`):
26	 *           - Emit `rebase_resolve_attempt`.
27	 *           - Spawn Claude to resolve the conflict markers in each file.
28	 *           - Run `git add -A` then `git rebase --continue`.
29	 *           - If continue succeeds: treat as a clean rebase (force-push,
30	 *             mark resolved). Emit `rebase_resolved_by_agent`.
31	 *           - If Claude fails or continue fails: emit `rebase_resolve_failed`
32	 *             and fall through to block path.
33	 *
34	 *      b. If ANY conflicted file was NOT authored by the agent:
35	 *           - Block immediately (human-owned files must not be auto-modified).
36	 *
37	 *      c. Block path:
38	 *           - Stage all conflict markers (`git add -A`).
39	 *           - Commit with a descriptive message.
40	 *           - Push the impl branch.
41	 *           - Update task YAML: `status: blocked`,
42	 *             `blocked_reason: pr_conflict`, `conflict_state: conflicted`,
43	 *             append `rebase_blocked` log entry with file:line pointers.
44	 *           - Push the management repo feature branch.
45	 *           - Emit `rebase_blocked`.
46	 */
47	
48	import { execSync, spawnSync, spawn } from "node:child_process";
49	import { readFileSync, writeFileSync } from "node:fs";
50	import { parse as parseYaml, stringify as yamlStringify } from "yaml";
51	import type { Task, RebaseLogEntry } from "../types/task.js";
52	import { taskYamlAbsPath, taskYamlRelPath } from "../paths.js";
53	import type { PrStatusResult } from "../poll/check-in-review-prs.js";
54	import { buildGitCommitEnv } from "../git-env.js";
55	
56	// ── Public types ──────────────────────────────────────────────────────────────
57	
58	export interface AutoRebaseOptions {
59	  /** Absolute path to the management (workspace) repo root. */
60	  workspaceRoot: string;
61	  /** Feature directory ID (e.g. "agent-pr-response"). */
62	  featureId: string;
63	  /** Task ID (e.g. "T3"). */
64	  taskId: string;
65	  /** Task feature branch name (e.g. "feature/agent-pr-response-T3"). */
66	  taskBranch: string;
67	  /** Absolute path to the implementation repo root. */
68	  implRepoRoot: string;
69	  /**
70	   * Base branch of the implementation repo (e.g. "main").
71	   * The rebase targets `origin/<implBaseBranch>`.
72	   */
73	  implBaseBranch: string;
74	  /** GIT_AUTHOR_EMAIL for commits and log entries. */
75	  gitAuthorEmail: string;
76	  /** GIT_AUTHOR_NAME for commits. Defaults to gitAuthorEmail. */
77	  gitAuthorName?: string;
78	  /** SSH private key path for git push operations. */
79	  sshKeyPath?: string;
80	  /** Structured event emitter for observability. */
81	  emit: (event: Record<string, unknown>) => void;
82	  /**
83	   * Optional override for spawning Claude to resolve conflicts.
84	   * Receives the prompt string, the impl repo cwd, and the process env.
85	   * Returns true if resolution succeeded, false otherwise.
86	   * Defaults to `defaultInvokeClaudeForResolution`.
87	   */
88	  invokeClaudeForResolution?: (
89	    prompt: string,
90	    cwd: string,
91	    env: NodeJS.ProcessEnv,
92	  ) => Promise<boolean>;
93	}
94	
95	export type AutoRebaseOutcome =
96	  | "claim_lost"        // Another agent already claimed the rebase.
97	  | "rebase_completed"  // Rebase was clean; impl branch force-pushed.
98	  | "rebase_blocked";   // Conflicts remain; task set to blocked.
99	
100	// ── Internal helpers ──────────────────────────────────────────────────────────
101	
102	
103	function readTask(
104	  workspaceRoot: string,
105	  featureId: string,
106	  taskId: string,
107	): Task {
108	  return parseYaml(
109	    readFileSync(taskYamlAbsPath(workspaceRoot, featureId, taskId), "utf-8"),
110	  ) as Task;
111	}
112	
113	function writeTask(
114	  workspaceRoot: string,
115	  featureId: string,
116	  task: Task,
117	): void {
118	  writeFileSync(
119	    taskYamlAbsPath(workspaceRoot, featureId, task.id),
120	    yamlStringify(task),
121	    "utf-8",
122	  );
123	}
124	
125	/**
126	 * Commit and push the updated task YAML to the management repo task branch.
127	 * Non-fatal: logs errors via emit but does not throw.
128	 */
129	function commitAndPushTaskYaml(
130	  workspaceRoot: string,
131	  featureId: string,
132	  taskId: string,
133	  taskBranch: string,
134	  commitMessage: string,
135	  env: NodeJS.ProcessEnv,
136	): void {
137	  const relPath = taskYamlRelPath(featureId, taskId);
138	  execSync(`git -C "${workspaceRoot}" add "${relPath}"`, {
139	    env,
140	    stdio: "pipe",
141	  });
142	  execSync(
143	    `git -C "${workspaceRoot}" commit -m "${commitMessage}"`,
144	    { env, stdio: "pipe" },
145	  );
146	  execSync(
147	    `git -C "${workspaceRoot}" push origin "${taskBranch}"`,
148	    { env, stdio: "pipe" },
149	  );
150	}
151	
152	/**
153	 * Return all files that currently have conflict markers via `git diff --name-only`.
154	 * Falls back to an empty array on error.
155	 */
156	function listConflictedFiles(
157	  implRepoRoot: string,
158	  env: NodeJS.ProcessEnv,
159	): string[] {
160	  try {
161	    const output = execSync(
162	      `git -C "${implRepoRoot}" diff --name-only --diff-filter=U`,
163	      { env, encoding: "utf-8", stdio: ["ignore", "pipe", "pipe"] },
164	    ).trim();
165	    return output ? output.split("\n") : [];
166	  } catch {
167	    return [];
168	  }
169	}
170	
171	/**
172	 * Return the set of files the agent has touched on this branch relative to
173	 * origin/<baseBranch>. Uses `git diff --name-only origin/<base>...HEAD`.
174	 * Falls back to an empty Set on error.
175	 */
176	function listAgentAuthoredFiles(
177	  implRepoRoot: string,
178	  baseBranch: string,
179	  env: NodeJS.ProcessEnv,
180	): Set<string> {
181	  try {
182	    const output = execSync(
183	      `git -C "${implRepoRoot}" diff --name-only origin/${baseBranch}...HEAD`,
184	      { env, encoding: "utf-8", stdio: ["ignore", "pipe", "pipe"] },
185	    ).trim();
186	    return new Set(output ? output.split("\n") : []);
187	  } catch {
188	    return new Set();
189	  }
190	}
191	
192	/**
193	 * Build the prompt to send to Claude for resolving conflict markers.
194	 * For dependency manifest files, instruct a union merge.
195	 * For other files, instruct preservation of all functionality from both sides.
196	 */
197	function buildConflictResolutionPrompt(
198	  implRepoRoot: string,
199	  baseBranch: string,
200	  conflictedFiles: string[],
201	): string {
202	  const depFiles = new Set([
203	    "pyproject.toml",
204	    "requirements.txt",
205	    "package.json",
206	    "go.mod",
207	    "Cargo.toml",
208	  ]);
209	
210	  const fileInstructions = conflictedFiles
211	    .map((f) => {
212	      const basename = f.split("/").pop() ?? f;
213	      if (depFiles.has(basename)) {
214	        return `- ${f}: dependency manifest — take the UNION of both sides (include all packages/versions from both HEAD and ${baseBranch}, keeping the higher version where there are conflicts)`;
215	      }
216	      return `- ${f}: preserve ALL functionality from both sides; do not drop any code`;
217	    })
218	    .join("\n");
219	
220	  return (
221	    `You are resolving git merge conflicts after a rebase in the repository at ${implRepoRoot}.\n` +
222	    `The following files contain conflict markers (<<<<<<<, =======, >>>>>>>):\n\n` +
223	    fileInstructions +
224	    `\n\nFor each file:\n` +
225	    `1. Read the file contents (which include conflict markers).\n` +
226	    `2. Resolve the conflict markers according to the instructions above.\n` +
227	    `3. Write the fully resolved content back to disk.\n\n` +
228	    `IMPORTANT:\n` +
229	    `- Do NOT run git add or git commit — only write the resolved file contents.\n` +
230	    `- Do NOT modify any files that are not listed above.\n` +
231	    `- After writing all files, respond with a brief summary of what was resolved.`
232	  );
233	}
234	
235	/**
236	 * Default implementation: spawns Claude CLI to resolve conflict markers.
237	 * Streams stdout/stderr to process.stdout/stderr.
238	 * Returns true if the process exits with code 0.
239	 */
240	async function defaultInvokeClaudeForResolution(
241	  prompt: string,
242	  cwd: string,
243	  env: NodeJS.ProcessEnv,
244	): Promise<boolean> {
245	  return new Promise((resolve) => {
246	    const child = spawn(
247	      "claude",
248	      [
249	        "-p",
250	        prompt,
251	        "--max-turns",
252	        "10",
253	        "--output-format",
254	        "stream-json",
255	        "--verbose",
256	        "--dangerously-skip-permissions",
257	      ],
258	      { cwd, env, stdio: ["ignore", "pipe", "pipe"] },
259	    );
260	
261	    child.stdout.pipe(process.stdout);
262	    child.stderr.pipe(process.stderr);
263	
264	    child.on("close", (code) => {
265	      resolve(code === 0);
266	    });
267	
268	    child.on("error", () => {
269	      resolve(false);
270	    });
271	  });
272	}
273	
274	// ── Public API ────────────────────────────────────────────────────────────────
275	
276	/**
277	 * Attempt to rebase the impl branch for one conflicted in_review task.
278	 *
279	 * @returns The outcome of the operation.
280	 */
281	export async function autoRebase(
282	  opts: AutoRebaseOptions,
283	): Promise<AutoRebaseOutcome> {
284	  const {
285	    workspaceRoot,
286	    featureId,
287	    taskId,
288	    taskBranch,
289	    implRepoRoot,
290	    implBaseBranch,
291	    gitAuthorEmail,
292	    gitAuthorName = gitAuthorEmail,
293	    sshKeyPath,
294	    emit,
295	  } = opts;
296	
297	  const env = buildGitCommitEnv(gitAuthorEmail, gitAuthorName, sshKeyPath);
298	  const now = new Date().toISOString();
299	
300	  // ── 1. Claim: ensure we are on the task branch in the management repo ────────
301	  try {
302	    execSync(`git -C "${workspaceRoot}" fetch origin`, { env, stdio: "pipe" });
303	    execSync(
304	      `git -C "${workspaceRoot}" checkout "${taskBranch}"`,
305	      { env, stdio: "pipe" },
306	    );
307	    execSync(
308	      `git -C "${workspaceRoot}" reset --hard "origin/${taskBranch}"`,
309	      { env, stdio: "pipe" },
310	    );
311	  } catch (e) {
312	    emit({
313	      type: "rebase_claim_lost",
314	      task_id: taskId,
315	      feature_id: featureId,
316	      details: `Failed to checkout/reset management repo to task branch: ${String(e)}`,
317	    });
318	    return "claim_lost";
319	  }
320	
321	  // ── 2. Write rebase_started claim to task YAML and push ───────────────────────
322	  let task = readTask(workspaceRoot, featureId, taskId);
323	
324	  // Guard: if conflict_state is already "resolving", another agent claimed it.
325	  if (task.conflict_state === "resolving") {
326	    emit({
327	      type: "rebase_claim_lost",
328	      task_id: taskId,
329	      feature_id: featureId,
330	      details: "conflict_state is already resolving — another agent claimed the rebase.",
331	    });
332	    return "claim_lost";
333	  }
334	
335	  const startedEntry: RebaseLogEntry = {
336	    at: now,
337	    action: "rebase_started",
338	    by: gitAuthorEmail,
339	    note: `Rebase claimed; targeting origin/${implBaseBranch}.`,
340	  };
341	
342	  task.conflict_state = "resolving";
343	  task.rebase_log = [...(task.rebase_log ?? []), startedEntry];
344	  task.execution.last_updated_by = gitAuthorEmail;
345	  task.execution.last_updated_at = now;
346	
347	  writeTask(workspaceRoot, featureId, task);
348	
349	  // First-push-wins: if the push is rejected, another agent got there first.
350	  const relPath = taskYamlRelPath(featureId, taskId);
351	  execSync(`git -C "${workspaceRoot}" add "${relPath}"`, {
352	    env,
353	    stdio: "pipe",
354	  });
355	  execSync(
356	    `git -C "${workspaceRoot}" commit -m "chore(${taskId}): rebase_started — claim"`,
357	    { env, stdio: "pipe" },
358	  );
359	
360	  const claimPush = spawnSync(
361	    "git",
362	    ["-C", workspaceRoot, "push", "origin", taskBranch],
363	    { env, encoding: "utf-8" },
364	  );
365	
366	  if (claimPush.status !== 0) {
367	    emit({
368	      type: "rebase_claim_lost",
369	      task_id: taskId,
370	      feature_id: featureId,
371	      details: `Push rejected — another agent claimed the rebase first. stderr: ${claimPush.stderr}`,
372	    });
373	    return "claim_lost";
374	  }
375	
376	  // ── 3. Rebase in the implementation repo ─────────────────────────────────────
377	  try {
378	    execSync(`git -C "${implRepoRoot}" fetch origin`, { env, stdio: "pipe" });
379	  } catch (e) {
380	    emit({
381	      type: "rebase_blocked",
382	      task_id: taskId,
383	      feature_id: featureId,
384	      details: `git fetch failed in impl repo: ${String(e)}`,
385	    });
386	    // Can't proceed — abort and mark blocked.
387	    return await handleConflictedRebase(
388	      opts,
389	      task,
390	      env,
391	      [`git fetch failed: ${String(e)}`],
392	    );
393	  }
394	
395	  // Ensure we are on the task branch in the impl repo.
396	  try {
397	    execSync(`git -C "${implRepoRoot}" checkout "${taskBranch}"`, {
398	      env,
399	      stdio: "pipe",
400	    });
401	    execSync(
402	      `git -C "${implRepoRoot}" reset --hard "origin/${taskBranch}"`,
403	      { env, stdio: "pipe" },
404	    );
405	  } catch (e) {
406	    emit({
407	      type: "rebase_blocked",
408	      task_id: taskId,
409	      feature_id: featureId,
410	      details: `Failed to checkout impl branch ${taskBranch}: ${String(e)}`,
411	    });
412	    return await handleConflictedRebase(opts, task, env, [`checkout failed: ${String(e)}`]);
413	  }
414	
415	  // Capture agent-authored files BEFORE the rebase so we can compare later.
416	  const agentFiles = listAgentAuthoredFiles(implRepoRoot, implBaseBranch, env);
417	
418	  // Abort any in-progress rebase before starting a new one.
419	  spawnSync("git", ["-C", implRepoRoot, "rebase", "--abort"], {
420	    env,
421	    encoding: "utf-8",
422	  });
423	
424	  const rebaseResult = spawnSync(
425	    "git",
426	    ["-C", implRepoRoot, "rebase", `origin/${implBaseBranch}`],
427	    { env, encoding: "utf-8" },
428	  );
429	
430	  if (rebaseResult.status === 0) {
431	    // ── 4a. Clean rebase ────────────────────────────────────────────────────────
432	    return await handleCleanRebase(opts, task, env);
433	  } else {
434	    // ── 4b. Conflicted rebase — three-tier logic ────────────────────────────────
435	    const conflictedFiles = listConflictedFiles(implRepoRoot, env);
436	    const nonAuthoredConflicts = conflictedFiles.filter(
437	      (f) => !agentFiles.has(f),
438	    );
439	
440	    if (conflictedFiles.length > 0 && nonAuthoredConflicts.length === 0) {
441	      // All conflicts are in agent-authored files — attempt Claude resolution.
442	      emit({
443	        type: "rebase_resolve_attempt",
444	        task_id: taskId,
445	        feature_id: featureId,
446	        conflicted_files: conflictedFiles,
447	      });
448	      const invoker =
449	        opts.invokeClaudeForResolution ?? defaultInvokeClaudeForResolution;
450	      const prompt = buildConflictResolutionPrompt(
451	        implRepoRoot,
452	        implBaseBranch,
453	        conflictedFiles,
454	      );
455	
456	      try {
457	        const resolved = await invoker(prompt, implRepoRoot, env);
458	        if (resolved) {
459	          execSync(`git -C "${implRepoRoot}" add -A`, { env, stdio: "pipe" });
460	          const continueResult = spawnSync(
461	            "git",
462	            ["-C", implRepoRoot, "rebase", "--continue"],
463	            {
464	              env: { ...env, GIT_EDITOR: "true", GIT_SEQUENCE_EDITOR: "true" },
465	              encoding: "utf-8",
466	            },
467	          );
468	          if (continueResult.status === 0) {
469	            emit({
470	              type: "rebase_resolved_by_agent",
471	              task_id: taskId,
472	              feature_id: featureId,
473	              conflicted_files: conflictedFiles,
474	            });
475	            const resolvedAt = new Date().toISOString();
476	            task.rebase_log = [
477	              ...(task.rebase_log ?? []),
478	              {
479	                at: resolvedAt,
480	                action: "rebase_resolved_by_agent",
481	                by: gitAuthorEmail,
482	                note: `Claude resolved conflict markers in: ${conflictedFiles.join(", ")}; rebase continued cleanly.`,
483	              },
484	            ];
485	            return await handleCleanRebase(opts, task, env);
486	          }
487	        }
488	      } catch {
489	        // fall through to block
490	      }
491	      emit({
492	        type: "rebase_resolve_failed",
493	        task_id: taskId,
494	        feature_id: featureId,
495	        conflicted_files: conflictedFiles,
496	      });
497	    }
498	
499	    return await handleConflictedRebase(opts, task, env, conflictedFiles);
500	  }
501	}
502	
503	// ── Clean rebase handler ──────────────────────────────────────────────────────
504	
505	async function handleCleanRebase(
506	  opts: AutoRebaseOptions,
507	  task: Task,
508	  env: NodeJS.ProcessEnv,
509	): Promise<AutoRebaseOutcome> {
510	  const {
511	    workspaceRoot,
512	    featureId,
513	    taskId,
514	    taskBranch,
515	    implRepoRoot,
516	    gitAuthorEmail,
517	    emit,
518	  } = opts;
519	
520	  // Force-push the impl branch.
521	  const pushResult = spawnSync(
522	    "git",
523	    ["-C", implRepoRoot, "push", "--force-with-lease", "origin", taskBranch],
524	    { env, encoding: "utf-8" },
525	  );
526	
527	  if (pushResult.status !== 0) {
528	    emit({
529	      type: "rebase_blocked",
530	      task_id: taskId,
531	      feature_id: featureId,
532	      details: `force-with-lease push failed after clean rebase: ${pushResult.stderr}`,
533	    });
534	    // Rare — treat as a recoverable blocked state.
535	    return await handleConflictedRebase(
536	      opts,
537	      task,
538	      env,
539	      [`force-push failed: ${pushResult.stderr}`],
540	    );
541	  }
542	
543	  // Update task YAML with resolved state.
544	  const completedAt = new Date().toISOString();
545	  const completedEntry: RebaseLogEntry = {
546	    at: completedAt,
547	    action: "rebase_completed",
548	    by: gitAuthorEmail,
549	    note: "Rebase completed cleanly; impl branch force-pushed.",
550	  };
551	
552	  task.conflict_state = "resolved";
553	  task.rebase_log = [...(task.rebase_log ?? []), completedEntry];
554	  task.execution.last_updated_by = gitAuthorEmail;
555	  task.execution.last_updated_at = completedAt;
556	
557	  writeTask(workspaceRoot, featureId, task);
558	
559	  try {
560	    commitAndPushTaskYaml(
561	      workspaceRoot,
562	      featureId,
563	      taskId,
564	      taskBranch,
565	      `chore(${taskId}): rebase_completed — conflict_state resolved`,
566	      env,
567	    );
568	  } catch (e) {
569	    emit({
570	      type: "rebase_completed",
571	      task_id: taskId,
572	      feature_id: featureId,
573	      note: "Rebase clean but management repo push failed — YAML may be stale.",
574	      details: String(e),
575	    });
576	    return "rebase_completed";
577	  }
578	
579	  emit({
580	    type: "rebase_completed",
581	    task_id: taskId,
582	    feature_id: featureId,
583	  });
584	
585	  return "rebase_completed";
586	}
587	
588	// ── Conflicted rebase handler ─────────────────────────────────────────────────
589	
590	async function handleConflictedRebase(
591	  opts: AutoRebaseOptions,
592	  task: Task,
593	  env: NodeJS.ProcessEnv,
594	  conflictedFiles: string[],
595	): Promise<AutoRebaseOutcome> {
596	  const {
597	    workspaceRoot,
598	    featureId,
599	    taskId,
600	    taskBranch,
601	    implRepoRoot,
602	    gitAuthorEmail,
603	    emit,
604	  } = opts;
605	
606	  // Abort any ongoing rebase so git is in a clean-enough state.
607	  spawnSync("git", ["-C", implRepoRoot, "rebase", "--abort"], {
608	    env,
609	    encoding: "utf-8",
610	  });
611	
612	  // Stage everything (including conflict markers) and commit.
613	  spawnSync("git", ["-C", implRepoRoot, "add", "-A"], {
614	    env,
615	    encoding: "utf-8",
616	  });
617	
618	  const conflictSummary =
619	    conflictedFiles.length > 0
620	      ? conflictedFiles.join(", ")
621	      : "unknown files";
622	
623	  const commitResult = spawnSync(
624	    "git",
625	    [
626	      "-C",
627	      implRepoRoot,
628	      "commit",
629	      "-m",
630	      `wip(${taskId}): conflict markers after failed rebase — ${conflictSummary}`,
631	    ],
632	    { env, encoding: "utf-8" },
633	  );
634	
635	  // Push even if commit was a no-op (nothing staged).
636	  if (commitResult.status === 0) {
637	    spawnSync(
638	      "git",
639	      ["-C", implRepoRoot, "push", "origin", taskBranch],
640	      { env, encoding: "utf-8" },
641	    );
642	  }
643	
644	  // Build the blocked_suggestion with file:line pointers.
645	  const blockedNote =
646	    conflictedFiles.length > 0
647	      ? `Unresolvable merge conflicts in: ${conflictedFiles.join("; ")}. Manual resolution required.`
648	      : "Merge conflicts detected during rebase. Manual resolution required.";
649	
650	  const blockedAt = new Date().toISOString();
651	  const blockedEntry: RebaseLogEntry = {
652	    at: blockedAt,
653	    action: "rebase_blocked",
654	    by: gitAuthorEmail,
655	    note: blockedNote,
656	  };
657	
658	  task.status = "blocked";
659	  task.blocked_reason = "pr_conflict";
660	  // "resolved" signals that the conflict has been surfaced to the branch and
661	  // is visible in the PR — not that it has been fixed. See technical-design.md.
662	  task.conflict_state = "resolved";
663	  task.rebase_log = [...(task.rebase_log ?? []), blockedEntry];
664	  task.execution.last_updated_by = gitAuthorEmail;
665	  task.execution.last_updated_at = blockedAt;
666	  task.execution.suggested_next_step =
667	    "Manually resolve the conflicts listed in blocked_reason detail, then set status back to in_review.";
668	  task.log.push({
669	    action: "blocked",
670	    by: gitAuthorEmail,
671	    at: blockedAt,
672	    note: blockedNote,
673	  });
674	
675	  writeTask(workspaceRoot, featureId, task);
676	
677	  try {
678	    commitAndPushTaskYaml(
679	      workspaceRoot,
680	      featureId,
681	      taskId,
682	      taskBranch,
683	      `chore(${taskId}): rebase_blocked — pr_conflict`,
684	      env,
685	    );
686	  } catch (e) {
687	    emit({
688	      type: "rebase_blocked",
689	      task_id: taskId,
690	      feature_id: featureId,
691	      conflicted_files: conflictedFiles,
692	      note: "Management repo YAML push failed — YAML may be stale.",
693	      details: String(e),
694	    });
695	    return "rebase_blocked";
696	  }
697	
698	  emit({
699	    type: "rebase_blocked",
700	    task_id: taskId,
701	    feature_id: featureId,
702	    conflicted_files: conflictedFiles,
703	  });
704	
705	  return "rebase_blocked";
706	}
707	
708	// ── Cycle-level orchestrator ──────────────────────────────────────────────────
709	
710	export interface HandleMergeConflictsOptions {
711	  /** Results from checkInReviewPrs — only those with mergeable === false are processed. */
712	  prResults: PrStatusResult[];
713	  /** Absolute path to the management (workspace) repo root — keyed by workspaceRoot. */
714	  workspaceRoot: string;
715	  /** Resolve the impl repo root for a given repo ID (from workspace.yaml). */
716	  resolveImplRepoRoot: (repoId: string) => string;
717	  /** Resolve the impl base branch for a given repo ID (from workspace.yaml). */
718	  resolveImplBaseBranch: (repoId: string) => string;
719	  /** Resolve the task's repo ID from the task YAML. */
720	  resolveTaskRepoId: (featureId: string, taskId: string) => string;
721	  /** GIT_AUTHOR_EMAIL for commits and log entries. */
722	  gitAuthorEmail: string;
723	  /** GIT_AUTHOR_NAME for commits. Defaults to gitAuthorEmail. */
724	  gitAuthorName?: string;
725	  /** SSH private key path for git push operations. */
726	  sshKeyPath?: string;
727	  /** Structured event emitter for observability. */
728	  emit: (event: Record<string, unknown>) => void;
729	}
730	
731	/**
732	 * Iterate T2 poll results where `mergeable === false` and run autoRebase for each.
733	 * Called from `runOneCycle` in main.ts after the ready-task pass.
734	 */
735	export async function handleMergeConflicts(
736	  opts: HandleMergeConflictsOptions,
737	): Promise<void> {
738	  const {
739	    prResults,
740	    workspaceRoot,
741	    resolveImplRepoRoot,
742	    resolveImplBaseBranch,
743	    resolveTaskRepoId,
744	    gitAuthorEmail,
745	    gitAuthorName,
746	    sshKeyPath,
747	    emit,
748	  } = opts;
749	
750	  const conflicted = prResults.filter((r) => r.mergeable === false);
751	
752	  // Only process one conflicted task per impl repo per cycle to prevent
753	  // concurrent git rebase operations on the same on-disk clone.
754	  const processedImplRoots = new Set<string>();
755	
756	  for (const result of conflicted) {
757	    const { taskId, featureId } = result;
758	
759	    let repoId: string;
760	    try {
761	      repoId = resolveTaskRepoId(featureId, taskId);
762	    } catch (e) {
763	      emit({
764	        type: "rebase_blocked",
765	        task_id: taskId,
766	        feature_id: featureId,
767	        details: `Cannot resolve repo ID: ${String(e)}`,
768	      });
769	      continue;
770	    }
771	
772	    let implRepoRoot: string;
773	    let implBaseBranch: string;
774	    try {
775	      implRepoRoot = resolveImplRepoRoot(repoId);
776	      implBaseBranch = resolveImplBaseBranch(repoId);
777	    } catch (e) {
778	      emit({
779	        type: "rebase_blocked",
780	        task_id: taskId,
781	        feature_id: featureId,
782	        details: `Cannot resolve impl repo path or base branch: ${String(e)}`,
783	      });
784	      continue;
785	    }
786	
787	    if (processedImplRoots.has(implRepoRoot)) {
788	      emit({
789	        type: "rebase_skipped_concurrent",
790	        task_id: taskId,
791	        feature_id: featureId,
792	        details: `impl repo ${implRepoRoot} already has a rebase in progress this cycle — skipping to prevent concurrent git operations`,
793	      });
794	      continue;
795	    }
796	    processedImplRoots.add(implRepoRoot);
797	
798	    const taskBranch = `feature/${featureId}-${taskId}`;
799	
800	    try {
801	      await autoRebase({
802	        workspaceRoot,
803	        featureId,
804	        taskId,
805	        taskBranch,
806	        implRepoRoot,
807	        implBaseBranch,
808	        gitAuthorEmail,
809	        gitAuthorName,
810	        sshKeyPath,
811	        emit,
812	      });
813	    } catch (e) {
814	      emit({
815	        type: "rebase_blocked",
816	        task_id: taskId,
817	        feature_id: featureId,
818	        details: `Unexpected error in autoRebase: ${String(e)}`,
819	      });
820	    }
821	  }
822	}
