193	/**
194	 * Claim the review work for one draft-state in_review task and dispatch
195	 * Claude to address the open PR review comments.
196	 *
197	 * Claim protocol (first-push-wins):
198	 *   1. Checkout and reset the management-repo task branch.
199	 *   2. Guard: if the task log already has a `review_started` entry, skip.
200	 *   3. Append `review_started` to the task log and push.
201	 *      If the push is rejected, another agent won — return "claim_lost".
202	 *   4. Generate review agent context and call runClaude.
203	 *
204	 * @returns The outcome of the operation.
205	 */
206	export async function dispatchOneReview(
207	  opts: DispatchOneReviewOptions,
208	): Promise<DraftReviewOutcome> {
209	  const {
210	    workspaceRoot,
211	    featureId,
212	    taskId,
213	    taskBranch,
214	    implRepoRoot,
215	    gitAuthorEmail,
216	    gitAuthorName = gitAuthorEmail,
217	    sshKeyPath,
218	    workflowLocalPath,
219	    maxTurns,
220	    maxTokens,
221	    logSinkEnabled,
222	    implementationModel,
223	    emit,
224	  } = opts;
225	
226	  const env = buildGitCommitEnv(gitAuthorEmail, gitAuthorName, sshKeyPath);
227	  const now = new Date().toISOString();
228	
229	  // ── 1. Checkout and reset task branch in management repo ──────────────────────
230	  try {
231	    execSync(`git -C "${workspaceRoot}" fetch origin`, { env, stdio: "pipe" });
232	    execSync(
233	      `git -C "${workspaceRoot}" checkout "${taskBranch}"`,
234	      { env, stdio: "pipe" },
235	    );
236	    execSync(
237	      `git -C "${workspaceRoot}" reset --hard "origin/${taskBranch}"`,
238	      { env, stdio: "pipe" },
239	    );
240	  } catch (e) {
241	    emit({
242	      type: "review_claim_lost",
243	      task_id: taskId,
244	      feature_id: featureId,
245	      details: `Failed to checkout/reset management repo to task branch: ${String(e)}`,
246	    });
247	    return "claim_lost";
248	  }
249	
250	  // ── 2. Read task and guard against duplicate claims ───────────────────────────
251	  let task: Task;
252	  try {
253	    task = readTask(workspaceRoot, featureId, taskId);
254	  } catch (e) {
255	    emit({
256	      type: "review_claim_lost",
257	      task_id: taskId,
258	      feature_id: featureId,
259	      details: `Failed to read task YAML: ${String(e)}`,
260	    });
261	    return "claim_lost";
262	  }
263	
264	  // If the last log entry is review_started, another agent holds an active claim.
265	  // A prior review_started followed by blocked/in_review/etc means the cycle ended
266	  // and a new claim is valid (e.g. new comments after a previous review round).
267	  const lastEntry = task.log[task.log.length - 1];
268	  const alreadyClaimed = lastEntry?.action === "review_started";
269	  if (alreadyClaimed) {
270	    emit({
271	      type: "review_claim_lost",
272	      task_id: taskId,
273	      feature_id: featureId,
274	      details: "Last log entry is review_started — another agent currently holds the review claim.",
275	    });
276	    return "claim_lost";
277	  }
278	
279	  // Guard against dispatch loops: count consecutive review cycles (review_started +
280	  // comments_addressed pairs) since the last non-review log entry. If >= 3, stop
281	  // dispatching — the agent has repeatedly attempted without fully resolving and
282	  // a human must inspect. Resets naturally whenever a human adds any other log entry.
283	  const REVIEW_CYCLE_ACTIONS = new Set(["review_started", "comments_addressed"]);
284	  const MAX_REVIEW_CYCLES = 3;
285	  let consecutiveReviewCycles = 0;
286	  for (let i = task.log.length - 1; i >= 0; i--) {
287	    if (!REVIEW_CYCLE_ACTIONS.has(task.log[i].action)) break;
288	    if (task.log[i].action === "review_started") consecutiveReviewCycles++;
289	  }
290	  if (consecutiveReviewCycles >= MAX_REVIEW_CYCLES) {
291	    emit({
292	      type: "review_loop_detected",
293	      task_id: taskId,
294	      feature_id: featureId,
295	      details: `${consecutiveReviewCycles} consecutive review cycles without resolution — human intervention required.`,
296	    });
297	    return "claim_lost";
298	  }
299	
300	  // ── 3. Write review_started log entry and push (first-push-wins) ──────────────
301	  task.log.push({
302	    action: "review_started",
303	    by: gitAuthorEmail,
304	    at: now,
305	    note: "Review dispatch claimed; addressing open PR comments.",
306	  });
307	  task.execution.last_updated_by = gitAuthorEmail;
308	  task.execution.last_updated_at = now;
309	
310	  writeTask(workspaceRoot, featureId, task);
311	
312	  const relPath = taskYamlRelPath(featureId, taskId);
313	  try {
314	    execSync(`git -C "${workspaceRoot}" add "${relPath}"`, { env, stdio: "pipe" });
315	    execSync(
316	      `git -C "${workspaceRoot}" commit -m "chore(${taskId}): review_started — claim"`,
317	      { env, stdio: "pipe" },
318	    );
319	  } catch (e) {
320	    emit({
321	      type: "review_claim_lost",
322	      task_id: taskId,
323	      feature_id: featureId,
324	      details: `Failed to commit review_started claim: ${String(e)}`,
325	    });
326	    return "claim_lost";
327	  }
328	
329	  const claimPush = spawnSync(
330	    "git",
331	    ["-C", workspaceRoot, "push", "origin", taskBranch],
332	    { env, encoding: "utf-8" },
333	  );
334	
335	  if (claimPush.status !== 0) {
336	    emit({
337	      type: "review_claim_lost",
338	      task_id: taskId,
339	      feature_id: featureId,
340	      details: `Push rejected — another agent claimed the review first. stderr: ${claimPush.stderr}`,
341	    });
342	    return "claim_lost";
343	  }
344	
345	  emit({
346	    type: "review_dispatching",
347	    task_id: taskId,
348	    feature_id: featureId,
349	    pr_url: task.pr.url,
350	  });
351	
352	  // ── 4. Generate review agent context ─────────────────────────────────────────
353	  const agentContext = generateReviewAgentContext({
354	    taskId,
355	    featureId,
356	    taskTitle: task.title,
357	    taskBranch,
358	    taskRepo: task.repo,
359	    taskRepoRoot: implRepoRoot,
360	    workspaceRoot,
361	    prUrl: task.pr.url,
362	    gitAuthorEmail,
363	    gitAuthorName,
364	    implementationModel,
365	  });
366	
367	  // ── 5. Run Claude ─────────────────────────────────────────────────────────────
368	  const runResult = await runClaude({
369	    taskId,
370	    featureId,
371	    workspaceRoot,
372	    taskRepoRoot: implRepoRoot,
373	    workflowLocalPath,
374	    agentContext,
375	    maxTurns,
376	    maxTokens,
377	    sshKeyPath,
378	    gitAuthorEmail,
379	    taskBranch,
380	    logSinkEnabled,
381	  });
382	
383	  emit({
384	    type: "review_dispatch_complete",
385	    task_id: taskId,
386	    feature_id: featureId,
387	    outcome: runResult.outcome,
388	  });
389	
390	  return "dispatched";
391	}
392	
393	// ── Cycle-level orchestrator ──────────────────────────────────────────────────
394	
395	/**
396	 * Iterate poll results where `hasOpenComments === true` and dispatch Claude
397	 * to address them. Triggered regardless of draft state — any in_review PR
398	 * with unresolved threads or unaddressed comments is eligible.
399	 * Called from `runOneCycle` in main.ts after the merge-conflict pass.
400	 */
401	export async function handleDraftReviews(
402	  opts: HandleDraftReviewsOptions,
403	): Promise<void> {
404	  const {
405	    prResults,
406	    workspaceRoot,
407	    resolveImplRepoRoot,
408	    resolveTaskRepoId,
409	    resolveImplementationModel,
410	    gitAuthorEmail,
411	    gitAuthorName,
412	    sshKeyPath,
413	    workflowLocalPath,
414	    maxTurns,
415	    maxTokens,
416	    logSinkEnabled,
417	    emit,
418	  } = opts;
419	
420	  const draftTasks = prResults.filter((r) => r.hasOpenComments === true);
421	
422	  for (const result of draftTasks) {
423	    const { taskId, featureId } = result;
424	
425	    let repoId: string;
426	    try {
427	      repoId = resolveTaskRepoId(featureId, taskId);
428	    } catch (e) {
429	      emit({
430	        type: "review_dispatch_error",
431	        task_id: taskId,
432	        feature_id: featureId,
433	        details: `Cannot resolve repo ID: ${String(e)}`,
434	      });
435	      continue;
436	    }
437	
438	    let implRepoRoot: string;
439	    try {
440	      implRepoRoot = resolveImplRepoRoot(repoId);
441	    } catch (e) {
442	      emit({
443	        type: "review_dispatch_error",
444	        task_id: taskId,
445	        feature_id: featureId,
446	        details: `Cannot resolve impl repo root: ${String(e)}`,
447	      });
448	      continue;
449	    }
450	
451	    let implementationModel: string;
452	    try {
453	      implementationModel = resolveImplementationModel(featureId, taskId);
454	    } catch (e) {
455	      emit({
456	        type: "review_dispatch_error",
457	        task_id: taskId,
458	        feature_id: featureId,
459	        details: `Cannot resolve implementation model: ${String(e)}`,
460	      });
461	      continue;
462	    }
463	
464	    const taskBranch = `feature/${featureId}-${taskId}`;
465	
466	    try {
467	      await dispatchOneReview({
468	        workspaceRoot,
