91	// ── Internal helpers ──────────────────────────────────────────────────────────
92	
93	function readTask(
94	  workspaceRoot: string,
95	  featureId: string,
96	  taskId: string,
97	): Task {
98	  return parseYaml(
99	    readFileSync(taskYamlAbsPath(workspaceRoot, featureId, taskId), "utf-8"),
100	  ) as Task;
101	}
102	
103	function writeTask(
104	  workspaceRoot: string,
105	  featureId: string,
106	  task: Task,
107	): void {
108	  writeFileSync(
109	    taskYamlAbsPath(workspaceRoot, featureId, task.id),
110	    yamlStringify(task),
111	    "utf-8",
