313	        if (githubToken) {
314	          try {
315	            const mgmtCoords = parseManagementRepoCoords(workspaceLocalPath);
316	            await openWorkspacePr({
317	              workspaceRoot: workspaceLocalPath,
318	              featureId,
319	              taskId: task.id,
320	              branch: taskBranch,
321	              baseBranch: mgmtCoords.baseBranch,
322	              githubToken,
323	              repoOwner: mgmtCoords.owner,
324	              repoName: mgmtCoords.repo,
325	              gitAuthorEmail,
326	              gitAuthorName,
327	              sshKeyPath,
328	            });
329	            emit({ type: "workspace_pr_opened", task_id: task.id, feature_id: featureId });
330	          } catch (e) {
331	            emit({ type: "workspace_pr_failed", task_id: task.id, feature_id: featureId, details: String(e) });
332	          }
333	        }
334	
335	        // ── Load model policy + resolve task repo path ────────────────────────
336	        const workspaceModelPolicy = loadWorkspaceModelPolicy(workspaceLocalPath);
337	        const taskRepoRoot = resolveRepoLocalPath(workspaceLocalPath, task.repo);
338	
339	        // ── Resolve implementation model + parse task-level overrides ─────────
340	        const tasksMdPath = join(workspaceLocalPath, "docs", "features", featureId, "tasks.md");
341	        let taskModelOverrides = {};
342	        try {
343	          const tasksMdContent = readFileSync(tasksMdPath, "utf-8");
344	          taskModelOverrides = parseModelOverrides(tasksMdContent, task.id);
345	        } catch {
346	          // Non-fatal — use workspace defaults if tasks.md is unreadable.
347	        }
348	        const implementationModel = resolveModel(
349	          workspaceModelPolicy,
350	          taskModelOverrides,
351	          "implementation",
352	          task.id,
353	        );
354	
355	        // ── Generate agent context ─────────────────────────────────────────────
356	        const baseAgentContext = generateAgentContext({
357	          taskId: task.id,
358	          featureId,
359	          taskTitle: task.title,
360	          taskBranch,
361	          taskRepo: task.repo,
362	          taskRepoRoot,
363	          workspaceRoot: workspaceLocalPath,
364	          gitAuthorEmail,
365	          gitAuthorName,
366	          implementationModel,
367	        });
368	
369	        // ── Pre-inject RAG context ─────────────────────────────────────────────
370	        // The runtime is the authoritative writer of the rag_pre_flight task-log
371	        // entry — runClaude appends it before spawning Claude and audits it on
372	        // exit, so the agent cannot fabricate or omit RAG injection metadata.
373	        const mcpRagUrl = process.env.MCP_RAG_URL;
374	        const workspaceYaml = parseYaml(
375	          readFileSync(workspaceYamlPath(workspaceLocalPath), "utf-8"),
376	        ) as { workspace_id: string };
377	        const ragQuery = `${task.title} ${featureId}`;
378	        const ragPreFlight = await fetchRagContext(
379	          mcpRagUrl,
380	          ragQuery,
381	          workspaceYaml.workspace_id,
382	        );
383	        const agentContext = ragPreFlight.block
384	          ? `${baseAgentContext}\n\n${ragPreFlight.block}`
385	          : baseAgentContext;
386	
387	        // ── Run claude ─────────────────────────────────────────────────────────
388	        const runResult = await runClaude({
389	          taskId: task.id,
390	          featureId,
391	          workspaceRoot: workspaceLocalPath,
392	          taskRepoRoot,
393	          workflowLocalPath,
394	          agentContext,
395	          maxTurns: config.budget.max_iterations,
396	          maxTokens: config.budget.max_tokens_per_task,
397	          sshKeyPath,
398	          gitAuthorEmail,
399	          taskBranch,
400	          logSinkEnabled: config.log_sink.enabled,
401	          ragPreFlight: {
402	            query: ragQuery,
403	            injected: ragPreFlight.injected,
404	            summary: ragPreFlight.summary,
405	          },
406	        });
407	
408	        emit({ type: "task_run_complete", task_id: task.id, feature_id: featureId, outcome: runResult.outcome });
409	        outcome = "ran_task";
410	        // Break out of both loops — but still complete the in_review pass below.
411	        break outerLoop;
412	      }
413	    }
414	
415	    // ── 3c. In-review PR poll ─────────────────────────────────────────────────
416	    // Runs after every ready-task pass, regardless of whether a task was claimed.
417	    // Skipped if it ran within pr_poll_interval_seconds.
418	    if (githubToken) {
419	      const prPollIntervalMs =
420	        (config.pr_poll_interval_seconds ?? config.idle_sleep_seconds ?? 60) * 1000;
421	      const now = Date.now();
422	
423	      if (lastPrPollAt === null || now - lastPrPollAt >= prPollIntervalMs) {
424	        if (pulledWorkspaceRoots.length > 0) lastPrPollAt = now;
425	        try {
426	          const { prResults, workspacePrRecoveries } = await checkInReviewPrs({
427	            workspaceRoots: pulledWorkspaceRoots,
428	            githubToken,
429	            emit,
430	          });
431	
432	          // ── T3: Auto-rebase for mergeable === false tasks ──────────────────────
433	          // Run per workspace so the resolver closures have the correct root.
434	          for (const wsRoot of pulledWorkspaceRoots) {
435	            const wsResults = prResults.filter((r) => r.workspaceRoot === wsRoot);
436	            if (wsResults.some((r) => r.mergeable === false)) {
437	              await handleMergeConflicts({
438	                prResults: wsResults,
439	                workspaceRoot: wsRoot,
440	                resolveImplRepoRoot: (repoId) =>
441	                  resolveRepoLocalPath(wsRoot, repoId),
442	                resolveImplBaseBranch: (repoId) =>
443	                  resolveRepoBaseBranch(wsRoot, repoId),
444	                resolveTaskRepoId: (featureId, taskId) =>
445	                  resolveTaskRepoId(wsRoot, featureId, taskId),
446	                gitAuthorEmail,
447	                gitAuthorName,
448	                sshKeyPath,
449	                emit,
450	              });
451	            }
452	          }
453	
454	          // ── T4: Review dispatch for tasks with open comments ──────────────────
455	          // Run per workspace so the resolver closures have the correct root.
456	          for (const wsRoot of pulledWorkspaceRoots) {
457	            const wsResults = prResults.filter((r) => r.workspaceRoot === wsRoot);
458	            if (wsResults.some((r) => r.hasOpenComments === true)) {
459	              const wsModelPolicy = loadWorkspaceModelPolicy(wsRoot);
460	              await handleDraftReviews({
461	                prResults: wsResults,
462	                workspaceRoot: wsRoot,
463	                resolveImplRepoRoot: (repoId) =>
464	                  resolveRepoLocalPath(wsRoot, repoId),
465	                resolveTaskRepoId: (featureId, taskId) =>
466	                  resolveTaskRepoId(wsRoot, featureId, taskId),
467	                resolveImplementationModel: (featureId, taskId) => {
468	                  try {
469	                    const tasksMdPath = join(wsRoot, "docs", "features", featureId, "tasks.md");
470	                    const content = readFileSync(tasksMdPath, "utf-8");
471	                    const overrides = parseModelOverrides(content, taskId);
472	                    return resolveModel(wsModelPolicy, overrides, "implementation", taskId);
473	                  } catch {
474	                    return resolveModel(wsModelPolicy, {}, "implementation", taskId);
475	                  }
476	                },
477	                gitAuthorEmail,
478	                gitAuthorName,
479	                sshKeyPath,
480	                workflowLocalPath,
481	                maxTurns: config.budget.max_iterations,
482	                maxTokens: config.budget.max_tokens_per_task,
483	                logSinkEnabled: config.log_sink.enabled,
484	                emit,
485	              });
486	            }
487	          }
488	
489	          // ── Merge completion for merged implementation PRs ─────────────────────
490	          // Run per workspace so each handler operates on its own management repo.
491	          for (const wsRoot of pulledWorkspaceRoots) {
492	            const wsResults = prResults.filter((r) => r.workspaceRoot === wsRoot);
493	            if (wsResults.some((r) => r.merged === true)) {
494	              const mgmtCoords = parseManagementRepoCoords(wsRoot);
495	              await handleMergedPrs({
496	                prResults: wsResults,
497	                workspaceRoot: wsRoot,
498	                mgmtRepoOwner: mgmtCoords.owner,
499	                mgmtRepoName: mgmtCoords.repo,
500	                mgmtBaseBranch: mgmtCoords.baseBranch,
501	                githubToken,
502	                gitAuthorEmail,
503	                gitAuthorName,
504	                sshKeyPath,
505	                emit,
506	              });
507	            }
508	          }
509	
510	          // ── Workspace PR recovery for done tasks whose workspace PR failed ────
511	          // Grouped by workspace so each call targets the correct management repo.
512	          for (const wsRoot of pulledWorkspaceRoots) {
513	            const wsRecoveries = workspacePrRecoveries.filter(
514	              (r) => r.workspaceRoot === wsRoot,
515	            );
516	            if (wsRecoveries.length > 0) {
517	              const mgmtCoords = parseManagementRepoCoords(wsRoot);
518	              await handleWorkspacePrRecoveries({
519	                recoveries: wsRecoveries,
520	                mgmtRepoOwner: mgmtCoords.owner,
521	                mgmtRepoName: mgmtCoords.repo,
522	                mgmtBaseBranch: mgmtCoords.baseBranch,
523	                githubToken,
524	                gitAuthorEmail,
525	                gitAuthorName,
526	                sshKeyPath,
527	                emit,
528	              });
529	            }
530	          }
531	        } catch (e) {
532	          emit({ type: "in_review_poll_error", details: String(e) });
533	        }
534	      }
535	    }
536	
537	    return outcome;
538	  }
539	
540	  // ── 4. Run the polling loop ───────────────────────────────────────────────
541	  await runAgentLoop({ config, runCycle: runOneCycle, emit });
542	
543	  return 0;
544	}
545	
546	main()
547	  .then((code) => process.exit(code))
548	  .catch((e) => {
549	    try {
550	      console.log(
551	        JSON.stringify({
552	          type: "fatal_error",
553	          details: (e as Error).message ?? String(e),
554	          at: new Date().toISOString(),
555	        }),
556	      );
557	    } catch {
558	      /* cannot emit — last resort */
559	    }
560	    process.exit(4);
561	  });
