1	/**
2	 * T5: Claude Code CLI subprocess invocation.
3	 *
4	 * Replaces the raw Anthropic SDK tool-use loop (run-task.ts) with a thin
5	 * wrapper around `claude -p <agentContext> --max-turns <n>`. After the
6	 * subprocess exits, the task YAML is read to determine the outcome.
7	 *
8	 * Token audit (D3 option X / Y):
9	 *   Attempt to find a JSON usage line in stdout. If found and total tokens
10	 *   exceed maxTokens, override the outcome to budget_exceeded. If the format
11	 *   is not found, emit budget_audit_skipped and continue (option Y).
12	 */
13	
14	import { spawn, execSync } from "node:child_process";
15	import { mkdirSync, appendFileSync, readFileSync, writeFileSync, existsSync, readdirSync, rmSync, copyFileSync, lstatSync } from "node:fs";
16	import { join } from "node:path";
17	import { homedir } from "node:os";
18	import { parse as parseYaml, stringify as yamlStringify } from "yaml";
19	import type { Task, BlockedReason, TaskLogEntry } from "../types/task.js";
20	import { taskYamlAbsPath, taskYamlRelPath, featureLogsDirPath, logFileRelPath } from "../paths.js";
21	import { deriveLogPath, toSafeIso } from "../logging/log-sink.js";
22	import { redactSecrets } from "../logging/redact-secrets.js";
23	import { buildGitEnv, buildGitCommitEnv } from "../git-env.js";
24	
25	// ── Public types ──────────────────────────────────────────────────────────────
26	
27	export type RunClaudeResult =
28	  | { outcome: "in_review" }
29	  | { outcome: "blocked"; reason: string; details?: unknown };
30	
31	/**
32	 * RAG pre-flight metadata supplied by the caller.
33	 *
34	 * When present, runClaude appends a `rag_pre_flight` log entry to the task YAML
35	 * before spawning Claude and audits the entry on exit. This makes RAG injection
36	 * non-forgeable: the runtime — not the agent — writes the audit record, and
37	 * the runtime verifies the record survives Claude's mutations untouched.
38	 */
39	export interface RagPreFlight {
40	  /** The query string passed to the RAG server. */
41	  query: string;
42	  /** True iff at least one chunk was retrieved. */
43	  injected: boolean;
44	  /**
45	   * Deterministic summary string. Must match one of the patterns enforced by
46	   * `auditRagPreFlight` — see `fetchRagContext` for the vocabulary.
47	   */
48	  summary: string;
49	}
50	
51	export interface RunClaudeOpts {
52	  taskId: string;
53	  featureId: string;
54	  workspaceRoot: string;
55	  taskRepoRoot: string;
56	  /** Absolute path to the workflow repo (contains technical_skills/). */
57	  workflowLocalPath: string;
58	  agentContext: string;
59	  maxTurns: number;
60	  maxTokens: number;
61	  sshKeyPath: string | undefined;
62	  gitAuthorEmail: string;
63	  taskBranch: string;
64	  /** When true, write captured stdout to the JSONL log file and commit+push. */
65	  logSinkEnabled: boolean;
66	  /**
67	   * Optional. When provided, write a `rag_pre_flight` log entry before
68	   * spawning Claude and audit it on exit. Omit for runClaude callers that
69	   * don't need RAG accountability (e.g. PR review dispatch).
70	   */
71	  ragPreFlight?: RagPreFlight;
72	}
73	
74	// ── Helpers ───────────────────────────────────────────────────────────────────
75	
76	function emit(event: Record<string, unknown>): void {
77	  console.log(JSON.stringify({ at: new Date().toISOString(), ...event }));
78	}
79	
80	/**
81	 * Option B — Pre-flight toolchain check.
82	 *
83	 * Detects which package manager / runtime the repo needs by inspecting
84	 * well-known lock files and manifests, then verifies each required tool
85	 * exists via `which`. Returns the list of missing tool names (empty = all OK).
86	 *
87	 * This runs before spawning claude so zero tokens are spent when the
88	 * container image is missing a tool.
89	 */
90	const TOOLCHAIN_MARKERS: Array<{ file: string; tool: string }> = [
91	  { file: "yarn.lock",        tool: "yarn"    },
92	  { file: "pnpm-lock.yaml",   tool: "pnpm"    },
93	  { file: "go.mod",           tool: "go"      },
94	  { file: "requirements.txt", tool: "python3" },
95	  { file: "pyproject.toml",   tool: "python3" },
96	  { file: "Cargo.toml",       tool: "cargo"   },
97	];
98	
99	function checkRequiredTools(taskRepoRoot: string): string[] {
100	  const missing: string[] = [];
101	  const checked = new Set<string>();
102	
103	  for (const { file, tool } of TOOLCHAIN_MARKERS) {
104	    if (checked.has(tool)) continue;
105	    if (!existsSync(join(taskRepoRoot, file))) continue;
106	    checked.add(tool);
107	    try {
108	      execSync(`which ${tool}`, { stdio: "pipe" });
109	    } catch {
110	      missing.push(tool);
111	    }
112	  }
113	
114	  return missing;
115	}
116	
117	/**
118	 * Option A — Hard-stop instruction appended to every agent context.
119	 *
120	 * Safety net for tools the pre-flight doesn't know about (e.g. jq, forge,
121	 * custom CLIs). If the agent hits a 127 exit code for any tool, it must
122	 * block immediately instead of burning turns trying workarounds.
123	 */
124	const MISSING_TOOL_INSTRUCTION = `
125	
126	## Hard stop rule — missing tools
127	If any shell command exits with code 127 ("command not found"), do NOT attempt to install it, use an alternative, or work around it in any way. This is a container environment problem that the runtime must fix — the agent cannot fix it. Immediately set the task status to \`blocked\`, set \`blocked_reason\` to \`missing_tool\`, record which tool was missing in \`blocked_details\`, and stop.`;
128	
129	/**
130	 * Copy the workspace CLAUDE.md to ~/.claude/CLAUDE.md so Claude Code picks up
131	 * workspace rules (commit identity, no co-authorship, no GPG, no gh CLI) regardless
132	 * of which implementation repo it is running against.
133	 */
134	function copyWorkspaceClaude(workspaceRoot: string): void {
135	  const src = join(workspaceRoot, "CLAUDE.md");
136	  if (!existsSync(src)) {
137	    emit({ type: "workspace_claude_md_missing", workspace_root: workspaceRoot });
138	    return;
139	  }
140	  const destDir = join(homedir(), ".claude");
141	  mkdirSync(destDir, { recursive: true });
142	  copyFileSync(src, join(destDir, "CLAUDE.md"));
143	}
144	
145	/**
146	 * Recursively copy a source directory into a destination directory.
147	 * The destination is created if absent. Existing files are overwritten.
148	 */
149	function copyDirRecursive(src: string, dest: string): void {
150	  mkdirSync(dest, { recursive: true });
151	  for (const entry of readdirSync(src)) {
152	    const srcPath = join(src, entry);
153	    const destPath = join(dest, entry);
154	    const stat = lstatSync(srcPath);
155	    if (stat.isDirectory()) {
156	      copyDirRecursive(srcPath, destPath);
157	    } else if (stat.isFile()) {
158	      copyFileSync(srcPath, destPath);
159	    }
160	    // Symlinks inside skill dirs are skipped — they point to container-local paths
161	    // that may not exist and are not needed once the dir is fully copied.
162	  }
163	}
164	
165	/**
166	 * Populate ~/.claude/skills/ with all workflow and workspace-local skills so
167	 * Claude Code can discover them natively regardless of which repo it runs against.
168	 *
169	 * Sources (applied in order — later sources overwrite earlier ones):
170	 *   1. workflowLocalPath/technical_skills/*
171	 *   2. workflowLocalPath/workflow_skills/*
172	 *   3. Non-symlink dirs from workspaceRoot/.claude/skills/* (workspace-local skills)
173	 *
174	 * ~/.claude/skills/ is cleaned before copying to remove stale skills from prior runs.
175	 * Individual copy errors are non-fatal — emits skill_copy_warn and continues.
176	 */
177	function setupGlobalSkills(workspaceRoot: string, workflowLocalPath: string): void {
178	  const globalSkillsDir = join(homedir(), ".claude", "skills");
179	
180	  // Clean stale state from prior task or workspace.
181	  if (existsSync(globalSkillsDir)) {
182	    rmSync(globalSkillsDir, { recursive: true, force: true });
183	  }
184	  mkdirSync(globalSkillsDir, { recursive: true });
185	
186	  let technicalSkills = 0;
187	  let workflowSkills = 0;
188	  let workspaceLocalSkills = 0;
189	
190	  const copySkillsFrom = (sourceDir: string, counter: () => void): void => {
191	    if (!existsSync(sourceDir)) return;
192	    let entries: string[];
193	    try { entries = readdirSync(sourceDir); } catch { return; }
194	    for (const entry of entries) {
195	      const srcPath = join(sourceDir, entry);
196	      try {
197	        const stat = lstatSync(srcPath);
198	        if (!stat.isDirectory()) continue;
199	        copyDirRecursive(srcPath, join(globalSkillsDir, entry));
200	        counter();
201	      } catch (e) {
202	        emit({ type: "skill_copy_warn", skill: entry, details: String(e) });
203	      }
204	    }
205	  };
206	
207	  copySkillsFrom(join(workflowLocalPath, "technical_skills"), () => { technicalSkills++; });
208	  copySkillsFrom(join(workflowLocalPath, "workflow_skills"),  () => { workflowSkills++; });
209	
210	  // Workspace-local skills: non-symlink dirs only (symlinks point to workflow dirs already copied).
211	  const wsSkillsDir = join(workspaceRoot, ".claude", "skills");
212	  if (existsSync(wsSkillsDir)) {
213	    let entries: string[];
214	    try { entries = readdirSync(wsSkillsDir); } catch { entries = []; }
215	    for (const entry of entries) {
216	      if (entry === ".gitignore") continue;
217	      const srcPath = join(wsSkillsDir, entry);
218	      try {
219	        const stat = lstatSync(srcPath);
220	        if (stat.isSymbolicLink() || !stat.isDirectory()) continue;
221	        copyDirRecursive(srcPath, join(globalSkillsDir, entry));
222	        workspaceLocalSkills++;
223	      } catch (e) {
224	        emit({ type: "skill_copy_warn", skill: entry, details: String(e) });
225	      }
226	    }
227	  }
228	
229	  emit({ type: "skills_setup_complete", technical_skills: technicalSkills, workflow_skills: workflowSkills, workspace_local_skills: workspaceLocalSkills });
230	}
231	
232	/**
233	 * Scan stdout lines for token usage across all formats:
234	 *
235	 * - stream-json assistant events:
236	 *     {"type":"assistant","message":{"usage":{"input_tokens":N,"output_tokens":N,...}}}
237	 *   These fire once per turn; we sum all turns for the total.
238	 *
239	 * - Legacy flat usage object (plain-text / json format):
240	 *     {"usage":{"input_tokens":N,"output_tokens":N}}
241	 *
242	 * Returns accumulated total tokens, or undefined if no usage lines are found.
243	 */
244	function extractTotalTokens(stdout: string): number | undefined {
245	  let total = 0;
246	  let found = false;
247	
248	  for (const line of stdout.split("\n")) {
249	    const trimmed = line.trim();
250	    if (!trimmed.startsWith("{")) continue;
251	    try {
252	      const parsed = JSON.parse(trimmed) as Record<string, unknown>;
253	
254	      // stream-json: assistant event carries per-turn usage inside message.
255	      if (parsed.type === "assistant") {
256	        const msg = parsed.message as Record<string, unknown> | undefined;
257	        const usage = msg?.usage as Record<string, unknown> | undefined;
258	        if (
259	          typeof usage?.input_tokens === "number" &&
260	          typeof usage?.output_tokens === "number"
261	        ) {
262	          total += (usage.input_tokens as number) + (usage.output_tokens as number);
263	          found = true;
264	        }
265	        continue;
266	      }
267	
268	      // Legacy flat shape.
269	      const usage = parsed.usage as Record<string, unknown> | undefined;
270	      if (
271	        typeof usage?.input_tokens === "number" &&
272	        typeof usage?.output_tokens === "number"
273	      ) {
274	        total += (usage.input_tokens as number) + (usage.output_tokens as number);
275	        found = true;
276	      }
277	    } catch {
278	      // Not a JSON line — skip.
279	    }
280	  }
281	
282	  return found ? total : undefined;
283	}
284	
285	/**
286	 * Allowed `rag_summary` patterns. These mirror the vocabulary documented in
287	 * `workflow_skills/rag-context/SKILL.md` and produced by `fetchRagContext`.
288	 *
289	 * The audit on exit insists that the `rag_pre_flight` entry's summary still
290	 * matches one of these prefixes — a free-form prose excuse like "RAG context
291	 * provided via system prompt" will fail the audit.
292	 */
293	const RAG_SUMMARY_PATTERNS: RegExp[] = [
294	  /^Retrieved \d+ chunks?:/,
295	  /^tool_unavailable:/,
296	  /^tool_call_failed:/,
297	  /^query_returned_no_chunks$/,
298	];
299	
300	function isAllowedRagSummary(s: string): boolean {
301	  return RAG_SUMMARY_PATTERNS.some((re) => re.test(s));
302	}
303	
304	/**
305	 * Append a `rag_pre_flight` log entry to the task YAML, commit, and push.
306	 *
307	 * Called BEFORE Claude is spawned. The entry is the runtime's authoritative
308	 * record of what RAG context was injected (or why none was). Returns the
309	 * entry written so the caller can audit on exit.
310	 */
311	function writeRagPreFlightAndPush(
312	  workspaceRoot: string,
313	  featureId: string,
314	  taskId: string,
315	  taskBranch: string,
316	  gitAuthorEmail: string,
317	  sshKeyPath: string | undefined,
318	  ragPreFlight: RagPreFlight,
319	): TaskLogEntry {
320	  const now = new Date().toISOString();
321	  const entry: TaskLogEntry = {
322	    action: "rag_pre_flight",
323	    by: gitAuthorEmail,
324	    at: now,
325	    rag_context_injected: ragPreFlight.injected,
326	    rag_summary: ragPreFlight.summary,
327	    rag_query: ragPreFlight.query,
328	    note: "Runtime pre-flight RAG fetch — written before claude spawn.",
329	  };
330	
331	  const yamlPath = taskYamlAbsPath(workspaceRoot, featureId, taskId);
332	  const task = parseYaml(readFileSync(yamlPath, "utf-8")) as Task;
333	  task.log.push(entry);
334	  writeFileSync(yamlPath, yamlStringify(task), "utf-8");
335	
336	  const relPath = taskYamlRelPath(featureId, taskId);
337	  const gitOpts = {
338	    cwd: workspaceRoot,
339	    encoding: "utf-8" as const,
340	    env: buildGitEnv(sshKeyPath),
341	    timeout: 30_000,
342	    stdio: "pipe" as const,
343	  };
344	
345	  execSync(`git add "${relPath}"`, gitOpts);
346	  execSync(
347	    `git commit -m "chore(${taskId}): rag pre-flight — ${ragPreFlight.injected ? "injected" : "skipped"}"`,
348	    gitOpts,
349	  );
350	  execSync(`git push origin "${taskBranch}"`, gitOpts);
351	
352	  return entry;
353	}
354	
355	/**
356	 * Verify the runtime's `rag_pre_flight` entry survived Claude's run unmodified.
357	 *
358	 * Returns `{ ok: true }` when the entry matching `expected.at` is still
359	 * present and has the same summary / injected flag. Otherwise returns
360	 * `{ ok: false, reason }` describing the audit failure.
361	 */
362	function auditRagPreFlight(
363	  task: Task,
364	  expected: TaskLogEntry,
365	): { ok: true } | { ok: false; reason: string } {
366	  if (!isAllowedRagSummary(String(expected.rag_summary ?? ""))) {
367	    // Defensive: should never happen since fetchRagContext is deterministic.
368	    return {
369	      ok: false,
370	      reason: `runtime wrote a non-conforming rag_summary: ${String(expected.rag_summary)}`,
371	    };
372	  }
373	
374	  const found = task.log.find(
375	    (e) => e.action === "rag_pre_flight" && e.at === expected.at,
376	  );
377	
378	  if (!found) {
379	    return {
380	      ok: false,
381	      reason: "rag_pre_flight log entry missing from task YAML — agent removed or rewrote it",
382	    };
383	  }
384	
385	  if (found.rag_summary !== expected.rag_summary) {
386	    return {
387	      ok: false,
388	      reason: `rag_summary mutated: expected ${JSON.stringify(expected.rag_summary)}, got ${JSON.stringify(found.rag_summary)}`,
389	    };
390	  }
391	
392	  if (found.rag_context_injected !== expected.rag_context_injected) {
393	    return {
394	      ok: false,
395	      reason: `rag_context_injected mutated: expected ${expected.rag_context_injected}, got ${found.rag_context_injected}`,
396	    };
397	  }
398	
399	  return { ok: true };
400	}
401	
402	/**
403	 * Write blocked state to the task YAML and commit+push to the management repo.
404	 * Called only when claude exits without updating the task status (still in_progress).
405	 * Writes blocked_context with wip_branch, wip_sha (from git rev-parse HEAD), and pushed_at.
406	 */
407	function writeBlockedAndPush(
408	  workspaceRoot: string,
409	  featureId: string,
410	  taskId: string,
411	  task: Task,
412	  blockedReason: BlockedReason,
413	  note: string,
414	  taskBranch: string,
415	  gitAuthorEmail: string,
416	  sshKeyPath: string | undefined,
417	): void {
418	  const now = new Date().toISOString();
419	  task.status = "blocked";
420	  task.blocked_reason = blockedReason;
421	
422	  let wipSha = "unknown";
423	  try {
424	    wipSha = execSync(
425	      `git -C "${workspaceRoot}" rev-parse HEAD`,
426	      { encoding: "utf-8", stdio: "pipe" },
427	    ).trim();
428	  } catch {
429	    // best-effort; leave wipSha as "unknown" if rev-parse fails
430	  }
431	  task.blocked_context = {
432	    wip_branch: taskBranch,
433	    wip_sha: wipSha,
434	    pushed_at: now,
435	  };
436	
437	  task.execution.last_updated_by = gitAuthorEmail;
438	  task.execution.last_updated_at = now;
439	  task.log.push({ action: "blocked", by: gitAuthorEmail, at: now, note });
440	
441	  const yamlPath = taskYamlAbsPath(workspaceRoot, featureId, taskId);
442	  writeFileSync(yamlPath, yamlStringify(task));
443	
444	  const relPath = taskYamlRelPath(featureId, taskId);
445	  const opts = { cwd: workspaceRoot, encoding: "utf-8" as const, env: buildGitEnv(sshKeyPath), timeout: 30_000 };
446	
447	  execSync(`git add "${relPath}"`, opts);
448	  execSync(
449	    `git commit -m "chore(${taskId}): blocked — ${blockedReason}"`,
450	    opts,
451	  );
452	  execSync("git push origin HEAD", opts);
453	}
454	
455	/**
456	 * Write captured claude stdout to the per-run JSONL log file and commit+push.
457	 * The file contains: run_started event, raw claude output, run_ended event.
458	 * Raw claude output lines are written as-is — they may or may not be JSON.
459	 */
460	function flushLogAndPush(
461	  workspaceRoot: string,
462	  featureId: string,
463	  taskId: string,
464	  taskBranch: string,
465	  runStartIso: string,
466	  gitAuthorEmail: string,
467	  stdout: string,
468	  outcome: string,
469	  sshKeyPath: string | undefined,
470	): void {
471	  const logPath = deriveLogPath(workspaceRoot, featureId, taskId, runStartIso);
472	  mkdirSync(featureLogsDirPath(workspaceRoot, featureId, taskId), { recursive: true });
473	
474	  // Header event — written synchronously so partial logs are still useful.
475	  appendFileSync(
476	    logPath,
477	    JSON.stringify({ at: runStartIso, by: gitAuthorEmail, type: "run_started" }) + "\n",
478	  );
479	
480	  // Raw claude output (may be plain text or JSON events).
481	  // Redact secrets before writing — curl headers and bash commands in tool_use
482	  // inputs can contain API tokens verbatim.
483	  if (stdout) {
484	    const redacted = redactSecrets(stdout);
485	    appendFileSync(logPath, redacted);
486	    if (!redacted.endsWith("\n")) appendFileSync(logPath, "\n");
487	  }
488	
489	  // Footer event.
490	  appendFileSync(
491	    logPath,
492	    JSON.stringify({ at: new Date().toISOString(), by: gitAuthorEmail, type: "run_ended", details: { outcome } }) + "\n",
493	  );
494	
495	  const logFilename = `${toSafeIso(runStartIso)}.jsonl`;
496	  const relPath = logFileRelPath(featureId, taskId, logFilename);
497	  const gitAuthorName = process.env.GIT_AUTHOR_NAME ?? gitAuthorEmail;
498	  const env = buildGitCommitEnv(gitAuthorEmail, gitAuthorName, sshKeyPath);
499	  const GIT_PUSH_TIMEOUT = 30_000;
500	
501	  // Ensure we are on the feature branch regardless of what Claude's skills
502	  // may have done to the management repo HEAD during execution.
503	  const gitOpts = { env, stdio: "pipe" as const, timeout: GIT_PUSH_TIMEOUT };
504	  execSync(`git -C "${workspaceRoot}" checkout "${taskBranch}"`, gitOpts);
505	  execSync(`git -C "${workspaceRoot}" add "${relPath}"`, gitOpts);
506	  execSync(`git -C "${workspaceRoot}" commit -m "chore: flush task log ${taskId}"`, gitOpts);
507	  execSync(`git -C "${workspaceRoot}" push origin "${taskBranch}"`, gitOpts);
508	}
509	
510	// ── Main export ───────────────────────────────────────────────────────────────
511	
512	/**
513	 * Invoke `claude -p <agentContext> --max-turns <n>` as a subprocess, then
514	 * read the task YAML to determine the outcome.
515	 */
516	export async function runClaude(opts: RunClaudeOpts): Promise<RunClaudeResult> {
517	  const {
518	    taskId,
519	    featureId,
520	    workspaceRoot,
521	    taskRepoRoot,
522	    workflowLocalPath,
523	    agentContext,
524	    maxTurns,
525	    maxTokens,
526	    sshKeyPath,
527	    gitAuthorEmail,
528	    taskBranch,
529	    logSinkEnabled,
530	  } = opts;
531	
532	  const runStartIso = new Date().toISOString();
533	
534	  // Build subprocess environment — inject SSH command and agent-runtime marker.
535	  const env = { ...buildGitEnv(sshKeyPath), CLAUDE_AGENT_RUNTIME: "1" };
536	
537	  // ── Option B: Pre-flight toolchain check ─────────────────────────────────
538	  // Verify required tools exist before spending any tokens. If a tool is
539	  // missing the container image must be fixed — block immediately.
540	  const missingTools = checkRequiredTools(taskRepoRoot);
541	  if (missingTools.length > 0) {
542	    const details = `missing tools in container: ${missingTools.join(", ")}`;
543	    emit({ type: "preflight_failed", task_id: taskId, feature_id: featureId, reason: "missing_tool", details });
544	    return { outcome: "blocked", reason: "missing_tool", details };
545	  }
546	
547	  // ── Workspace rules + global skills ──────────────────────────────────────
548	  // Copy workspace CLAUDE.md → ~/.claude/CLAUDE.md so workspace rules apply
549	  // regardless of which repo Claude runs against.
550	  // Copy all skills → ~/.claude/skills/ so Claude discovers them natively
551	  // without polluting the task repo's working tree.
552	  copyWorkspaceClaude(workspaceRoot);
553	  setupGlobalSkills(workspaceRoot, workflowLocalPath);
554	
555	  // ── Option A: Append hard-stop instruction ───────────────────────────────
556	  // Fallback for tools the pre-flight doesn't know about.
557	  const effectiveAgentContext = agentContext + MISSING_TOOL_INSTRUCTION;
558	
559	  // ── MCP server registration ───────────────────────────────────────────────
560	  // Build a single --mcp-config file combining all available MCP servers:
561	  //   - rag-server (SSE): enabled when MCP_RAG_URL is set
562	  //   - figma (stdio):    enabled when FIGMA_PERSONAL_ACCESS_TOKEN is set
563	  // Agents degrade gracefully when either is absent.
564	  const mcpArgs: string[] = [];
565	  const mcpRagUrl = process.env.MCP_RAG_URL;
566	  const figmaToken = process.env.FIGMA_PERSONAL_ACCESS_TOKEN;
567	
568	  if (mcpRagUrl || figmaToken) {
569	    const mcpConfig: { mcpServers: Record<string, unknown> } = { mcpServers: {} };
570	
571	    if (mcpRagUrl) {
572	      mcpConfig.mcpServers["rag-server"] = { type: "sse", url: `${mcpRagUrl}/sse` };
573	      emit({ type: "mcp_rag_registered", task_id: taskId, feature_id: featureId, url: mcpRagUrl });
574	    }
575	
576	    if (figmaToken) {
577	      mcpConfig.mcpServers["figma"] = {
578	        type: "stdio",
579	        command: "npx",
580	        args: ["-y", "@figma/mcp-server"],
581	        env: { FIGMA_PERSONAL_ACCESS_TOKEN: figmaToken },
582	      };
583	      emit({ type: "mcp_figma_registered", task_id: taskId, feature_id: featureId });
584	    }
585	
586	    const mcpConfigPath = `/tmp/mcp-config-${taskId}.json`;
587	    writeFileSync(mcpConfigPath, JSON.stringify(mcpConfig));
588	    mcpArgs.push("--mcp-config", mcpConfigPath);
589	  }
590	
591	  // ── RAG pre-flight audit record ──────────────────────────────────────────
592	  // Append the runtime-authoritative `rag_pre_flight` entry to the task YAML
593	  // before spawning Claude. We hold onto the entry so we can verify on exit
594	  // that the agent didn't tamper with it.
595	  let ragPreFlightEntry: TaskLogEntry | null = null;
596	  if (opts.ragPreFlight) {
597	    try {
598	      ragPreFlightEntry = writeRagPreFlightAndPush(
599	        workspaceRoot,
600	        featureId,
601	        taskId,
602	        taskBranch,
603	        gitAuthorEmail,
604	        sshKeyPath,
605	        opts.ragPreFlight,
606	      );
607	      emit({
608	        type: "rag_pre_flight_recorded",
609	        task_id: taskId,
610	        feature_id: featureId,
611	        injected: opts.ragPreFlight.injected,
612	        summary: opts.ragPreFlight.summary,
613	      });
614	    } catch (e) {
615	      // If we can't write the audit record, fail closed — better to block than
616	      // run unaudited.
617	      const details = `failed to write rag_pre_flight entry: ${String(e)}`;
618	      emit({ type: "rag_pre_flight_failed", task_id: taskId, feature_id: featureId, details });
619	      return { outcome: "blocked", reason: "runtime_error", details };
620	    }
621	  }
622	
623	  emit({ type: "claude_spawn", task_id: taskId, feature_id: featureId, max_turns: maxTurns });
624	
625	  // Use async spawn so stdout streams to the container log in real-time
626	  // while also being captured for the JSONL log sink.
627	  const spawnResult = await new Promise<{
628	    stdout: string;
629	    status: number | null;
630	    signal: string | null;
631	    error?: Error;
632	  }>((resolve) => {
633	    const stdoutChunks: string[] = [];
634	
635	    const child = spawn(
636	      "claude",
637	      [
638	        "-p", effectiveAgentContext,
639	        "--max-turns", String(maxTurns),
640	        "--output-format", "stream-json",
641	        "--verbose",
642	        "--dangerously-skip-permissions",
643	        ...mcpArgs,
644	      ],
645	      { cwd: taskRepoRoot, env },
646	    );
647	
648	    child.stdout.setEncoding("utf-8");
649	    child.stderr.setEncoding("utf-8");
650	
651	    // Tee stdout: capture for log sink + stream to container stdout.
652	    // Also watch for the stream-json `result` event: once Claude has emitted
653	    // its final result, start a 30-second watchdog. If the Claude process has
654	    // not exited by then (e.g. because a background bash subprocess inherited
655	    // the stdio fd and is keeping the pipe open), kill it so we don't hang
656	    // indefinitely waiting for `close`.
657	    let resultWatchdog: ReturnType<typeof setTimeout> | null = null;
658	    child.stdout.on("data", (chunk: string) => {
659	      stdoutChunks.push(chunk);
660	      process.stdout.write(chunk);
661	      if (resultWatchdog === null && chunk.includes('"type":"result"')) {
662	        resultWatchdog = setTimeout(() => {
663	          if (!child.killed) child.kill("SIGTERM");
664	        }, 30_000);
665	      }
666	    });
667	
668	    // Surface claude's stderr directly to the container log.
669	    child.stderr.on("data", (chunk: string) => {
670	      process.stderr.write(chunk);
671	    });
672	
673	    child.on("error", (error: Error) => {
674	      if (resultWatchdog !== null) clearTimeout(resultWatchdog);
675	      resolve({ stdout: stdoutChunks.join(""), status: null, signal: null, error });
676	    });
677	
678	    // Use 'exit' + setTimeout(0) rather than relying solely on 'close': if
679	    // Claude spawned background processes via Bash tool use, those grandchildren
680	    // inherit the stdout pipe fd and keep it open after Claude exits — 'close'
681	    // would never fire. setTimeout(0) lets buffered 'data' events drain in the
682	    // current poll phase before we destroy the streams, which causes 'close'
683	    // to fire immediately after.
684	    child.on("exit", () => {
685	      if (resultWatchdog !== null) clearTimeout(resultWatchdog);
686	      setTimeout(() => {
687	        if (!child.stdout.destroyed) child.stdout.destroy();
688	        if (!child.stderr.destroyed) child.stderr.destroy();
689	      }, 0);
690	    });
691	
692	    child.on("close", (code: number | null, signal: string | null) => {
693	      resolve({ stdout: stdoutChunks.join(""), status: code, signal });
694	    });
695	  });
696	
697	  emit({
698	    type: "claude_exit",
699	    task_id: taskId,
700	    feature_id: featureId,
701	    exit_code: spawnResult.status,
702	    signal: spawnResult.signal ?? null,
703	  });
704	
705	  // ── Token audit (D3) ──────────────────────────────────────────────────────
706	  const totalTokens =
707	    spawnResult.stdout ? extractTotalTokens(spawnResult.stdout) : undefined;
708	
709	  if (totalTokens === undefined) {
710	    emit({
711	      type: "budget_audit_skipped",
712	      task_id: taskId,
713	      feature_id: featureId,
714	      reason: "usage format not found in stdout",
715	    });
716	  } else {
717	    emit({ type: "budget_audit", task_id: taskId, feature_id: featureId, total_tokens: totalTokens, max_tokens: maxTokens });
718	  }
719	
720	  // ── Outcome determination ─────────────────────────────────────────────────
721	  let result: RunClaudeResult;
722	
723	  let task: Task;
724	  try {
725	    task = parseYaml(
726	      readFileSync(taskYamlAbsPath(workspaceRoot, featureId, taskId), "utf-8"),
727	    ) as Task;
728	  } catch (e) {
729	    result = {
730	      outcome: "blocked",
731	      reason: "runtime_error",
732	      details: `Failed to read task YAML after claude exit: ${String(e)}`,
733	    };
734	    // Log flush is best-effort when the task YAML itself is unreadable.
735	    if (logSinkEnabled) {
736	      try {
737	        flushLogAndPush(workspaceRoot, featureId, taskId, taskBranch, runStartIso, gitAuthorEmail, spawnResult.stdout ?? "", result.outcome, sshKeyPath);
738	      } catch (logErr) {
739	        emit({ type: "log_flush_failed", task_id: taskId, feature_id: featureId, details: String(logErr) });
740	      }
741	    }
742	    return result;
743	  }
744	
745	  // Re-serialise through yamlStringify so any bare scalars Claude wrote that
746	  // contain ": " (e.g. "Test suite: 5 passed") get properly quoted.
747	  // Commit + push only when the content actually changed.
748	  try {
749	    const taskYamlPath = taskYamlAbsPath(workspaceRoot, featureId, taskId);
750	    const original = readFileSync(taskYamlPath, "utf-8");
751	    const normalised = yamlStringify(task);
752	    if (normalised !== original) {
753	      writeFileSync(taskYamlPath, normalised, "utf-8");
754	      const relPath = taskYamlRelPath(featureId, taskId);
755	      const gitOpts = { cwd: workspaceRoot, encoding: "utf-8" as const, env: buildGitEnv(sshKeyPath), timeout: 30_000 };
756	      execSync(`git add "${relPath}"`, gitOpts);
757	      execSync(`git commit -m "chore(${taskId}): normalise task YAML"`, gitOpts);
758	      execSync(`git push origin "${taskBranch}"`, gitOpts);
759	      emit({ type: "task_yaml_normalised", task_id: taskId, feature_id: featureId });
760	    }
761	  } catch (normErr) {
762	    emit({ type: "task_yaml_normalise_failed", task_id: taskId, feature_id: featureId, details: String(normErr) });
763	  }
764	
765	  // ── RAG pre-flight audit ──────────────────────────────────────────────────
766	  // If the runtime wrote a `rag_pre_flight` entry before spawning, confirm it
767	  // survived intact. Mutation/removal forces a runtime_error block — the run
768	  // is unauditable, treat it as failed regardless of the agent's claimed
769	  // outcome.
770	  if (ragPreFlightEntry) {
771	    const audit = auditRagPreFlight(task, ragPreFlightEntry);
772	    if (!audit.ok) {
773	      const details = `rag_audit_failed: ${audit.reason}`;
774	      emit({
775	        type: "rag_audit_failed",
776	        task_id: taskId,
777	        feature_id: featureId,
778	        reason: audit.reason,
779	      });
780	      try {
781	        writeBlockedAndPush(workspaceRoot, featureId, taskId, task, "runtime_error", details, taskBranch, gitAuthorEmail, sshKeyPath);
782	      } catch (pushErr) {
783	        emit({ type: "blocked_push_failed", task_id: taskId, feature_id: featureId, details: String(pushErr) });
784	      }
785	      result = { outcome: "blocked", reason: "runtime_error", details };
786	
787	      // Flush logs (best-effort) and return early — skip the normal outcome
788	      // determination below since we've already overridden it.
789	      if (logSinkEnabled) {
790	        try {
791	          flushLogAndPush(workspaceRoot, featureId, taskId, taskBranch, runStartIso, gitAuthorEmail, spawnResult.stdout ?? "", result.outcome, sshKeyPath);
792	        } catch (logErr) {
793	          emit({ type: "log_flush_failed", task_id: taskId, feature_id: featureId, details: String(logErr) });
794	        }
795	      }
796	      return result;
797	    }
798	  }
799	
800	  if (task.status === "in_review") {
801	    result = { outcome: "in_review" };
802	  } else if (task.status === "blocked") {
803	    const reason = task.blocked_reason ?? "unknown";
804	    // Token overage takes precedence over the agent's own blocked_reason.
805	    if (totalTokens !== undefined && totalTokens > maxTokens) {
806	      result = {
807	        outcome: "blocked",
808	        reason: "budget_exceeded",
809	        details: {
810	          total_tokens: totalTokens,
811	          max_tokens: maxTokens,
812	          original_reason: reason,
813	        },
814	      };
815	    } else {
816	      result = { outcome: "blocked", reason, details: task.blocked_details };
817	    }
818	  } else {
819	    // Task is still in_progress — claude exited without completing the task.
820	    const note =
821	      spawnResult.error
822	        ? `process error: ${spawnResult.error.message}`
823	        : `task still in_progress after claude exit (code ${spawnResult.status ?? "null"})`;
824	
825	    emit({ type: "task_blocked", task_id: taskId, feature_id: featureId, reason: "runtime_error", note });
826	
827	    try {
828	      writeBlockedAndPush(workspaceRoot, featureId, taskId, task, "runtime_error", note, taskBranch, gitAuthorEmail, sshKeyPath);
829	    } catch (pushErr) {
830	      emit({ type: "blocked_push_failed", task_id: taskId, feature_id: featureId, details: String(pushErr) });
831	    }
832	
833	    result = { outcome: "blocked", reason: "runtime_error", details: note };
834	  }
835	
836	  // ── Flush log to management repo ──────────────────────────────────────────
837	  if (logSinkEnabled) {
838	    try {
839	      flushLogAndPush(
840	        workspaceRoot,
841	        featureId,
842	        taskId,
843	        taskBranch,
844	        runStartIso,
845	        gitAuthorEmail,
846	        spawnResult.stdout ?? "",
847	        result.outcome,
848	        sshKeyPath,
849	      );
850	    } catch (logErr) {
851	      emit({ type: "log_flush_failed", task_id: taskId, feature_id: featureId, details: String(logErr) });
852	    }
853	  }
854	
855	  return result;
856	}
