/**
 * T5: Claude Code CLI subprocess invocation.
 *
 * Replaces the raw Anthropic SDK tool-use loop (run-task.ts) with a thin
 * wrapper around `claude -p <agentContext> --max-turns <n>`. After the
 * subprocess exits, the task YAML is read to determine the outcome.
 *
 * Token audit (D3 option X / Y):
 *   Attempt to find a JSON usage line in stdout. If found and total tokens
 *   exceed maxTokens, override the outcome to budget_exceeded. If the format
 *   is not found, emit budget_audit_skipped and continue (option Y).
 */

import { spawn, execSync } from "node:child_process";
import { mkdirSync, appendFileSync, readFileSync, writeFileSync, existsSync, readdirSync, rmSync, copyFileSync, lstatSync } from "node:fs";
import { join } from "node:path";
import { homedir } from "node:os";
import { parse as parseYaml, stringify as yamlStringify } from "yaml";
import type { Task, BlockedReason, TaskLogEntry } from "../types/task.js";
import { taskYamlAbsPath, taskYamlRelPath, featureLogsDirPath, logFileRelPath } from "../paths.js";
import { deriveLogPath, toSafeIso } from "../logging/log-sink.js";
import { redactSecrets } from "../logging/redact-secrets.js";
import { buildGitEnv, buildGitCommitEnv } from "../git-env.js";

// ── Public types ──────────────────────────────────────────────────────────────

export type RunClaudeResult =
  | { outcome: "in_review" }
  | { outcome: "blocked"; reason: string; details?: unknown };

/**
 * RAG pre-flight metadata supplied by the caller.
 *
 * When present, runClaude appends a `rag_pre_flight` log entry to the task YAML
 * before spawning Claude and audits the entry on exit. This makes RAG injection
 * non-forgeable: the runtime — not the agent — writes the audit record, and
 * the runtime verifies the record survives Claude's mutations untouched.
 */
export interface RagPreFlight {
  /** The query string passed to the RAG server. */
  query: string;
  /** True iff at least one chunk was retrieved. */
  injected: boolean;
  /**
   * Deterministic summary string. Must match one of the patterns enforced by
   * `auditRagPreFlight` — see `fetchRagContext` for the vocabulary.
   */
  summary: string;
}

export interface RunClaudeOpts {
  taskId: string;
  featureId: string;
  workspaceRoot: string;
  taskRepoRoot: string;
  /** Absolute path to the workflow repo (contains technical_skills/). */
  workflowLocalPath: string;
  agentContext: string;
  maxTurns: number;
  maxTokens: number;
  sshKeyPath: string | undefined;
  gitAuthorEmail: string;
  taskBranch: string;
  /** When true, write captured stdout to the JSONL log file and commit+push. */
  logSinkEnabled: boolean;
  /**
   * Optional. When provided, write a `rag_pre_flight` log entry before
   * spawning Claude and audit it on exit. Omit for runClaude callers that
   * don't need RAG accountability (e.g. PR review dispatch).
   */
  ragPreFlight?: RagPreFlight;
}

// ── Helpers ───────────────────────────────────────────────────────────────────

function emit(event: Record<string, unknown>): void {
  console.log(JSON.stringify({ at: new Date().toISOString(), ...event }));
}

/**
 * Option B — Pre-flight toolchain check.
 *
 * Detects which package manager / runtime the repo needs by inspecting
 * well-known lock files and manifests, then verifies each required tool
 * exists via `which`. Returns the list of missing tool names (empty = all OK).
 *
 * This runs before spawning claude so zero tokens are spent when the
 * container image is missing a tool.
 */
const TOOLCHAIN_MARKERS: Array<{ file: string; tool: string }> = [
  { file: "yarn.lock",        tool: "yarn"    },
  { file: "pnpm-lock.yaml",   tool: "pnpm"    },
  { file: "go.mod",           tool: "go"      },
  { file: "requirements.txt", tool: "python3" },
  { file: "pyproject.toml",   tool: "python3" },
  { file: "Cargo.toml",       tool: "cargo"   },
];

function checkRequiredTools(taskRepoRoot: string): string[] {
  const missing: string[] = [];
  const checked = new Set<string>();

  for (const { file, tool } of TOOLCHAIN_MARKERS) {
    if (checked.has(tool)) continue;
    if (!existsSync(join(taskRepoRoot, file))) continue;
    checked.add(tool);
    try {
      execSync(`which ${tool}`, { stdio: "pipe" });
    } catch {
      missing.push(tool);
    }
  }

  return missing;
}

/**
 * Option A — Hard-stop instruction appended to every agent context.
 *
 * Safety net for tools the pre-flight doesn't know about (e.g. jq, forge,
 * custom CLIs). If the agent hits a 127 exit code for any tool, it must
 * block immediately instead of burning turns trying workarounds.
 */
const MISSING_TOOL_INSTRUCTION = `

## Hard stop rule — missing tools
If any shell command exits with code 127 ("command not found"), do NOT attempt to install it, use an alternative, or work around it in any way. This is a container environment problem that the runtime must fix — the agent cannot fix it. Immediately set the task status to \`blocked\`, set \`blocked_reason\` to \`missing_tool\`, record which tool was missing in \`blocked_details\`, and stop.`;

/**
 * Copy the workspace CLAUDE.md to ~/.claude/CLAUDE.md so Claude Code picks up
 * workspace rules (commit identity, no co-authorship, no GPG, no gh CLI) regardless
 * of which implementation repo it is running against.
 */
function copyWorkspaceClaude(workspaceRoot: string): void {
  const src = join(workspaceRoot, "CLAUDE.md");
  if (!existsSync(src)) {
    emit({ type: "workspace_claude_md_missing", workspace_root: workspaceRoot });
    return;
  }
  const destDir = join(homedir(), ".claude");
  mkdirSync(destDir, { recursive: true });
  copyFileSync(src, join(destDir, "CLAUDE.md"));
}

/**
 * Recursively copy a source directory into a destination directory.
 * The destination is created if absent. Existing files are overwritten.
 */
function copyDirRecursive(src: string, dest: string): void {
  mkdirSync(dest, { recursive: true });
  for (const entry of readdirSync(src)) {
    const srcPath = join(src, entry);
    const destPath = join(dest, entry);
    const stat = lstatSync(srcPath);
    if (stat.isDirectory()) {
      copyDirRecursive(srcPath, destPath);
    } else if (stat.isFile()) {
      copyFileSync(srcPath, destPath);
    }
    // Symlinks inside skill dirs are skipped — they point to container-local paths
    // that may not exist and are not needed once the dir is fully copied.
  }
}

/**
 * Populate ~/.claude/skills/ with all workflow and workspace-local skills so
 * Claude Code can discover them natively regardless of which repo it runs against.
 *
 * Sources (applied in order — later sources overwrite earlier ones):
 *   1. workflowLocalPath/technical_skills/*
 *   2. workflowLocalPath/workflow_skills/*
 *   3. Non-symlink dirs from workspaceRoot/.claude/skills/* (workspace-local skills)
 *
 * ~/.claude/skills/ is cleaned before copying to remove stale skills from prior runs.
 * Individual copy errors are non-fatal — emits skill_copy_warn and continues.
 */
function setupGlobalSkills(workspaceRoot: string, workflowLocalPath: string): void {
  const globalSkillsDir = join(homedir(), ".claude", "skills");

  // Clean stale state from prior task or workspace.
  if (existsSync(globalSkillsDir)) {
    rmSync(globalSkillsDir, { recursive: true, force: true });
  }
  mkdirSync(globalSkillsDir, { recursive: true });

  let technicalSkills = 0;
  let workflowSkills = 0;
  let workspaceLocalSkills = 0;

  const copySkillsFrom = (sourceDir: string, counter: () => void): void => {
    if (!existsSync(sourceDir)) return;
    let entries: string[];
    try { entries = readdirSync(sourceDir); } catch { return; }
    for (const entry of entries) {
      const srcPath = join(sourceDir, entry);
      try {
        const stat = lstatSync(srcPath);
        if (!stat.isDirectory()) continue;
        copyDirRecursive(srcPath, join(globalSkillsDir, entry));
        counter();
      } catch (e) {
        emit({ type: "skill_copy_warn", skill: entry, details: String(e) });
      }
    }
  };

  copySkillsFrom(join(workflowLocalPath, "technical_skills"), () => { technicalSkills++; });
  copySkillsFrom(join(workflowLocalPath, "workflow_skills"),  () => { workflowSkills++; });

  // Workspace-local skills: non-symlink dirs only (symlinks point to workflow dirs already copied).
  const wsSkillsDir = join(workspaceRoot, ".claude", "skills");
  if (existsSync(wsSkillsDir)) {
    let entries: string[];
    try { entries = readdirSync(wsSkillsDir); } catch { entries = []; }
    for (const entry of entries) {
      if (entry === ".gitignore") continue;
      const srcPath = join(wsSkillsDir, entry);
      try {
        const stat = lstatSync(srcPath);
        if (stat.isSymbolicLink() || !stat.isDirectory()) continue;
        copyDirRecursive(srcPath, join(globalSkillsDir, entry));
        workspaceLocalSkills++;
      } catch (e) {
        emit({ type: "skill_copy_warn", skill: entry, details: String(e) });
      }
    }
  }

  emit({ type: "skills_setup_complete", technical_skills: technicalSkills, workflow_skills: workflowSkills, workspace_local_skills: workspaceLocalSkills });
}

/**
 * Scan stdout lines for token usage across all formats:
 *
 * - stream-json assistant events:
 *     {"type":"assistant","message":{"usage":{"input_tokens":N,"output_tokens":N,...}}}
 *   These fire once per turn; we sum all turns for the total.
 *
 * - Legacy flat usage object (plain-text / json format):
 *     {"usage":{"input_tokens":N,"output_tokens":N}}
 *
 * Returns accumulated total tokens, or undefined if no usage lines are found.
 */
function extractTotalTokens(stdout: string): number | undefined {
  let total = 0;
  let found = false;

  for (const line of stdout.split("\n")) {
    const trimmed = line.trim();
    if (!trimmed.startsWith("{")) continue;
    try {
      const parsed = JSON.parse(trimmed) as Record<string, unknown>;

      // stream-json: assistant event carries per-turn usage inside message.
      if (parsed.type === "assistant") {
        const msg = parsed.message as Record<string, unknown> | undefined;
        const usage = msg?.usage as Record<string, unknown> | undefined;
        if (
          typeof usage?.input_tokens === "number" &&
          typeof usage?.output_tokens === "number"
        ) {
          total += (usage.input_tokens as number) + (usage.output_tokens as number);
          found = true;
        }
        continue;
      }

      // Legacy flat shape.
      const usage = parsed.usage as Record<string, unknown> | undefined;
      if (
        typeof usage?.input_tokens === "number" &&
        typeof usage?.output_tokens === "number"
      ) {
        total += (usage.input_tokens as number) + (usage.output_tokens as number);
        found = true;
      }
    } catch {
      // Not a JSON line — skip.
    }
  }

  return found ? total : undefined;
}

/**
 * Allowed `rag_summary` patterns. These mirror the vocabulary documented in
 * `workflow_skills/rag-context/SKILL.md` and produced by `fetchRagContext`.
 *
 * The audit on exit insists that the `rag_pre_flight` entry's summary still
 * matches one of these prefixes — a free-form prose excuse like "RAG context
 * provided via system prompt" will fail the audit.
 */
const RAG_SUMMARY_PATTERNS: RegExp[] = [
  /^Retrieved \d+ chunks?:/,
  /^tool_unavailable:/,
  /^tool_call_failed:/,
  /^query_returned_no_chunks$/,
];

function isAllowedRagSummary(s: string): boolean {
  return RAG_SUMMARY_PATTERNS.some((re) => re.test(s));
}

/**
 * Append a `rag_pre_flight` log entry to the task YAML, commit, and push.
 *
 * Called BEFORE Claude is spawned. The entry is the runtime's authoritative
 * record of what RAG context was injected (or why none was). Returns the
 * entry written so the caller can audit on exit.
 */
function writeRagPreFlightAndPush(
  workspaceRoot: string,
  featureId: string,
  taskId: string,
  taskBranch: string,
  gitAuthorEmail: string,
  sshKeyPath: string | undefined,
  ragPreFlight: RagPreFlight,
): TaskLogEntry {
  const now = new Date().toISOString();
  const entry: TaskLogEntry = {
    action: "rag_pre_flight",
    by: gitAuthorEmail,
    at: now,
    rag_context_injected: ragPreFlight.injected,
    rag_summary: ragPreFlight.summary,
    rag_query: ragPreFlight.query,
    note: "Runtime pre-flight RAG fetch — written before claude spawn.",
  };

  const yamlPath = taskYamlAbsPath(workspaceRoot, featureId, taskId);
  const task = parseYaml(readFileSync(yamlPath, "utf-8")) as Task;
  task.log.push(entry);
  writeFileSync(yamlPath, yamlStringify(task), "utf-8");

  const relPath = taskYamlRelPath(featureId, taskId);
  const gitOpts = {
    cwd: workspaceRoot,
    encoding: "utf-8" as const,
    env: buildGitEnv(sshKeyPath),
    timeout: 30_000,
    stdio: "pipe" as const,
  };

  execSync(`git add "${relPath}"`, gitOpts);
  execSync(
    `git commit -m "chore(${taskId}): rag pre-flight — ${ragPreFlight.injected ? "injected" : "skipped"}"`,
    gitOpts,
  );
  execSync(`git push origin "${taskBranch}"`, gitOpts);

  return entry;
}

/**
 * Verify the runtime's `rag_pre_flight` entry survived Claude's run unmodified.
 *
 * Returns `{ ok: true }` when the entry matching `expected.at` is still
 * present and has the same summary / injected flag. Otherwise returns
 * `{ ok: false, reason }` describing the audit failure.
 */
function auditRagPreFlight(
  task: Task,
  expected: TaskLogEntry,
): { ok: true } | { ok: false; reason: string } {
  if (!isAllowedRagSummary(String(expected.rag_summary ?? ""))) {
    // Defensive: should never happen since fetchRagContext is deterministic.
    return {
      ok: false,
      reason: `runtime wrote a non-conforming rag_summary: ${String(expected.rag_summary)}`,
    };
  }

  const found = task.log.find(
    (e) => e.action === "rag_pre_flight" && e.at === expected.at,
  );

  if (!found) {
    return {
      ok: false,
      reason: "rag_pre_flight log entry missing from task YAML — agent removed or rewrote it",
    };
  }

  if (found.rag_summary !== expected.rag_summary) {
    return {
      ok: false,
      reason: `rag_summary mutated: expected ${JSON.stringify(expected.rag_summary)}, got ${JSON.stringify(found.rag_summary)}`,
    };
  }

  if (found.rag_context_injected !== expected.rag_context_injected) {
    return {
      ok: false,
      reason: `rag_context_injected mutated: expected ${expected.rag_context_injected}, got ${found.rag_context_injected}`,
    };
  }

  return { ok: true };
}

/**
 * Write blocked state to the task YAML and commit+push to the management repo.
 * Called only when claude exits without updating the task status (still in_progress).
 * Writes blocked_context with wip_branch, wip_sha (from git rev-parse HEAD), and pushed_at.
 */
function writeBlockedAndPush(
  workspaceRoot: string,
  featureId: string,
  taskId: string,
  task: Task,
  blockedReason: BlockedReason,
  note: string,
  taskBranch: string,
  gitAuthorEmail: string,
  sshKeyPath: string | undefined,
): void {
  const now = new Date().toISOString();
  task.status = "blocked";
  task.blocked_reason = blockedReason;

  let wipSha = "unknown";
  try {
    wipSha = execSync(
      `git -C "${workspaceRoot}" rev-parse HEAD`,
      { encoding: "utf-8", stdio: "pipe" },
    ).trim();
  } catch {
    // best-effort; leave wipSha as "unknown" if rev-parse fails
  }
  task.blocked_context = {
    wip_branch: taskBranch,
    wip_sha: wipSha,
    pushed_at: now,
  };

  task.execution.last_updated_by = gitAuthorEmail;
  task.execution.last_updated_at = now;
  task.log.push({ action: "blocked", by: gitAuthorEmail, at: now, note });

  const yamlPath = taskYamlAbsPath(workspaceRoot, featureId, taskId);
  writeFileSync(yamlPath, yamlStringify(task));

  const relPath = taskYamlRelPath(featureId, taskId);
  const opts = { cwd: workspaceRoot, encoding: "utf-8" as const, env: buildGitEnv(sshKeyPath), timeout: 30_000 };

  execSync(`git add "${relPath}"`, opts);
  execSync(
    `git commit -m "chore(${taskId}): blocked — ${blockedReason}"`,
    opts,
  );
  execSync("git push origin HEAD", opts);
}

/**
 * Write captured claude stdout to the per-run JSONL log file and commit+push.
 * The file contains: run_started event, raw claude output, run_ended event.
 * Raw claude output lines are written as-is — they may or may not be JSON.
 */
function flushLogAndPush(
  workspaceRoot: string,
  featureId: string,
  taskId: string,
  taskBranch: string,
  runStartIso: string,
  gitAuthorEmail: string,
  stdout: string,
  outcome: string,
  sshKeyPath: string | undefined,
): void {
  const logPath = deriveLogPath(workspaceRoot, featureId, taskId, runStartIso);
  mkdirSync(featureLogsDirPath(workspaceRoot, featureId, taskId), { recursive: true });

  // Header event — written synchronously so partial logs are still useful.
  appendFileSync(
    logPath,
    JSON.stringify({ at: runStartIso, by: gitAuthorEmail, type: "run_started" }) + "\n",
  );

  // Raw claude output (may be plain text or JSON events).
  // Redact secrets before writing — curl headers and bash commands in tool_use
  // inputs can contain API tokens verbatim.
  if (stdout) {
    const redacted = redactSecrets(stdout);
    appendFileSync(logPath, redacted);
    if (!redacted.endsWith("\n")) appendFileSync(logPath, "\n");
  }

  // Footer event.
  appendFileSync(
    logPath,
    JSON.stringify({ at: new Date().toISOString(), by: gitAuthorEmail, type: "run_ended", details: { outcome } }) + "\n",
  );

  const logFilename = `${toSafeIso(runStartIso)}.jsonl`;
  const relPath = logFileRelPath(featureId, taskId, logFilename);
  const gitAuthorName = process.env.GIT_AUTHOR_NAME ?? gitAuthorEmail;
  const env = buildGitCommitEnv(gitAuthorEmail, gitAuthorName, sshKeyPath);
  const GIT_PUSH_TIMEOUT = 30_000;

  // Ensure we are on the feature branch regardless of what Claude's skills
  // may have done to the management repo HEAD during execution.
  const gitOpts = { env, stdio: "pipe" as const, timeout: GIT_PUSH_TIMEOUT };
  execSync(`git -C "${workspaceRoot}" checkout "${taskBranch}"`, gitOpts);
  execSync(`git -C "${workspaceRoot}" add "${relPath}"`, gitOpts);
  execSync(`git -C "${workspaceRoot}" commit -m "chore: flush task log ${taskId}"`, gitOpts);
  execSync(`git -C "${workspaceRoot}" push origin "${taskBranch}"`, gitOpts);
}

// ── Main export ───────────────────────────────────────────────────────────────

/**
 * Invoke `claude -p <agentContext> --max-turns <n>` as a subprocess, then
 * read the task YAML to determine the outcome.
 */
export async function runClaude(opts: RunClaudeOpts): Promise<RunClaudeResult> {
  const {
    taskId,
    featureId,
    workspaceRoot,
    taskRepoRoot,
    workflowLocalPath,
    agentContext,
    maxTurns,
    maxTokens,
    sshKeyPath,
    gitAuthorEmail,
    taskBranch,
    logSinkEnabled,
  } = opts;

  const runStartIso = new Date().toISOString();

  // Build subprocess environment — inject SSH command and agent-runtime marker.
  const env = { ...buildGitEnv(sshKeyPath), CLAUDE_AGENT_RUNTIME: "1" };

  // ── Option B: Pre-flight toolchain check ─────────────────────────────────
  // Verify required tools exist before spending any tokens. If a tool is
  // missing the container image must be fixed — block immediately.
  const missingTools = checkRequiredTools(taskRepoRoot);
  if (missingTools.length > 0) {
    const details = `missing tools in container: ${missingTools.join(", ")}`;
    emit({ type: "preflight_failed", task_id: taskId, feature_id: featureId, reason: "missing_tool", details });
    return { outcome: "blocked", reason: "missing_tool", details };
  }

  // ── Workspace rules + global skills ──────────────────────────────────────
  // Copy workspace CLAUDE.md → ~/.claude/CLAUDE.md so workspace rules apply
  // regardless of which repo Claude runs against.
  // Copy all skills → ~/.claude/skills/ so Claude discovers them natively
  // without polluting the task repo's working tree.
  copyWorkspaceClaude(workspaceRoot);
  setupGlobalSkills(workspaceRoot, workflowLocalPath);

  // ── Option A: Append hard-stop instruction ───────────────────────────────
  // Fallback for tools the pre-flight doesn't know about.
  const effectiveAgentContext = agentContext + MISSING_TOOL_INSTRUCTION;

  // ── MCP server registration ───────────────────────────────────────────────
  // Build a single --mcp-config file combining all available MCP servers:
  //   - rag-server (SSE): enabled when MCP_RAG_URL is set
  //   - figma (stdio):    enabled when FIGMA_PERSONAL_ACCESS_TOKEN is set
  // Agents degrade gracefully when either is absent.
  const mcpArgs: string[] = [];
  const mcpRagUrl = process.env.MCP_RAG_URL;
  const figmaToken = process.env.FIGMA_PERSONAL_ACCESS_TOKEN;

  if (mcpRagUrl || figmaToken) {
    const mcpConfig: { mcpServers: Record<string, unknown> } = { mcpServers: {} };

    if (mcpRagUrl) {
      mcpConfig.mcpServers["rag-server"] = { type: "sse", url: `${mcpRagUrl}/sse` };
      emit({ type: "mcp_rag_registered", task_id: taskId, feature_id: featureId, url: mcpRagUrl });
    }

    if (figmaToken) {
      mcpConfig.mcpServers["figma"] = {
        type: "stdio",
        command: "npx",
        args: ["-y", "@figma/mcp-server"],
        env: { FIGMA_PERSONAL_ACCESS_TOKEN: figmaToken },
      };
      emit({ type: "mcp_figma_registered", task_id: taskId, feature_id: featureId });
    }

    const mcpConfigPath = `/tmp/mcp-config-${taskId}.json`;
    writeFileSync(mcpConfigPath, JSON.stringify(mcpConfig));
    mcpArgs.push("--mcp-config", mcpConfigPath);
  }

  // ── RAG pre-flight audit record ──────────────────────────────────────────
  // Append the runtime-authoritative `rag_pre_flight` entry to the task YAML
  // before spawning Claude. We hold onto the entry so we can verify on exit
  // that the agent didn't tamper with it.
  let ragPreFlightEntry: TaskLogEntry | null = null;
  if (opts.ragPreFlight) {
    try {
      ragPreFlightEntry = writeRagPreFlightAndPush(
        workspaceRoot,
        featureId,
        taskId,
        taskBranch,
        gitAuthorEmail,
        sshKeyPath,
        opts.ragPreFlight,
      );
      emit({
        type: "rag_pre_flight_recorded",
        task_id: taskId,
        feature_id: featureId,
        injected: opts.ragPreFlight.injected,
        summary: opts.ragPreFlight.summary,
      });
    } catch (e) {
      // If we can't write the audit record, fail closed — better to block than
      // run unaudited.
      const details = `failed to write rag_pre_flight entry: ${String(e)}`;
      emit({ type: "rag_pre_flight_failed", task_id: taskId, feature_id: featureId, details });
      return { outcome: "blocked", reason: "runtime_error", details };
    }
  }

  emit({ type: "claude_spawn", task_id: taskId, feature_id: featureId, max_turns: maxTurns });

  // Use async spawn so stdout streams to the container log in real-time
  // while also being captured for the JSONL log sink.
  const spawnResult = await new Promise<{
    stdout: string;
    status: number | null;
    signal: string | null;
    error?: Error;
  }>((resolve) => {
    const stdoutChunks: string[] = [];

    const child = spawn(
      "claude",
      [
        "-p", effectiveAgentContext,
        "--max-turns", String(maxTurns),
        "--output-format", "stream-json",
        "--verbose",
        "--dangerously-skip-permissions",
        ...mcpArgs,
      ],
      { cwd: taskRepoRoot, env },
    );

    child.stdout.setEncoding("utf-8");
    child.stderr.setEncoding("utf-8");

    // Tee stdout: capture for log sink + stream to container stdout.
    // Also watch for the stream-json `result` event: once Claude has emitted
    // its final result, start a 30-second watchdog. If the Claude process has
    // not exited by then (e.g. because a background bash subprocess inherited
    // the stdio fd and is keeping the pipe open), kill it so we don't hang
    // indefinitely waiting for `close`.
    let resultWatchdog: ReturnType<typeof setTimeout> | null = null;
    child.stdout.on("data", (chunk: string) => {
      stdoutChunks.push(chunk);
      process.stdout.write(chunk);
      if (resultWatchdog === null && chunk.includes('"type":"result"')) {
        resultWatchdog = setTimeout(() => {
          if (!child.killed) child.kill("SIGTERM");
        }, 30_000);
      }
    });

    // Surface claude's stderr directly to the container log.
    child.stderr.on("data", (chunk: string) => {
      process.stderr.write(chunk);
    });

    child.on("error", (error: Error) => {
      if (resultWatchdog !== null) clearTimeout(resultWatchdog);
      resolve({ stdout: stdoutChunks.join(""), status: null, signal: null, error });
    });

    // Use 'exit' + setTimeout(0) rather than relying solely on 'close': if
    // Claude spawned background processes via Bash tool use, those grandchildren
    // inherit the stdout pipe fd and keep it open after Claude exits — 'close'
    // would never fire. setTimeout(0) lets buffered 'data' events drain in the
    // current poll phase before we destroy the streams, which causes 'close'
    // to fire immediately after.
    child.on("exit", () => {
      if (resultWatchdog !== null) clearTimeout(resultWatchdog);
      setTimeout(() => {
        if (!child.stdout.destroyed) child.stdout.destroy();
        if (!child.stderr.destroyed) child.stderr.destroy();
      }, 0);
    });

    child.on("close", (code: number | null, signal: string | null) => {
      resolve({ stdout: stdoutChunks.join(""), status: code, signal });
    });
  });

  emit({
    type: "claude_exit",
    task_id: taskId,
    feature_id: featureId,
    exit_code: spawnResult.status,
    signal: spawnResult.signal ?? null,
  });

  // ── Token audit (D3) ──────────────────────────────────────────────────────
  const totalTokens =
    spawnResult.stdout ? extractTotalTokens(spawnResult.stdout) : undefined;

  if (totalTokens === undefined) {
    emit({
      type: "budget_audit_skipped",
      task_id: taskId,
      feature_id: featureId,
      reason: "usage format not found in stdout",
    });
  } else {
    emit({ type: "budget_audit", task_id: taskId, feature_id: featureId, total_tokens: totalTokens, max_tokens: maxTokens });
  }

  // ── Outcome determination ─────────────────────────────────────────────────
  let result: RunClaudeResult;

  let task: Task;
  try {
    task = parseYaml(
      readFileSync(taskYamlAbsPath(workspaceRoot, featureId, taskId), "utf-8"),
    ) as Task;
  } catch (e) {
    result = {
      outcome: "blocked",
      reason: "runtime_error",
      details: `Failed to read task YAML after claude exit: ${String(e)}`,
    };
    // Log flush is best-effort when the task YAML itself is unreadable.
    if (logSinkEnabled) {
      try {
        flushLogAndPush(workspaceRoot, featureId, taskId, taskBranch, runStartIso, gitAuthorEmail, spawnResult.stdout ?? "", result.outcome, sshKeyPath);
      } catch (logErr) {
        emit({ type: "log_flush_failed", task_id: taskId, feature_id: featureId, details: String(logErr) });
      }
    }
    return result;
  }

  // Re-serialise through yamlStringify so any bare scalars Claude wrote that
  // contain ": " (e.g. "Test suite: 5 passed") get properly quoted.
  // Commit + push only when the content actually changed.
  try {
    const taskYamlPath = taskYamlAbsPath(workspaceRoot, featureId, taskId);
    const original = readFileSync(taskYamlPath, "utf-8");
    const normalised = yamlStringify(task);
    if (normalised !== original) {
      writeFileSync(taskYamlPath, normalised, "utf-8");
      const relPath = taskYamlRelPath(featureId, taskId);
      const gitOpts = { cwd: workspaceRoot, encoding: "utf-8" as const, env: buildGitEnv(sshKeyPath), timeout: 30_000 };
      execSync(`git add "${relPath}"`, gitOpts);
      execSync(`git commit -m "chore(${taskId}): normalise task YAML"`, gitOpts);
      execSync(`git push origin "${taskBranch}"`, gitOpts);
      emit({ type: "task_yaml_normalised", task_id: taskId, feature_id: featureId });
    }
  } catch (normErr) {
    emit({ type: "task_yaml_normalise_failed", task_id: taskId, feature_id: featureId, details: String(normErr) });
  }

  // ── RAG pre-flight audit ──────────────────────────────────────────────────
  // If the runtime wrote a `rag_pre_flight` entry before spawning, confirm it
  // survived intact. Mutation/removal forces a runtime_error block — the run
  // is unauditable, treat it as failed regardless of the agent's claimed
  // outcome.
  if (ragPreFlightEntry) {
    const audit = auditRagPreFlight(task, ragPreFlightEntry);
    if (!audit.ok) {
      const details = `rag_audit_failed: ${audit.reason}`;
      emit({
        type: "rag_audit_failed",
        task_id: taskId,
        feature_id: featureId,
        reason: audit.reason,
      });
      try {
        writeBlockedAndPush(workspaceRoot, featureId, taskId, task, "runtime_error", details, taskBranch, gitAuthorEmail, sshKeyPath);
      } catch (pushErr) {
        emit({ type: "blocked_push_failed", task_id: taskId, feature_id: featureId, details: String(pushErr) });
      }
      result = { outcome: "blocked", reason: "runtime_error", details };

      // Flush logs (best-effort) and return early — skip the normal outcome
      // determination below since we've already overridden it.
      if (logSinkEnabled) {
        try {
          flushLogAndPush(workspaceRoot, featureId, taskId, taskBranch, runStartIso, gitAuthorEmail, spawnResult.stdout ?? "", result.outcome, sshKeyPath);
        } catch (logErr) {
          emit({ type: "log_flush_failed", task_id: taskId, feature_id: featureId, details: String(logErr) });
        }
      }
      return result;
    }
  }

  if (task.status === "in_review") {
    result = { outcome: "in_review" };
  } else if (task.status === "blocked") {
    const reason = task.blocked_reason ?? "unknown";
    // Token overage takes precedence over the agent's own blocked_reason.
    if (totalTokens !== undefined && totalTokens > maxTokens) {
      result = {
        outcome: "blocked",
        reason: "budget_exceeded",
        details: {
          total_tokens: totalTokens,
          max_tokens: maxTokens,
          original_reason: reason,
        },
      };
    } else {
      result = { outcome: "blocked", reason, details: task.blocked_details };
    }
  } else {
    // Task is still in_progress — claude exited without completing the task.
    const note =
      spawnResult.error
        ? `process error: ${spawnResult.error.message}`
        : `task still in_progress after claude exit (code ${spawnResult.status ?? "null"})`;

    emit({ type: "task_blocked", task_id: taskId, feature_id: featureId, reason: "runtime_error", note });

    try {
      writeBlockedAndPush(workspaceRoot, featureId, taskId, task, "runtime_error", note, taskBranch, gitAuthorEmail, sshKeyPath);
    } catch (pushErr) {
      emit({ type: "blocked_push_failed", task_id: taskId, feature_id: featureId, details: String(pushErr) });
    }

    result = { outcome: "blocked", reason: "runtime_error", details: note };
  }

  // ── Flush log to management repo ──────────────────────────────────────────
  if (logSinkEnabled) {
    try {
      flushLogAndPush(
        workspaceRoot,
        featureId,
        taskId,
        taskBranch,
        runStartIso,
        gitAuthorEmail,
        spawnResult.stdout ?? "",
        result.outcome,
        sshKeyPath,
      );
    } catch (logErr) {
      emit({ type: "log_flush_failed", task_id: taskId, feature_id: featureId, details: String(logErr) });
    }
  }

  return result;
}

