/**
 * T3: GitHub API PR creation and dedup for the management (workspace) repo.
 *
 * Opens a PR from the task branch to baseBranch on the management repo at
 * claim time. If an open PR already exists on the branch, reuses it
 * (idempotent — safe to call on re-claim or after a blocked recovery).
 *
 * HTTP calls use curl via spawnSync (no gh CLI, matching pr-create convention).
 * Authentication: Authorization: token <githubToken>.
 * JSON bodies are passed as array args to spawnSync — no shell interpolation.
 */

import { execSync, spawnSync } from "node:child_process";
import { readFileSync, writeFileSync } from "node:fs";
import { parse as parseYaml, stringify as yamlStringify } from "yaml";
import type { Task } from "../types/task.js";
import { taskYamlAbsPath, taskYamlRelPath } from "../paths.js";
import { buildGitCommitEnv } from "../git-env.js";

// ── Public types ──────────────────────────────────────────────────────────────

export interface OpenWorkspacePrOpts {
  /** Absolute path to the management (workspace) repo root. */
  workspaceRoot: string;
  /** Feature directory ID (e.g. "task-branch-lifecycle"). */
  featureId: string;
  /** Task ID (e.g. "T3"). */
  taskId: string;
  /** Task branch name, e.g. "feature/task-branch-lifecycle-T3". */
  branch: string;
  /** PR target branch, e.g. "main". */
  baseBranch: string;
  /** GitHub personal access token. */
  githubToken: string;
  /** GitHub repo owner, parsed from workspace.yaml management repo SSH URL. */
  repoOwner: string;
  /** GitHub repo name, parsed from workspace.yaml management repo SSH URL. */
  repoName: string;
  /** GIT_AUTHOR_EMAIL for the workspace_pr commit. Defaults to "agent@unknown". */
  gitAuthorEmail?: string;
  /** GIT_AUTHOR_NAME for the workspace_pr commit. Defaults to gitAuthorEmail. */
  gitAuthorName?: string;
  /** SSH private key path for git push. Omit to rely on ambient SSH config. */
  sshKeyPath?: string;
  /**
   * Skip git add/commit/push for the YAML update.
   * The YAML is still written to disk.
   * Intended for unit tests that do not set up a real git repo.
   */
  skipGit?: boolean;
}

export interface OpenWorkspacePrResult {
  prUrl: string;
  prNumber: number;
  /** True if an existing open PR was reused; false if a new PR was created. */
  alreadyExisted: boolean;
}

// ── parseGitHubCoords ─────────────────────────────────────────────────────────

/**
 * Extract GitHub owner and repo name from an SSH remote URL.
 *
 * Accepts:
 *   git@github.com:owner/repo.git
 *   git@github.com:owner/repo
 *
 * Throws a descriptive error for non-matching URLs (e.g. HTTPS or malformed).
 */
export function parseGitHubCoords(sshUrl: string): { owner: string; repo: string } {
  const match = /git@github\.com:([^/]+)\/([^.]+)(?:\.git)?$/.exec(sshUrl);
  if (!match) {
    throw new Error(
      `Cannot parse GitHub owner/repo from URL: "${sshUrl}". ` +
        `Expected SSH format: git@github.com:<owner>/<repo>[.git]`,
    );
  }
  return { owner: match[1], repo: match[2] };
}

// ── Internal helpers ──────────────────────────────────────────────────────────

interface PrListItem {
  html_url: string;
  number: number;
}

/**
 * Call the GitHub REST API via curl. Arguments are passed as an array to
 * spawnSync to avoid shell injection.
 *
 * Throws if curl fails or the response is not valid JSON.
 */
function curlJson(args: string[]): unknown {
  const result = spawnSync("curl", args, {
    encoding: "utf-8",
    stdio: ["ignore", "pipe", "pipe"],
  });
  if (result.error) throw result.error;
  const stdout = result.stdout ?? "";
  if (!stdout.trim()) {
    throw new Error(
      `curl returned empty response. stderr: ${result.stderr ?? ""}`,
    );
  }
  try {
    return JSON.parse(stdout);
  } catch {
    throw new Error(`curl response is not valid JSON: ${stdout}`);
  }
}


// ── Public API ────────────────────────────────────────────────────────────────

/**
 * Open a PR on the management repo from the task branch to baseBranch.
 *
 * Idempotent: if an open PR already exists on the branch it is reused rather
 * than creating a duplicate.
 *
 * On success, writes `task.workspace_pr = { url, status: "open" }` to the
 * task YAML and commits+pushes the change to the task branch (unless
 * `skipGit` is true).
 */
export async function openWorkspacePr(
  opts: OpenWorkspacePrOpts,
): Promise<OpenWorkspacePrResult> {
  const {
    workspaceRoot,
    featureId,
    taskId,
    branch,
    baseBranch,
    githubToken,
    repoOwner,
    repoName,
    gitAuthorEmail = "agent@unknown",
    gitAuthorName = gitAuthorEmail,
    sshKeyPath,
    skipGit = false,
  } = opts;

  // Read task YAML upfront: title needed for PR subject; object reused for write.
  const taskPath = taskYamlAbsPath(workspaceRoot, featureId, taskId);
  const task = parseYaml(readFileSync(taskPath, "utf-8")) as Task;

  // ── 1. Check for existing open PR ─────────────────────────────────────────
  const encodedHead = encodeURIComponent(`${repoOwner}:${branch}`);
  const listUrl =
    `https://api.github.com/repos/${repoOwner}/${repoName}/pulls` +
    `?head=${encodedHead}&state=open`;

  const pullsList = curlJson([
    "-s",
    "-H",
    `Authorization: token ${githubToken}`,
    "-H",
    "Accept: application/vnd.github+json",
    listUrl,
  ]) as PrListItem[];

  let prUrl: string;
  let prNumber: number;
  let alreadyExisted: boolean;

  if (Array.isArray(pullsList) && pullsList.length > 0) {
    // ── 2a. Reuse existing open PR ─────────────────────────────────────────
    prUrl = pullsList[0].html_url;
    prNumber = pullsList[0].number;
    alreadyExisted = true;
  } else {
    // ── 2b. Create new PR ──────────────────────────────────────────────────
    const prTitle = `feat(${taskId}): ${task.title}`;
    const prBody =
      `Task: ${taskId}\nFeature: ${featureId}\nBranch: \`${branch}\``;
    const createUrl =
      `https://api.github.com/repos/${repoOwner}/${repoName}/pulls`;
    const requestBody = JSON.stringify({
      title: prTitle,
      body: prBody,
      head: branch,
      base: baseBranch,
    });

    const created = curlJson([
      "-s",
      "-X",
      "POST",
      "-H",
      `Authorization: token ${githubToken}`,
      "-H",
      "Accept: application/vnd.github+json",
      "-H",
      "Content-Type: application/json",
      "-d",
      requestBody,
      createUrl,
    ]) as { html_url?: string; number?: number };

    if (!created.html_url || !created.number) {
      throw new Error(
        `GitHub API PR creation failed. Response: ${JSON.stringify(created)}`,
      );
    }

    prUrl = created.html_url;
    prNumber = created.number;
    alreadyExisted = false;
  }

  // ── 3. Write workspace_pr to task YAML ────────────────────────────────────
  task.workspace_pr = { url: prUrl, status: "open" };
  writeFileSync(taskPath, yamlStringify(task), "utf-8");

  // ── 4. Commit and push YAML update to task branch ─────────────────────────
  if (!skipGit) {
    const env = buildGitCommitEnv(gitAuthorEmail, gitAuthorName, sshKeyPath);
    const relPath = taskYamlRelPath(featureId, taskId);

    execSync(`git -C "${workspaceRoot}" add "${relPath}"`, {
      env,
      stdio: "pipe",
    });
    execSync(
      `git -C "${workspaceRoot}" commit -m "chore(${taskId}): open workspace PR"`,
      { env, stdio: "pipe" },
    );
    execSync(`git -C "${workspaceRoot}" push origin "${branch}"`, {
      env,
      stdio: "pipe",
    });
  }

  return { prUrl, prNumber, alreadyExisted };
}

/**
 * Merge-completion handler.
 *
 * When the in_review poll reports `merged: true` for a task's implementation
 * PR, this handler:
 *
 *   1. Reads the live task state from the feature branch (idempotency guard).
 *   2. Checks out and syncs the feature branch on the management repo.
 *   3. Updates the task YAML: status → done, pr.status → merged, done log entry.
 *   4. Applies the auto-ready rule: scans sibling task YAMLs in the same
 *      feature and transitions todo → ready for any whose depends_on list is
 *      now fully satisfied.
 *   5. Commits all YAML changes (completing task + newly-ready tasks) in one
 *      commit and pushes to the feature branch.  On push rejection, attempts
 *      a fetch+rebase recovery; if the rebase has conflicts, spawns Claude to
 *      resolve the YAML markers.  On persistent failure, emits
 *      pr_merge_done_blocked and skips the workspace PR merge.
 *   6. Merges the management-repo PR (workspace_pr) via the GitHub REST API.
 *      Errors here are non-fatal — the task YAML done state is preserved.
 */

import { execSync, spawnSync, spawn } from "node:child_process";
import { readFileSync, writeFileSync, readdirSync } from "node:fs";
import { join } from "node:path";
import { parse as parseYaml, stringify as yamlStringify } from "yaml";
import type { Task } from "../types/task.js";
import { taskYamlAbsPath, taskYamlRelPath, featuresRoot, TASKS_DIR } from "../paths.js";
import type { PrStatusResult, WorkspacePrRecovery } from "./check-in-review-prs.js";
import { parsePrUrl } from "./check-in-review-prs.js";
import { buildGitCommitEnv } from "../git-env.js";
import { tryReadTaskFromBranch } from "../task-branch-state.js";
import { taskBranchName } from "../paths.js";

// ── Public types ──────────────────────────────────────────────────────────────

export interface HandleMergedPrsOptions {
  /** Results from checkInReviewPrs — only those with merged === true are processed. */
  prResults: PrStatusResult[];
  /** Absolute path to the management (workspace) repo root. */
  workspaceRoot: string;
  /** GitHub owner of the management repo (for workspace PR merge call). */
  mgmtRepoOwner: string;
  /** GitHub repo name of the management repo. */
  mgmtRepoName: string;
  /** Base branch of the management repo (default: "main"). Used for rebase-before-merge. */
  mgmtBaseBranch?: string;
  /** GitHub personal access token. */
  githubToken: string;
  /** GIT_AUTHOR_EMAIL for commits and log entries. */
  gitAuthorEmail: string;
  /** GIT_AUTHOR_NAME for commits. Defaults to gitAuthorEmail. */
  gitAuthorName: string;
  /** SSH private key path for git push operations. */
  sshKeyPath?: string;
  /** Structured event emitter for observability. */
  emit: (event: Record<string, unknown>) => void;
  /**
   * Optional override for spawning Claude to resolve YAML conflict markers.
   * Receives the prompt string, the workspace cwd, and the process env.
   * Returns true if resolution succeeded, false otherwise.
   */
  invokeClaudeForResolution?: (
    prompt: string,
    cwd: string,
    env: NodeJS.ProcessEnv,
  ) => Promise<boolean>;
  /**
   * Optional override for checking whether the workspace PR is mergeable.
   * Returns true (mergeable), false (conflicting — skip merge), or null (unknown — proceed).
   * Defaults to querying the GitHub REST API.
   */
  checkMergeability?: (
    owner: string,
    repo: string,
    pullNumber: number,
    githubToken: string,
  ) => boolean | null;
}

// ── Internal helpers ──────────────────────────────────────────────────────────

/**
 * Query the GitHub REST API for the current mergeability of a PR.
 * Returns true (MERGEABLE), false (CONFLICTING), or null (UNKNOWN / error).
 */
export function fetchPrMergeability(
  mgmtRepoOwner: string,
  mgmtRepoName: string,
  prNumber: number,
  githubToken: string,
): boolean | null {
  const url = `https://api.github.com/repos/${mgmtRepoOwner}/${mgmtRepoName}/pulls/${prNumber}`;
  const result = spawnSync(
    "curl",
    [
      "-s", "-X", "GET",
      "-H", `Authorization: token ${githubToken}`,
      "-H", "Accept: application/vnd.github+json",
