/**
 * Shared git environment helpers.
 *
 * Two variants:
 *   buildGitEnv        — SSH only; for clone/fetch where no commit identity is needed.
 *   buildGitCommitEnv  — SSH + author/committer identity; for add/commit/push.
 */

export function buildGitEnv(sshKeyPath: string | undefined): NodeJS.ProcessEnv {
  return {
    ...process.env,
    ...(sshKeyPath
      ? { GIT_SSH_COMMAND: `ssh -i ${sshKeyPath} -o StrictHostKeyChecking=no` }
      : {}),
  } as NodeJS.ProcessEnv;
}

export function buildGitCommitEnv(
  gitAuthorEmail: string,
  gitAuthorName: string,
  sshKeyPath: string | undefined,
): NodeJS.ProcessEnv {
  return {
    ...process.env,
    GIT_AUTHOR_NAME: gitAuthorName,
    GIT_AUTHOR_EMAIL: gitAuthorEmail,
    GIT_COMMITTER_NAME: gitAuthorName,
    GIT_COMMITTER_EMAIL: gitAuthorEmail,
    ...(sshKeyPath
      ? { GIT_SSH_COMMAND: `ssh -i ${sshKeyPath} -o StrictHostKeyChecking=no` }
      : {}),
  } as NodeJS.ProcessEnv;
}

