/**
 * Orchestrator main entry point.
 *
 * Lifecycle:
 *   bootstrap (once) → polling loop:
 *     pull workspaces → eligibility → claim → briefing → adapter.run →
 *     side-effects → sleep → repeat
 *
 * idle_sleep_seconds controls loop behaviour (read from agent.yaml):
 *   0   → single-shot mode: one cycle then exit
 *   >0  → continuous: loops indefinitely, sleeping idle_sleep_seconds between cycles
 *
 * Exit codes:
 *   0  normal exit
 *   2  agent.yaml invalid
 *   3  git clone/pull failed (bootstrap only)
 *   4  unexpected fatal error
 */

import { existsSync, readFileSync, writeFileSync, mkdirSync } from "node:fs";
import { join } from "node:path";
import { tmpdir } from "node:os";
import { parse as parseYaml } from "yaml";
import { runBootstrap } from "./bootstrap/bootstrap.js";
import { resolveSSHKey } from "./resolve-ssh-key.js";
import { workspaceYamlPath, taskYamlAbsPath, taskBranchName } from "./paths.js";
import { findEligibleTasks } from "./eligibility/match.js";
import { claimTask } from "./claim/claim-task.js";
import { openWorkspacePr, parseGitHubCoords } from "./claim/open-workspace-pr.js";
import type { Task } from "./types/task.js";
import { generateBriefing } from "./briefing/agent-context.js";
import { fetchRagContext } from "./bootstrap/fetch-rag-context.js";
import { resolveModel } from "./config/resolve-model-policy.js";
import { parseModelOverrides } from "./config/parse-model-overrides.js";
import type { ModelPolicy } from "./config/resolve-model-policy.js";
import { pullWorkspaces } from "./poll/pull-workspaces.js";
import { runAgentLoop, type CycleOutcome } from "./poll/agent-loop.js";
import { checkInReviewPrs } from "./poll/check-in-review-prs.js";
import { handleMergeConflicts } from "./pr-response/auto-rebase.js";
import { handleDraftReviews } from "./pr-response/dispatch-draft-review.js";
import { handleMergedPrs, handleWorkspacePrRecoveries } from "./poll/handle-merged-prs.js";
import { SubProcessAdapter } from "./adapter/spawn.js";
import type { ExecutorInput } from "./adapter/adapter.js";
import { mutateTaskYaml } from "./side-effects/mutate-task-yaml.js";
import { appendLogEntry } from "./side-effects/append-log.js";
import { openImplPr } from "./side-effects/open-pr.js";
import { buildGitEnv } from "./git-env.js";
import { execSync } from "node:child_process";

// ── Helpers ───────────────────────────────────────────────────────────────────

function requireEnv(name: string): string {
  const val = process.env[name];
  if (!val) throw new Error(`Required environment variable ${name} is not set`);
  return val;
}

function extractRepoName(url: string): string {
  const match = /\/([^/]+?)(?:\.git)?$/.exec(url);
  return match?.[1] ?? url;
}

function emit(event: Record<string, unknown>): void {
  console.log(JSON.stringify({ at: new Date().toISOString(), ...event }));
}

function resolveRepoLocalPath(workspaceRoot: string, repoId: string): string {
  type RepoEntry = { id: string; github: string; local_path?: string };
  const yaml = parseYaml(
    readFileSync(workspaceYamlPath(workspaceRoot), "utf-8"),
  ) as { repos: RepoEntry[] };

  const repo = yaml.repos.find((r) => r.id === repoId);
  if (!repo) throw new Error(`Repo "${repoId}" not found in workspace.yaml`);

  if (!repo.local_path?.startsWith("env:")) {
    throw new Error(
      `Repo "${repoId}" has no "local_path: env:<VAR>" declaration in workspace.yaml.`,
    );
  }

  const envVar = repo.local_path.slice(4);
  const val = process.env[envVar];
  if (!val) {
    throw new Error(`Env var ${envVar} is not set — bootstrap should have populated it for repo "${repoId}".`);
  }
  return val;
}

function resolveRepoBaseBranch(workspaceRoot: string, repoId: string): string {
  type RepoEntry = { id: string; base_branch?: string };
  const yaml = parseYaml(
    readFileSync(workspaceYamlPath(workspaceRoot), "utf-8"),
  ) as { repos: RepoEntry[] };

  const repo = yaml.repos.find((r) => r.id === repoId);
  if (!repo) throw new Error(`Repo "${repoId}" not found in workspace.yaml`);
  return repo.base_branch ?? "main";
}

function resolveTaskRepoId(workspaceRoot: string, featureId: string, taskId: string): string {
  const task = parseYaml(
    readFileSync(taskYamlAbsPath(workspaceRoot, featureId, taskId), "utf-8"),
  ) as { repo: string };
  if (!task.repo) throw new Error(`Task ${taskId} has no repo field`);
  return task.repo;
}

function resolveRepoGitUrl(workspaceRoot: string, repoId: string): string {
  type RepoEntry = { id: string; github: string };
  const yaml = parseYaml(
    readFileSync(workspaceYamlPath(workspaceRoot), "utf-8"),
  ) as { repos: RepoEntry[] };
  const repo = yaml.repos.find((r) => r.id === repoId);
  if (!repo) throw new Error(`Repo "${repoId}" not found in workspace.yaml`);
  return repo.github;
}

function loadWorkspaceModelPolicy(workspaceRoot: string): ModelPolicy {
  const yaml = parseYaml(
    readFileSync(workspaceYamlPath(workspaceRoot), "utf-8"),
  ) as { model_policy?: ModelPolicy };

  if (yaml.model_policy) return yaml.model_policy;

  const defaultPhase = {
    allowed: ["claude-sonnet-4-6"],
    default: "claude-sonnet-4-6",
  };
  return {
    implementation: defaultPhase,
    self_review: defaultPhase,
    pr_description: defaultPhase,
    suggested_next_step: { allowed: ["claude-haiku-4-5-20251001"], default: "claude-haiku-4-5-20251001" },
  };
}

function parseManagementRepoCoords(
  workspaceRoot: string,
): { owner: string; repo: string; baseBranch: string } {
  type RepoEntry = { id: string; github: string; local_path?: string; base_branch?: string };
  const yaml = parseYaml(
    readFileSync(workspaceYamlPath(workspaceRoot), "utf-8"),
  ) as { management_repo: string; repos: RepoEntry[] };

  const mgmtId = yaml.management_repo;
  const mgmtRepo = yaml.repos.find((r) => r.id === mgmtId);
  if (!mgmtRepo) {
    throw new Error(`Management repo "${mgmtId}" not found in workspace.yaml repos`);
  }
  const { owner, repo } = parseGitHubCoords(mgmtRepo.github);
  return { owner, repo, baseBranch: mgmtRepo.base_branch ?? "main" };
}

/**
 * Write a rag_pre_flight log entry to the task YAML before spawning the executor.
 * The entry is the runtime's authoritative record of RAG context injection.
 */
function writeRagPreFlight(
  workspaceRoot: string,
  featureId: string,
  taskId: string,
  taskBranch: string,
  gitAuthorEmail: string,
  sshKeyPath: string | undefined,
  ragPreFlight: { query: string; injected: boolean; summary: string },
): void {
  const now = new Date().toISOString();
  const entry = {
    action: "rag_pre_flight" as const,
    by: gitAuthorEmail,
    at: now,
    rag_context_injected: ragPreFlight.injected,
    rag_summary: ragPreFlight.summary,
    rag_query: ragPreFlight.query,
    note: "Runtime pre-flight RAG fetch — written before executor spawn.",
  };

  const yamlPath = taskYamlAbsPath(workspaceRoot, featureId, taskId);
  const task = parseYaml(readFileSync(yamlPath, "utf-8")) as Task;
  task.log.push(entry);
  writeFileSync(yamlPath, JSON.stringify(task), "utf-8");

  // Use yaml stringify for correct formatting.
  const { stringify: yamlStringify } = await import("yaml").catch(() => ({ stringify: JSON.stringify }));
  writeFileSync(yamlPath, typeof yamlStringify === "function" ? yamlStringify(task) : JSON.stringify(task, null, 2), "utf-8");

  const relPath = `docs/features/${featureId}/tasks/${taskId}.yaml`;
  const gitOpts = {
    cwd: workspaceRoot,
    encoding: "utf-8" as const,
    env: buildGitEnv(sshKeyPath),
    timeout: 30_000,
    stdio: "pipe" as const,
  };
  execSync(`git add "${relPath}"`, gitOpts);
  execSync(
    `git commit -m "chore(${taskId}): rag pre-flight — ${ragPreFlight.injected ? "injected" : "skipped"}"`,
    gitOpts,
  );
  execSync(`git push origin "${taskBranch}"`, gitOpts);
}

// ── Main ──────────────────────────────────────────────────────────────────────

async function main(): Promise<number> {
  let agentYamlPath: string;
  let workflowLocalPath: string;
  let workspacesRoot: string;
  let gitAuthorEmail: string;

  try {
    agentYamlPath = requireEnv("AGENT_YAML_PATH");
    workflowLocalPath = requireEnv("WORKFLOW_LOCAL_PATH");
    workspacesRoot = requireEnv("WORKSPACES_ROOT");
    gitAuthorEmail = requireEnv("GIT_AUTHOR_EMAIL");
  } catch (e) {
    emit({ type: "fatal_missing_env", details: (e as Error).message });
    return 4;
  }

  const gitAuthorName = process.env.GIT_AUTHOR_NAME ?? gitAuthorEmail;

  const sshResolution = resolveSSHKey(process.env);
  const sshKeyPath = sshResolution.sshKeyPath;
  if (sshResolution.warned) {
    emit({ type: "warn_no_ssh_key", note: "Neither SSH_PRIVATE_KEY nor SSH_KEY_PATH is set." });
  }

  const bootstrapResult = await runBootstrap({
    agentYamlPath,
    workflowLocalPath,
    workflowUrl: process.env.WORKFLOW_URL,
    workspacesRoot,
    sshKeyPath,
  });

  if (bootstrapResult.exitCode !== 0) return bootstrapResult.exitCode;

  const config = bootstrapResult.config!;
  const githubToken = process.env.GITHUB_TOKEN ?? "";
  if (!githubToken) {
    emit({ type: "warn_no_github_token" });
  }

  // ── Build the per-cycle executor adapter ──────────────────────────────────
  const adapter = new SubProcessAdapter({
    extraEnv: {
      WORKSPACE_ROOT: "", // filled per-task below
      GIT_AUTHOR_EMAIL: gitAuthorEmail,
      GIT_AUTHOR_NAME: gitAuthorName,
      WORKFLOW_LOCAL_PATH: workflowLocalPath,
      MAX_TURNS: String(config.budget.max_iterations),
      LOG_SINK_ENABLED: config.log_sink.enabled ? "1" : "0",
      ...(process.env.MCP_RAG_URL ? { MCP_RAG_URL: process.env.MCP_RAG_URL } : {}),
      ...(process.env.FIGMA_PERSONAL_ACCESS_TOKEN
        ? { FIGMA_PERSONAL_ACCESS_TOKEN: process.env.FIGMA_PERSONAL_ACCESS_TOKEN }
        : {}),
    },
  });

  let lastPrPollAt: number | null = null;

  async function runOneCycle(): Promise<CycleOutcome> {
    const pullResults = pullWorkspaces({
      watchUrls: config.watches,
      sshKeyPath,
      workspacesRoot,
      workflowUrl: process.env.WORKFLOW_URL,
      workflowLocalPath,
      emit,
    });

    const haltedUrls = new Set(
      pullResults
        .filter((r) => r.outcome === "halt" || r.outcome === "warn")
        .map((r) => r.url),
    );

    let outcome: CycleOutcome = "idle";
    const pulledWorkspaceRoots: string[] = [];

    outerLoop:
    for (const watchUrl of config.watches) {
      if (haltedUrls.has(watchUrl)) continue;

      const workspaceLocalPath = join(workspacesRoot, extractRepoName(watchUrl));
      pulledWorkspaceRoots.push(workspaceLocalPath);

      if (!existsSync(workspaceLocalPath)) {
        emit({ type: "workspace_not_found", workspace_url: watchUrl });
        continue;
      }

      let eligibleTasks;
      try {
        eligibleTasks = findEligibleTasks(config, workspaceLocalPath, workflowLocalPath);
      } catch (e) {
        emit({ type: "eligibility_error", workspace_url: watchUrl, details: String(e) });
        continue;
      }

      if (eligibleTasks.length === 0) {
        emit({ type: "no_eligible_tasks", workspace_url: watchUrl });
        continue;
      }

      for (const { task, featureId } of eligibleTasks) {
        const claimResult = await claimTask({
          workspaceRoot: workspaceLocalPath,
          taskId: task.id,
          featureId,
          gitAuthorEmail,
          gitAuthorName,
          sshKeyPath,
          jitterMaxSeconds: config.jitter_max_seconds,
        });

        const taskBranch = taskBranchName(featureId, task.id);

        if (!claimResult.won) {
          if (claimResult.reason !== "branch_blocked_recovery") {
            emit({ type: "claim_lost", task_id: task.id, feature_id: featureId, reason: claimResult.reason });
            continue;
          }
          emit({ type: "task_blocked_recovery_detected", task_id: task.id, feature_id: featureId });
        } else {
          emit({ type: "task_claimed", task_id: task.id, feature_id: featureId });
        }

        // ── Open management-repo PR ───────────────────────────────────────────
        if (githubToken) {
          try {
            const mgmtCoords = parseManagementRepoCoords(workspaceLocalPath);
            await openWorkspacePr({
              workspaceRoot: workspaceLocalPath,
              featureId,
              taskId: task.id,
              branch: taskBranch,
              baseBranch: mgmtCoords.baseBranch,
              githubToken,
              repoOwner: mgmtCoords.owner,
              repoName: mgmtCoords.repo,
              gitAuthorEmail,
              gitAuthorName,
              sshKeyPath,
            });
            emit({ type: "workspace_pr_opened", task_id: task.id, feature_id: featureId });
          } catch (e) {
            emit({ type: "workspace_pr_failed", task_id: task.id, feature_id: featureId, details: String(e) });
          }
        }

        // ── Load model policy + resolve task repo ────────────────────────────
        const workspaceModelPolicy = loadWorkspaceModelPolicy(workspaceLocalPath);
        const taskRepoRoot = resolveRepoLocalPath(workspaceLocalPath, task.repo);
        const taskRepoUrl = resolveRepoGitUrl(workspaceLocalPath, task.repo);
        const taskBaseBranch = resolveRepoBaseBranch(workspaceLocalPath, task.repo);

        const tasksMdPath = join(workspaceLocalPath, "docs", "features", featureId, "tasks.md");
        let taskModelOverrides = {};
        try {
          const tasksMdContent = readFileSync(tasksMdPath, "utf-8");
          taskModelOverrides = parseModelOverrides(tasksMdContent, task.id);
        } catch { /* non-fatal */ }

        const implementationModel = resolveModel(
          workspaceModelPolicy,
          taskModelOverrides,
          "implementation",
          task.id,
        );

        // ── RAG pre-flight ───────────────────────────────────────────────────
        const mcpRagUrl = process.env.MCP_RAG_URL;
        const workspaceYaml = parseYaml(
          readFileSync(workspaceYamlPath(workspaceLocalPath), "utf-8"),
        ) as { workspace_id: string };
        const ragQuery = `${task.title} ${featureId}`;
        const ragPreFlight = await fetchRagContext(
          mcpRagUrl,
          ragQuery,
          workspaceYaml.workspace_id,
        );

        try {
          writeRagPreFlight(
            workspaceLocalPath,
            featureId,
            task.id,
            taskBranch,
            gitAuthorEmail,
            sshKeyPath,
            { query: ragQuery, injected: ragPreFlight.injected, summary: ragPreFlight.summary },
          );
        } catch (e) {
          emit({ type: "rag_pre_flight_failed", task_id: task.id, feature_id: featureId, details: String(e) });
          // Fail closed — cannot run unaudited.
          continue;
        }

        // ── Generate briefing ────────────────────────────────────────────────
        const baseContext = generateBriefing({
          taskId: task.id,
          featureId,
          taskTitle: task.title,
          taskBranch,
          taskRepo: task.repo,
          taskRepoRoot,
          workspaceRoot: workspaceLocalPath,
          gitAuthorEmail,
          gitAuthorName,
          implementationModel,
          resultPath: `/tmp/executor-result-${task.id}.json`,
        });
        const briefingContent = ragPreFlight.block
          ? `${baseContext}\n\n${ragPreFlight.block}`
          : baseContext;

        const briefingDir = join(tmpdir(), `briefing-${task.id}`);
        mkdirSync(briefingDir, { recursive: true });
        const briefingPath = join(briefingDir, "briefing.md");
        writeFileSync(briefingPath, briefingContent, "utf-8");

        const resultPath = `/tmp/executor-result-${task.id}.json`;

        // ── Build ExecutorInput ──────────────────────────────────────────────
        const input: ExecutorInput = {
          taskId: task.id,
          featureId,
          workspaceId: workspaceYaml.workspace_id,
          taskRepoUrl,
          taskRepoBranch: taskBranch,
          taskRepoPath: taskRepoRoot,
          briefingPath,
          resultPath,
          budgetTokens: config.budget.max_tokens_per_task,
          sshKeyPath: sshKeyPath ?? "",
          githubToken,
        };

        // ── Run executor (per-task extra env including WORKSPACE_ROOT) ───────
        const perTaskAdapter = new SubProcessAdapter({
          extraEnv: {
            WORKSPACE_ROOT: workspaceLocalPath,
            TASK_BRANCH: taskBranch,
            GIT_AUTHOR_EMAIL: gitAuthorEmail,
            GIT_AUTHOR_NAME: gitAuthorName,
            WORKFLOW_LOCAL_PATH: workflowLocalPath,
            MAX_TURNS: String(config.budget.max_iterations),
            LOG_SINK_ENABLED: config.log_sink.enabled ? "1" : "0",
            ...(process.env.MCP_RAG_URL ? { MCP_RAG_URL: process.env.MCP_RAG_URL } : {}),
            ...(process.env.FIGMA_PERSONAL_ACCESS_TOKEN
              ? { FIGMA_PERSONAL_ACCESS_TOKEN: process.env.FIGMA_PERSONAL_ACCESS_TOKEN }
              : {}),
          },
        });

        const execResult = await perTaskAdapter.run(input);

        emit({
          type: "executor_result",
          task_id: task.id,
          feature_id: featureId,
          terminal_status: execResult.terminal_status,
        });

        // ── Apply side-effects based on result ───────────────────────────────
        if (execResult.terminal_status === "in_review") {
          // Open implementation PR.
          let prUrl: string | undefined;
          if (githubToken) {
            try {
              const prResult = await openImplPr({
                taskRepoUrl,
                taskBranch,
                baseBranch: taskBaseBranch,
                featureId,
                taskId: task.id,
                taskTitle: task.title,
                githubToken,
              });
              prUrl = prResult.prUrl;
              emit({ type: "impl_pr_opened", task_id: task.id, feature_id: featureId, pr_url: prUrl });
            } catch (e) {
              emit({ type: "impl_pr_failed", task_id: task.id, feature_id: featureId, details: String(e) });
            }
          }

          // Mutate task YAML → in_review.
          const mutateErr = mutateTaskYaml({
            workspaceRoot: workspaceLocalPath,
            featureId,
            taskId: task.id,
            taskBranch,
            result: execResult,
            prUrl,
            gitAuthorEmail,
            gitAuthorName,
            sshKeyPath,
          });
          if (mutateErr) {
            emit({ type: "mutate_task_yaml_failed", task_id: task.id, details: mutateErr });
          }

          // Append in_review log entry.
          const logErr = appendLogEntry({
            workspaceRoot: workspaceLocalPath,
            featureId,
            taskId: task.id,
            taskBranch,
            entry: {
              action: "in_review",
              by: gitAuthorEmail,
              note: prUrl
                ? `Implementation PR opened: ${prUrl}`
                : "Implementation complete; awaiting PR creation.",
            },
            gitAuthorEmail,
            gitAuthorName,
            sshKeyPath,
          });
          if (logErr) {
            emit({ type: "append_log_failed", task_id: task.id, details: logErr });
          }
        } else {
          // blocked or failed — mutate task YAML.
          const mutateErr = mutateTaskYaml({
            workspaceRoot: workspaceLocalPath,
            featureId,
            taskId: task.id,
            taskBranch,
            result: execResult,
            gitAuthorEmail,
            gitAuthorName,
            sshKeyPath,
          });
          if (mutateErr) {
            emit({ type: "mutate_task_yaml_failed", task_id: task.id, details: mutateErr });
          }

          const logErr = appendLogEntry({
            workspaceRoot: workspaceLocalPath,
            featureId,
            taskId: task.id,
            taskBranch,
            entry: {
              action: "blocked",
              by: gitAuthorEmail,
              note: execResult.blocked_reason ?? "executor returned non-in_review status",
            },
            gitAuthorEmail,
            gitAuthorName,
            sshKeyPath,
          });
          if (logErr) {
            emit({ type: "append_log_failed", task_id: task.id, details: logErr });
          }
        }

        emit({ type: "task_run_complete", task_id: task.id, feature_id: featureId, outcome: execResult.terminal_status });
        outcome = "ran_task";
        break outerLoop;
      }
    }

    // ── In-review PR poll ─────────────────────────────────────────────────────
    if (githubToken) {
      const prPollIntervalMs =
        (config.pr_poll_interval_seconds ?? config.idle_sleep_seconds ?? 60) * 1000;
      const now = Date.now();

      if (lastPrPollAt === null || now - lastPrPollAt >= prPollIntervalMs) {
        if (pulledWorkspaceRoots.length > 0) lastPrPollAt = now;
        try {
          const { prResults, workspacePrRecoveries } = await checkInReviewPrs({
            workspaceRoots: pulledWorkspaceRoots,
            githubToken,
            emit,
          });

          for (const wsRoot of pulledWorkspaceRoots) {
            const wsResults = prResults.filter((r) => r.workspaceRoot === wsRoot);
            if (wsResults.some((r) => r.mergeable === false)) {
              await handleMergeConflicts({
                prResults: wsResults,
                workspaceRoot: wsRoot,
                resolveImplRepoRoot: (repoId) => resolveRepoLocalPath(wsRoot, repoId),
                resolveImplBaseBranch: (repoId) => resolveRepoBaseBranch(wsRoot, repoId),
                resolveTaskRepoId: (fId, tId) => resolveTaskRepoId(wsRoot, fId, tId),
                gitAuthorEmail,
                gitAuthorName,
                sshKeyPath,
                emit,
              });
            }
          }

          for (const wsRoot of pulledWorkspaceRoots) {
            const wsResults = prResults.filter((r) => r.workspaceRoot === wsRoot);
            if (wsResults.some((r) => r.hasOpenComments === true)) {
              const wsModelPolicy = loadWorkspaceModelPolicy(wsRoot);
              await handleDraftReviews({
                prResults: wsResults,
                workspaceRoot: wsRoot,
                resolveImplRepoRoot: (repoId) => resolveRepoLocalPath(wsRoot, repoId),
                resolveTaskRepoId: (fId, tId) => resolveTaskRepoId(wsRoot, fId, tId),
                resolveImplementationModel: (fId, tId) => {
                  try {
                    const tMdPath = join(wsRoot, "docs", "features", fId, "tasks.md");
                    const content = readFileSync(tMdPath, "utf-8");
                    const overrides = parseModelOverrides(content, tId);
                    return resolveModel(wsModelPolicy, overrides, "implementation", tId);
                  } catch {
                    return resolveModel(wsModelPolicy, {}, "implementation", tId);
                  }
                },
                gitAuthorEmail,
                gitAuthorName,
                sshKeyPath,
                workflowLocalPath,
                maxTurns: config.budget.max_iterations,
                maxTokens: config.budget.max_tokens_per_task,
                logSinkEnabled: config.log_sink.enabled,
                emit,
              });
            }
          }

          for (const wsRoot of pulledWorkspaceRoots) {
            const wsResults = prResults.filter((r) => r.workspaceRoot === wsRoot);
            if (wsResults.some((r) => r.merged === true)) {
              const mgmtCoords = parseManagementRepoCoords(wsRoot);
              await handleMergedPrs({
                prResults: wsResults,
                workspaceRoot: wsRoot,
                mgmtRepoOwner: mgmtCoords.owner,
                mgmtRepoName: mgmtCoords.repo,
                mgmtBaseBranch: mgmtCoords.baseBranch,
                githubToken,
                gitAuthorEmail,
                gitAuthorName,
                sshKeyPath,
                emit,
              });
            }
          }

          for (const wsRoot of pulledWorkspaceRoots) {
            const wsRecoveries = workspacePrRecoveries.filter(
              (r) => r.workspaceRoot === wsRoot,
            );
            if (wsRecoveries.length > 0) {
              const mgmtCoords = parseManagementRepoCoords(wsRoot);
              await handleWorkspacePrRecoveries({
                recoveries: wsRecoveries,
                mgmtRepoOwner: mgmtCoords.owner,
                mgmtRepoName: mgmtCoords.repo,
                mgmtBaseBranch: mgmtCoords.baseBranch,
                githubToken,
                gitAuthorEmail,
                gitAuthorName,
                sshKeyPath,
                emit,
              });
            }
          }
        } catch (e) {
          emit({ type: "in_review_poll_error", details: String(e) });
        }
      }
    }

    return outcome;
  }

  await runAgentLoop({ config, runCycle: runOneCycle, emit });
  return 0;
}

main()
  .then((code) => process.exit(code))
  .catch((e) => {
    try {
      console.log(JSON.stringify({
        type: "fatal_error",
        details: (e as Error).message ?? String(e),
        at: new Date().toISOString(),
      }));
    } catch { /* last resort */ }
    process.exit(4);
  });

input.content:
/**
 * T4: Draft-state comment resolution dispatch.
 *
 * When T2 reports `hasOpenComments: true` for an `in_review` task, this handler:
 *
 *   1. Claims the review work by appending a `review_started` log entry to
 *      the task YAML on the management-repo feature branch and pushing.
 *      First-push-wins: if the push is rejected, another agent claimed first.
 *
 *   2. Generates a review briefing that instructs Claude to execute the
 *      `respond-to-review` skill.
 *
 *   3. Invokes the Claude executor via SubProcessAdapter with that briefing.
 */

import { execSync, spawnSync } from "node:child_process";
import { readFileSync, writeFileSync, mkdirSync } from "node:fs";
import { join } from "node:path";
import { tmpdir } from "node:os";
import { parse as parseYaml, stringify as yamlStringify } from "yaml";
import type { Task } from "../types/task.js";
import { taskYamlAbsPath, taskYamlRelPath } from "../paths.js";
import type { PrStatusResult } from "../poll/check-in-review-prs.js";
import { buildGitCommitEnv } from "../git-env.js";
import { SubProcessAdapter } from "../adapter/spawn.js";
import type { ExecutorInput } from "../adapter/adapter.js";

// ── Public types ──────────────────────────────────────────────────────────────

export type DraftReviewOutcome =
  | "claim_lost"
  | "dispatched";

export interface DispatchOneReviewOptions {
  workspaceRoot: string;
  featureId: string;
  taskId: string;
  taskBranch: string;
  implRepoRoot: string;
  /** SSH or HTTPS URL of the implementation repo. */
  implRepoUrl: string;
  gitAuthorEmail: string;
  gitAuthorName?: string;
  sshKeyPath?: string;
  workflowLocalPath: string;
  maxTurns: number;
  maxTokens: number;
  logSinkEnabled: boolean;
  implementationModel: string;
  workspaceId: string;
  githubToken: string;
  emit: (event: Record<string, unknown>) => void;
}

export interface HandleDraftReviewsOptions {
  prResults: PrStatusResult[];
  workspaceRoot: string;
  resolveImplRepoRoot: (repoId: string) => string;
  resolveImplRepoUrl: (repoId: string) => string;
  resolveTaskRepoId: (featureId: string, taskId: string) => string;
  resolveImplementationModel: (featureId: string, taskId: string) => string;
  gitAuthorEmail: string;
  gitAuthorName?: string;
  sshKeyPath?: string;
  workflowLocalPath: string;
  maxTurns: number;
  maxTokens: number;
  logSinkEnabled: boolean;
  workspaceId: string;
  githubToken: string;
  emit: (event: Record<string, unknown>) => void;
}

// ── Internal helpers ──────────────────────────────────────────────────────────

function readTask(workspaceRoot: string, featureId: string, taskId: string): Task {
  return parseYaml(
    readFileSync(taskYamlAbsPath(workspaceRoot, featureId, taskId), "utf-8"),
  ) as Task;
}

function writeTask(workspaceRoot: string, featureId: string, task: Task): void {
  writeFileSync(
    taskYamlAbsPath(workspaceRoot, featureId, task.id),
    yamlStringify(task),
    "utf-8",
  );
}

function generateReviewBriefing(opts: {
  taskId: string;
  featureId: string;
  taskTitle: string;
  taskBranch: string;
  taskRepo: string;
  taskRepoRoot: string;
  workspaceRoot: string;
  prUrl: string;
  gitAuthorEmail: string;
  gitAuthorName: string;
  implementationModel: string;
}): string {
  const {
    taskId, featureId, taskTitle, taskBranch, taskRepo, taskRepoRoot,
    workspaceRoot, prUrl, gitAuthorEmail, gitAuthorName, implementationModel,
  } = opts;

  return [
    "You are an automated software agent running in a headless container.",
    "There is no interactive session. Do not prompt for input.",
    "",
    "## Identity",
    "",
    `Email: ${gitAuthorEmail}`,
    `Name:  ${gitAuthorName}`,
    "",
    "## Your claimed task",
    "",
    `Workspace root: ${workspaceRoot}`,
    `Feature:        ${featureId}`,
    `Task ID:        ${taskId}`,
    `Title:          ${taskTitle}`,
    `Impl repo:      ${taskRepo}`,
    `Repo root:      ${taskRepoRoot}`,
    `Branch:         ${taskBranch}`,
    `PR URL:         ${prUrl}`,
    "",
    "## What you must do",
    "",
    "1. Run `/respond-to-review` to read and address all open PR review comments,",
    "   then convert the PR from draft back to ready-for-review.",
    "",
    "Complete all steps without stopping or asking for confirmation.",
    "",
    "## Model",
    "",
    `Use model: ${implementationModel}`,
    "",
    "## Rules",
    "",
    "- Do not ask clarifying questions.",
    "- Use `GITHUB_TOKEN` from the environment for all GitHub API calls.",
    "- If you are stuck and cannot proceed, stop gracefully without opening new PRs.",
  ].join("\n");
}

// ── Public API ────────────────────────────────────────────────────────────────

export async function dispatchOneReview(
  opts: DispatchOneReviewOptions,
): Promise<DraftReviewOutcome> {
  const {
    workspaceRoot,
    featureId,
    taskId,
    taskBranch,
    implRepoRoot,
    implRepoUrl,
    gitAuthorEmail,
    gitAuthorName = gitAuthorEmail,
    sshKeyPath,
    workflowLocalPath,
    maxTurns,
    maxTokens,
    logSinkEnabled,
    implementationModel,
    workspaceId,
    githubToken,
    emit,
  } = opts;

  const env = buildGitCommitEnv(gitAuthorEmail, gitAuthorName, sshKeyPath);
  const now = new Date().toISOString();

  // ── 1. Checkout and reset task branch in management repo ──────────────────────
  try {
    execSync(`git -C "${workspaceRoot}" fetch origin`, { env, stdio: "pipe" });
    execSync(`git -C "${workspaceRoot}" checkout "${taskBranch}"`, { env, stdio: "pipe" });
    execSync(`git -C "${workspaceRoot}" reset --hard "origin/${taskBranch}"`, { env, stdio: "pipe" });
  } catch (e) {
    emit({ type: "review_claim_lost", task_id: taskId, feature_id: featureId, details: String(e) });
    return "claim_lost";
  }

  // ── 2. Read task and guard against duplicate claims ───────────────────────────
  let task: Task;
  try {
    task = readTask(workspaceRoot, featureId, taskId);
  } catch (e) {
    emit({ type: "review_claim_lost", task_id: taskId, feature_id: featureId, details: String(e) });
    return "claim_lost";
  }

  const lastEntry = task.log[task.log.length - 1];
  if (lastEntry?.action === "review_started") {
    emit({ type: "review_claim_lost", task_id: taskId, feature_id: featureId, details: "last log entry is review_started" });
    return "claim_lost";
  }

  const REVIEW_CYCLE_ACTIONS = new Set(["review_started", "comments_addressed"]);
  const MAX_REVIEW_CYCLES = 3;
  let consecutiveReviewCycles = 0;
  for (let i = task.log.length - 1; i >= 0; i--) {
    if (!REVIEW_CYCLE_ACTIONS.has(task.log[i].action)) break;
    if (task.log[i].action === "review_started") consecutiveReviewCycles++;
  }
  if (consecutiveReviewCycles >= MAX_REVIEW_CYCLES) {
    emit({ type: "review_loop_detected", task_id: taskId, feature_id: featureId });
    return "claim_lost";
  }

  // ── 3. Write review_started log entry and push (first-push-wins) ──────────────
  task.log.push({ action: "review_started", by: gitAuthorEmail, at: now, note: "Review dispatch claimed." });
  task.execution.last_updated_by = gitAuthorEmail;
  task.execution.last_updated_at = now;
  writeTask(workspaceRoot, featureId, task);

  const relPath = taskYamlRelPath(featureId, taskId);
  try {
    execSync(`git -C "${workspaceRoot}" add "${relPath}"`, { env, stdio: "pipe" });
    execSync(`git -C "${workspaceRoot}" commit -m "chore(${taskId}): review_started — claim"`, { env, stdio: "pipe" });
  } catch (e) {
    emit({ type: "review_claim_lost", task_id: taskId, feature_id: featureId, details: String(e) });
    return "claim_lost";
  }

  const claimPush = spawnSync("git", ["-C", workspaceRoot, "push", "origin", taskBranch], {
    env, encoding: "utf-8",
  });
  if (claimPush.status !== 0) {
    emit({ type: "review_claim_lost", task_id: taskId, feature_id: featureId, details: claimPush.stderr });
    return "claim_lost";
  }

  emit({ type: "review_dispatching", task_id: taskId, feature_id: featureId, pr_url: task.pr.url });

  // ── 4. Build review briefing and run executor ─────────────────────────────────
  const reviewBriefing = generateReviewBriefing({
    taskId,
    featureId,
    taskTitle: task.title,
    taskBranch,
    taskRepo: task.repo,
    taskRepoRoot: implRepoRoot,
    workspaceRoot,
    prUrl: task.pr.url,
    gitAuthorEmail,
    gitAuthorName,
    implementationModel,
  });

  const briefingDir = join(tmpdir(), `review-briefing-${taskId}`);
  mkdirSync(briefingDir, { recursive: true });
  const briefingPath = join(briefingDir, "review-briefing.md");
  writeFileSync(briefingPath, reviewBriefing, "utf-8");

  const resultPath = join(tmpdir(), `review-result-${taskId}.json`);

  const input: ExecutorInput = {
    taskId,
    featureId,
    workspaceId,
    taskRepoUrl: implRepoUrl,
    taskRepoBranch: taskBranch,
    taskRepoPath: implRepoRoot,
    briefingPath,
    resultPath,
    budgetTokens: maxTokens,
    sshKeyPath: sshKeyPath ?? "",
    githubToken,
  };

  const reviewAdapter = new SubProcessAdapter({
    extraEnv: {
      WORKSPACE_ROOT: workspaceRoot,
      TASK_BRANCH: taskBranch,
      GIT_AUTHOR_EMAIL: gitAuthorEmail,
      GIT_AUTHOR_NAME: gitAuthorName,
      WORKFLOW_LOCAL_PATH: workflowLocalPath,
      MAX_TURNS: String(maxTurns),
      LOG_SINK_ENABLED: logSinkEnabled ? "1" : "0",
    },
  });

  const runResult = await reviewAdapter.run(input);

  emit({
    type: "review_dispatch_complete",
    task_id: taskId,
    feature_id: featureId,
    outcome: runResult.terminal_status,
  });

  return "dispatched";
}

export async function handleDraftReviews(
  opts: HandleDraftReviewsOptions,
): Promise<void> {
  const {
    prResults,
    workspaceRoot,
    resolveImplRepoRoot,
    resolveImplRepoUrl,
    resolveTaskRepoId,
    resolveImplementationModel,
    gitAuthorEmail,
    gitAuthorName,
    sshKeyPath,
    workflowLocalPath,
    maxTurns,
    maxTokens,
    logSinkEnabled,
    workspaceId,
    githubToken,
    emit,
  } = opts;

  const draftTasks = prResults.filter((r) => r.hasOpenComments === true);

  for (const result of draftTasks) {
    const { taskId, featureId } = result;

    let repoId: string;
    try {
      repoId = resolveTaskRepoId(featureId, taskId);
    } catch (e) {
      emit({ type: "review_dispatch_error", task_id: taskId, feature_id: featureId, details: String(e) });
      continue;
    }

    let implRepoRoot: string;
    let implRepoUrl: string;
    try {
      implRepoRoot = resolveImplRepoRoot(repoId);
      implRepoUrl = resolveImplRepoUrl(repoId);
    } catch (e) {
      emit({ type: "review_dispatch_error", task_id: taskId, feature_id: featureId, details: String(e) });
      continue;
    }

    let implementationModel: string;
    try {
      implementationModel = resolveImplementationModel(featureId, taskId);
    } catch (e) {
      emit({ type: "review_dispatch_error", task_id: taskId, feature_id: featureId, details: String(e) });
      continue;
    }

    const taskBranch = `feature/${featureId}-${taskId}`;

    try {
      await dispatchOneReview({
        workspaceRoot,
        featureId,
        taskId,
        taskBranch,
        implRepoRoot,
        implRepoUrl,
        gitAuthorEmail,
        gitAuthorName,
        sshKeyPath,
        workflowLocalPath,
        maxTurns,
        maxTokens,
        logSinkEnabled,
        implementationModel,
        workspaceId,
        githubToken,
        emit,
      });
    } catch (e) {
      emit({ type: "review_dispatch_error", task_id: taskId, feature_id: featureId, details: String(e) });
    }
  }
}

