1	/**
2	 * Tests for pr-response/dispatch-draft-review.ts
3	 *
4	 * Unit tests only — no real git operations or Claude spawns. `execSync` and
5	 * `spawnSync` are mocked via vi.mock. `runClaude` is mocked to avoid subprocess
6	 * spawning. Filesystem operations use real temp directories.
7	 *
8	 * Covers:
9	 *   1. dispatchOneReview — claim_lost when checkout of task branch fails
10	 *   2. dispatchOneReview — claim_lost when task log already has review_started
11	 *   3. dispatchOneReview — claim_lost when push of claim commit is rejected
12	 *   4. dispatchOneReview — dispatched on successful claim + claude run
13	 *   5. handleDraftReviews — only processes tasks with draft === true
14	 *   6. handleDraftReviews — skips all tasks when none have draft === true
15	 */
16	
17	import { describe, it, expect, vi, afterEach } from "vitest";
18	import {
19	  mkdtempSync,
20	  mkdirSync,
21	  writeFileSync,
22	  readFileSync,
23	  rmSync,
24	} from "node:fs";
25	import { tmpdir } from "node:os";
26	import { join } from "node:path";
27	import { execSync, spawnSync } from "node:child_process";
28	import { stringify as yamlStringify, parse as parseYaml } from "yaml";
29	import type { Task } from "../src/types/task.js";
30	import type { PrStatusResult } from "../src/poll/check-in-review-prs.js";
31	import {
32	  dispatchOneReview,
33	  handleDraftReviews,
34	  type DispatchOneReviewOptions,
35	  type HandleDraftReviewsOptions,
36	} from "../src/pr-response/dispatch-draft-review.js";
37	
38	// ── Mock node:child_process ───────────────────────────────────────────────────
39	
40	vi.mock("node:child_process", async (importOriginal) => {
41	  const actual =
42	    await importOriginal<typeof import("node:child_process")>();
43	  return { ...actual, execSync: vi.fn(), spawnSync: vi.fn() };
44	});
45	
46	// ── Mock runClaude ────────────────────────────────────────────────────────────
47	
48	vi.mock("../src/loop/run-claude.js", () => ({
49	  runClaude: vi.fn().mockResolvedValue({ outcome: "in_review" }),
50	}));
51	
52	// ── Fixtures ──────────────────────────────────────────────────────────────────
53	
54	const FEATURE_ID = "test-feature";
55	const TASK_ID = "T4";
56	const TASK_BRANCH = `feature/${FEATURE_ID}-${TASK_ID}`;
57	const GIT_AUTHOR_EMAIL = "agent@test.com";
58	
59	function makeTask(overrides: Partial<Task> = {}): Task {
60	  return {
61	    id: TASK_ID,
62	    title: "Draft Review Task",
63	    repo: "impl-repo",
64	    status: "in_review",
65	    depends_on: [],
66	    blocked_reason: null,
67	    blocked_context: null,
68	    branch: TASK_BRANCH,
69	    execution: {
70	      actor_type: "agent",
71	      last_updated_by: GIT_AUTHOR_EMAIL,
72	      last_updated_at: "2026-04-19T00:00:00Z",
73	    },
74	    pr: {
75	      url: "https://github.com/myorg/impl-repo/pull/42",
76	      status: "open",
77	    },
78	    workspace_pr: null,
79	    log: [],
80	    ...overrides,
81	  };
82	}
83	
84	// ── Temp directory helpers ────────────────────────────────────────────────────
85	
86	const tmpDirs: string[] = [];
87	
88	function makeWorkspaceWithTask(task: Task, featureId = FEATURE_ID): string {
89	  const dir = mkdtempSync(join(tmpdir(), "dispatch-draft-unit-"));
90	  tmpDirs.push(dir);
91	  const tasksDir = join(dir, "docs", "features", featureId, "tasks");
92	  mkdirSync(tasksDir, { recursive: true });
93	  writeFileSync(
94	    join(tasksDir, `${task.id}.yaml`),
95	    yamlStringify(task),
96	    "utf-8",
97	  );
98	  return dir;
99	}
100	
101	function readTaskFromDisk(
102	  workspaceRoot: string,
103	  featureId: string,
104	  taskId: string,
105	): Task {
106	  return parseYaml(
107	    readFileSync(
108	      join(workspaceRoot, "docs", "features", featureId, "tasks", `${taskId}.yaml`),
109	      "utf-8",
110	    ),
111	  ) as Task;
112	}
113	
114	afterEach(() => {
115	  while (tmpDirs.length) {
116	    const d = tmpDirs.pop()!;
117	    try {
118	      rmSync(d, { recursive: true, force: true });
119	    } catch {
120	      /* best-effort */
121	    }
122	  }
123	  vi.clearAllMocks();
