1	/**
2	 * T4: Draft-state comment resolution dispatch.
3	 *
4	 * When T2 reports `hasOpenComments: true` for an `in_review` task, this handler:
5	 *
6	 *   1. Claims the review work by appending a `review_started` log entry to
7	 *      the task YAML on the management-repo feature branch and pushing.
8	 *      First-push-wins: if the push is rejected, another agent claimed first.
9	 *
10	 *   2. Generates a review briefing that instructs Claude to execute the
11	 *      `respond-to-review` skill.
12	 *
13	 *   3. Invokes the Claude executor via SubProcessAdapter with that briefing.
14	 */
15	
16	import { execSync, spawnSync } from "node:child_process";
17	import { readFileSync, writeFileSync, mkdirSync } from "node:fs";
18	import { join } from "node:path";
19	import { tmpdir } from "node:os";
20	import { parse as parseYaml, stringify as yamlStringify } from "yaml";
21	import type { Task } from "../types/task.js";
22	import { taskYamlAbsPath, taskYamlRelPath } from "../paths.js";
23	import type { PrStatusResult } from "../poll/check-in-review-prs.js";
24	import { buildGitCommitEnv } from "../git-env.js";
25	import { SubProcessAdapter } from "../adapter/spawn.js";
26	import type { ExecutorInput } from "../adapter/adapter.js";
27	
28	// ── Public types ──────────────────────────────────────────────────────────────
29	
30	export type DraftReviewOutcome =
31	  | "claim_lost"
32	  | "dispatched";
33	
34	export interface DispatchOneReviewOptions {
35	  workspaceRoot: string;
36	  featureId: string;
37	  taskId: string;
38	  taskBranch: string;
39	  implRepoRoot: string;
40	  /** SSH or HTTPS URL of the implementation repo. */
41	  implRepoUrl: string;
42	  gitAuthorEmail: string;
43	  gitAuthorName?: string;
44	  sshKeyPath?: string;
45	  workflowLocalPath: string;
46	  maxTurns: number;
47	  maxTokens: number;
48	  logSinkEnabled: boolean;
49	  implementationModel: string;
50	  workspaceId: string;
51	  githubToken: string;
52	  emit: (event: Record<string, unknown>) => void;
53	}
54	
55	export interface HandleDraftReviewsOptions {
56	  prResults: PrStatusResult[];
57	  workspaceRoot: string;
58	  resolveImplRepoRoot: (repoId: string) => string;
59	  resolveImplRepoUrl: (repoId: string) => string;
60	  resolveTaskRepoId: (featureId: string, taskId: string) => string;
61	  resolveImplementationModel: (featureId: string, taskId: string) => string;
62	  gitAuthorEmail: string;
63	  gitAuthorName?: string;
64	  sshKeyPath?: string;
65	  workflowLocalPath: string;
66	  maxTurns: number;
67	  maxTokens: number;
68	  logSinkEnabled: boolean;
69	  workspaceId: string;
70	  githubToken: string;
71	  emit: (event: Record<string, unknown>) => void;
72	}
73	
74	// ── Internal helpers ──────────────────────────────────────────────────────────
75	
76	function readTask(workspaceRoot: string, featureId: string, taskId: string): Task {
77	  return parseYaml(
78	    readFileSync(taskYamlAbsPath(workspaceRoot, featureId, taskId), "utf-8"),
79	  ) as Task;
80	}
81	
82	function writeTask(workspaceRoot: string, featureId: string, task: Task): void {
83	  writeFileSync(
84	    taskYamlAbsPath(workspaceRoot, featureId, task.id),
85	    yamlStringify(task),
86	    "utf-8",
87	  );
88	}
89	
90	function generateReviewBriefing(opts: {
91	  taskId: string;
92	  featureId: string;
93	  taskTitle: string;
94	  taskBranch: string;
95	  taskRepo: string;
96	  taskRepoRoot: string;
97	  workspaceRoot: string;
98	  prUrl: string;
99	  gitAuthorEmail: string;
100	  gitAuthorName: string;
101	  implementationModel: string;
102	}): string {
103	  const {
104	    taskId, featureId, taskTitle, taskBranch, taskRepo, taskRepoRoot,
105	    workspaceRoot, prUrl, gitAuthorEmail, gitAuthorName, implementationModel,
106	  } = opts;
107	
108	  return [
109	    "You are an automated software agent running in a headless container.",
110	    "There is no interactive session. Do not prompt for input.",
111	    "",
112	    "## Identity",
113	    "",
114	    `Email: ${gitAuthorEmail}`,
115	    `Name:  ${gitAuthorName}`,
116	    "",
117	    "## Your claimed task",
118	    "",
119	    `Workspace root: ${workspaceRoot}`,
120	    `Feature:        ${featureId}`,
121	    `Task ID:        ${taskId}`,
122	    `Title:          ${taskTitle}`,
123	    `Impl repo:      ${taskRepo}`,
124	    `Repo root:      ${taskRepoRoot}`,
125	    `Branch:         ${taskBranch}`,
126	    `PR URL:         ${prUrl}`,
127	    "",
128	    "## What you must do",
129	    "",
130	    "1. Run `/respond-to-review` to read and address all open PR review comments,",
131	    "   then convert the PR from draft back to ready-for-review.",
132	    "",
133	    "Complete all steps without stopping or asking for confirmation.",
134	    "",
135	    "## Model",
136	    "",
137	    `Use model: ${implementationModel}`,
138	    "",
139	    "## Rules",
140	    "",
141	    "- Do not ask clarifying questions.",
142	    "- Use `GITHUB_TOKEN` from the environment for all GitHub API calls.",
143	    "- If you are stuck and cannot proceed, stop gracefully without opening new PRs.",
144	  ].join("\n");
145	}
146	
147	// ── Public API ────────────────────────────────────────────────────────────────
148	
149	export async function dispatchOneReview(
150	  opts: DispatchOneReviewOptions,
151	): Promise<DraftReviewOutcome> {
152	  const {
153	    workspaceRoot,
154	    featureId,
155	    taskId,
156	    taskBranch,
157	    implRepoRoot,
158	    implRepoUrl,
159	    gitAuthorEmail,
160	    gitAuthorName = gitAuthorEmail,
161	    sshKeyPath,
162	    workflowLocalPath,
163	    maxTurns,
164	    maxTokens,
165	    logSinkEnabled,
166	    implementationModel,
167	    workspaceId,
168	    githubToken,
169	    emit,
170	  } = opts;
171	
172	  const env = buildGitCommitEnv(gitAuthorEmail, gitAuthorName, sshKeyPath);
173	  const now = new Date().toISOString();
174	
175	  // ── 1. Checkout and reset task branch in management repo ──────────────────────
176	  try {
177	    execSync(`git -C "${workspaceRoot}" fetch origin`, { env, stdio: "pipe" });
178	    execSync(`git -C "${workspaceRoot}" checkout "${taskBranch}"`, { env, stdio: "pipe" });
179	    execSync(`git -C "${workspaceRoot}" reset --hard "origin/${taskBranch}"`, { env, stdio: "pipe" });
180	  } catch (e) {
181	    emit({ type: "review_claim_lost", task_id: taskId, feature_id: featureId, details: String(e) });
182	    return "claim_lost";
183	  }
184	
185	  // ── 2. Read task and guard against duplicate claims ───────────────────────────
186	  let task: Task;
187	  try {
188	    task = readTask(workspaceRoot, featureId, taskId);
189	  } catch (e) {
190	    emit({ type: "review_claim_lost", task_id: taskId, feature_id: featureId, details: String(e) });
191	    return "claim_lost";
192	  }
193	
194	  const lastEntry = task.log[task.log.length - 1];
195	  if (lastEntry?.action === "review_started") {
196	    emit({ type: "review_claim_lost", task_id: taskId, feature_id: featureId, details: "last log entry is review_started" });
197	    return "claim_lost";
198	  }
199	
200	  const REVIEW_CYCLE_ACTIONS = new Set(["review_started", "comments_addressed"]);
201	  const MAX_REVIEW_CYCLES = 3;
202	  let consecutiveReviewCycles = 0;
203	  for (let i = task.log.length - 1; i >= 0; i--) {
204	    if (!REVIEW_CYCLE_ACTIONS.has(task.log[i].action)) break;
205	    if (task.log[i].action === "review_started") consecutiveReviewCycles++;
206	  }
207	  if (consecutiveReviewCycles >= MAX_REVIEW_CYCLES) {
208	    emit({ type: "review_loop_detected", task_id: taskId, feature_id: featureId });
209	    return "claim_lost";
210	  }
211	
212	  // ── 3. Write review_started log entry and push (first-push-wins) ──────────────
213	  task.log.push({ action: "review_started", by: gitAuthorEmail, at: now, note: "Review dispatch claimed." });
214	  task.execution.last_updated_by = gitAuthorEmail;
215	  task.execution.last_updated_at = now;
216	  writeTask(workspaceRoot, featureId, task);
217	
218	  const relPath = taskYamlRelPath(featureId, taskId);
219	  try {
220	    execSync(`git -C "${workspaceRoot}" add "${relPath}"`, { env, stdio: "pipe" });
221	    execSync(`git -C "${workspaceRoot}" commit -m "chore(${taskId}): review_started — claim"`, { env, stdio: "pipe" });
222	  } catch (e) {
223	    emit({ type: "review_claim_lost", task_id: taskId, feature_id: featureId, details: String(e) });
224	    return "claim_lost";
225	  }
226	
227	  const claimPush = spawnSync("git", ["-C", workspaceRoot, "push", "origin", taskBranch], {
228	    env, encoding: "utf-8",
229	  });
230	  if (claimPush.status !== 0) {
231	    emit({ type: "review_claim_lost", task_id: taskId, feature_id: featureId, details: claimPush.stderr });
232	    return "claim_lost";
233	  }
234	
235	  emit({ type: "review_dispatching", task_id: taskId, feature_id: featureId, pr_url: task.pr.url });
236	
237	  // ── 4. Build review briefing and run executor ─────────────────────────────────
238	  const reviewBriefing = generateReviewBriefing({
239	    taskId,
240	    featureId,
241	    taskTitle: task.title,
242	    taskBranch,
243	    taskRepo: task.repo,
244	    taskRepoRoot: implRepoRoot,
245	    workspaceRoot,
246	    prUrl: task.pr.url,
247	    gitAuthorEmail,
248	    gitAuthorName,
249	    implementationModel,
250	  });
251	
252	  const briefingDir = join(tmpdir(), `review-briefing-${taskId}`);
253	  mkdirSync(briefingDir, { recursive: true });
254	  const briefingPath = join(briefingDir, "review-briefing.md");
255	  writeFileSync(briefingPath, reviewBriefing, "utf-8");
256	
257	  const resultPath = join(tmpdir(), `review-result-${taskId}.json`);
258	
259	  const input: ExecutorInput = {
260	    taskId,
261	    featureId,
262	    workspaceId,
263	    taskRepoUrl: implRepoUrl,
264	    taskRepoBranch: taskBranch,
265	    taskRepoPath: implRepoRoot,
266	    briefingPath,
267	    resultPath,
268	    budgetTokens: maxTokens,
269	    sshKeyPath: sshKeyPath ?? "",
270	    githubToken,
271	  };
272	
273	  const reviewAdapter = new SubProcessAdapter({
274	    extraEnv: {
275	      WORKSPACE_ROOT: workspaceRoot,
276	      TASK_BRANCH: taskBranch,
277	      GIT_AUTHOR_EMAIL: gitAuthorEmail,
278	      GIT_AUTHOR_NAME: gitAuthorName,
279	      WORKFLOW_LOCAL_PATH: workflowLocalPath,
280	      MAX_TURNS: String(maxTurns),
281	      LOG_SINK_ENABLED: logSinkEnabled ? "1" : "0",
282	    },
283	  });
284	
285	  const runResult = await reviewAdapter.run(input);
286	
287	  emit({
288	    type: "review_dispatch_complete",
289	    task_id: taskId,
290	    feature_id: featureId,
291	    outcome: runResult.terminal_status,
292	  });
293	
294	  return "dispatched";
295	}
296	
297	export async function handleDraftReviews(
298	  opts: HandleDraftReviewsOptions,
299	): Promise<void> {
300	  const {
301	    prResults,
302	    workspaceRoot,
303	    resolveImplRepoRoot,
304	    resolveImplRepoUrl,
305	    resolveTaskRepoId,
306	    resolveImplementationModel,
307	    gitAuthorEmail,
308	    gitAuthorName,
309	    sshKeyPath,
310	    workflowLocalPath,
311	    maxTurns,
312	    maxTokens,
313	    logSinkEnabled,
314	    workspaceId,
315	    githubToken,
316	    emit,
317	  } = opts;
318	
319	  const draftTasks = prResults.filter((r) => r.hasOpenComments === true);
320	
321	  for (const result of draftTasks) {
322	    const { taskId, featureId } = result;
323	
324	    let repoId: string;
325	    try {
326	      repoId = resolveTaskRepoId(featureId, taskId);
327	    } catch (e) {
328	      emit({ type: "review_dispatch_error", task_id: taskId, feature_id: featureId, details: String(e) });
329	      continue;
330	    }
331	
332	    let implRepoRoot: string;
333	    let implRepoUrl: string;
334	    try {
335	      implRepoRoot = resolveImplRepoRoot(repoId);
336	      implRepoUrl = resolveImplRepoUrl(repoId);
337	    } catch (e) {
338	      emit({ type: "review_dispatch_error", task_id: taskId, feature_id: featureId, details: String(e) });
339	      continue;
340	    }
341	
342	    let implementationModel: string;
343	    try {
344	      implementationModel = resolveImplementationModel(featureId, taskId);
345	    } catch (e) {
346	      emit({ type: "review_dispatch_error", task_id: taskId, feature_id: featureId, details: String(e) });
347	      continue;
348	    }
349	
350	    const taskBranch = `feature/${featureId}-${taskId}`;
351	
352	    try {
353	      await dispatchOneReview({
354	        workspaceRoot,
355	        featureId,
356	        taskId,
357	        taskBranch,
358	        implRepoRoot,
359	        implRepoUrl,
360	        gitAuthorEmail,
361	        gitAuthorName,
362	        sshKeyPath,
363	        workflowLocalPath,
364	        maxTurns,
365	        maxTokens,
366	        logSinkEnabled,
367	        implementationModel,
368	        workspaceId,
369	        githubToken,
370	        emit,
371	      });
372	    } catch (e) {
373	      emit({ type: "review_dispatch_error", task_id: taskId, feature_id: featureId, details: String(e) });
374	    }
375	  }
376	}
