/**
 * T4: Draft-state comment resolution dispatch.
 *
 * When T2 reports `draft: true` for an `in_review` task, this handler:
 *
 *   1. Claims the review work by appending a `review_started` log entry to
 *      the task YAML on the management-repo feature branch and pushing.
 *      First-push-wins: if the push is rejected, another agent claimed first.
 *
 *   2. Generates an adapted agent context string that instructs Claude to
 *      execute the `respond-to-review` skill.
 *
 *   3. Calls `runClaude` with that context to dispatch Claude.
 */

import { execSync, spawnSync } from "node:child_process";
import { readFileSync, writeFileSync } from "node:fs";
import { parse as parseYaml, stringify as yamlStringify } from "yaml";
import type { Task } from "../types/task.js";
import { taskYamlAbsPath, taskYamlRelPath } from "../paths.js";
import type { PrStatusResult } from "../poll/check-in-review-prs.js";
import { buildGitCommitEnv } from "../git-env.js";
import { runClaude } from "../loop/run-claude.js";

// ── Public types ──────────────────────────────────────────────────────────────

export type DraftReviewOutcome =
  | "claim_lost"  // Another agent already claimed this review dispatch.
  | "dispatched"; // Claude was dispatched to address the PR review comments.

export interface DispatchOneReviewOptions {
  /** Absolute path to the management (workspace) repo root. */
  workspaceRoot: string;
  /** Feature directory ID (e.g. "agent-pr-response"). */
  featureId: string;
  /** Task ID (e.g. "T4"). */
  taskId: string;
  /** Task feature branch name (e.g. "feature/agent-pr-response-T4"). */
  taskBranch: string;
  /** Absolute path to the implementation repo root. */
  implRepoRoot: string;
  /** GIT_AUTHOR_EMAIL for commits and log entries. */
  gitAuthorEmail: string;
  /** GIT_AUTHOR_NAME for commits. Defaults to gitAuthorEmail. */
  gitAuthorName?: string;
  /** SSH private key path for git push operations. */
  sshKeyPath?: string;
  /** Absolute path to the workflow repo (contains technical_skills/). */
  workflowLocalPath: string;
  /** Maximum Claude turns for this activation. */
  maxTurns: number;
  /** Maximum token budget for this activation. */
  maxTokens: number;
  /** When true, write captured stdout to the JSONL log file and commit+push. */
  logSinkEnabled: boolean;
  /** Model ID to use for the Claude activation. */
  implementationModel: string;
  /** Structured event emitter for observability. */
  emit: (event: Record<string, unknown>) => void;
}

export interface HandleDraftReviewsOptions {
  /** Results from checkInReviewPrs — only those with draft === true are processed. */
  prResults: PrStatusResult[];
  /** Absolute path to the management (workspace) repo root. */
  workspaceRoot: string;
  /** Resolve the impl repo root for a given repo ID (from workspace.yaml). */
  resolveImplRepoRoot: (repoId: string) => string;
  /** Resolve the task's repo ID from the task YAML. */
  resolveTaskRepoId: (featureId: string, taskId: string) => string;
  /** Resolve the implementation model for a given task. */
  resolveImplementationModel: (featureId: string, taskId: string) => string;
  /** GIT_AUTHOR_EMAIL for commits and log entries. */
  gitAuthorEmail: string;
  /** GIT_AUTHOR_NAME for commits. Defaults to gitAuthorEmail. */
  gitAuthorName?: string;
  /** SSH private key path for git push operations. */
  sshKeyPath?: string;
  /** Absolute path to the workflow repo (contains technical_skills/). */
  workflowLocalPath: string;
  /** Maximum Claude turns for this activation. */
  maxTurns: number;
  /** Maximum token budget for this activation. */
  maxTokens: number;
  /** When true, write captured stdout to the JSONL log file and commit+push. */
  logSinkEnabled: boolean;
  /** Structured event emitter for observability. */
  emit: (event: Record<string, unknown>) => void;
}

// ── Internal helpers ──────────────────────────────────────────────────────────

function readTask(
  workspaceRoot: string,
  featureId: string,
  taskId: string,
): Task {
  return parseYaml(
    readFileSync(taskYamlAbsPath(workspaceRoot, featureId, taskId), "utf-8"),
  ) as Task;
}

function writeTask(
  workspaceRoot: string,
  featureId: string,
  task: Task,
): void {
  writeFileSync(
    taskYamlAbsPath(workspaceRoot, featureId, task.id),
    yamlStringify(task),
    "utf-8",
  );
}

/**
 * Generate an agent context string that instructs Claude to execute the
 * `respond-to-review` skill for addressing PR review comments.
 *
 * Parallel to `generateAgentContext` in bootstrap/agent-context.ts but
 * adapted for the review-response activation: the PR URL is included and
 * the "What you must do" section invokes `/respond-to-review` instead of
 * `/start-implementation`.
 */
function generateReviewAgentContext(opts: {
  taskId: string;
  featureId: string;
  taskTitle: string;
  taskBranch: string;
  taskRepo: string;
  taskRepoRoot: string;
  workspaceRoot: string;
  prUrl: string;
  gitAuthorEmail: string;
  gitAuthorName: string;
  implementationModel: string;
}): string {
  const {
    taskId,
    featureId,
    taskTitle,
    taskBranch,
    taskRepo,
    taskRepoRoot,
    workspaceRoot,
    prUrl,
    gitAuthorEmail,
    gitAuthorName,
    implementationModel,
  } = opts;

  return [
    "You are an automated software agent running in a headless container.",
    "There is no interactive session. Do not prompt for input.",
    "Do not ask clarifying questions. Execute the task described below.",
    "",
    "## Identity",
    "",
    `Email: ${gitAuthorEmail}`,
    `Name:  ${gitAuthorName}`,
    "",
    "## Your claimed task",
    "",
    `Workspace root: ${workspaceRoot}`,
    `Feature:        ${featureId}`,
    `Task ID:        ${taskId}`,
    `Title:          ${taskTitle}`,
    `Impl repo:      ${taskRepo}`,
    `Repo root:      ${taskRepoRoot}`,
    `Branch:         ${taskBranch}`,
    `PR URL:         ${prUrl}`,
    "",
    "## What you must do",
    "",
    "1. Run `/respond-to-review` to read and address all open PR review comments,",
    "   then convert the PR from draft back to ready-for-review.",
    "",
    "Complete all steps without stopping or asking for confirmation.",
    "",
    "## Model",
    "",
    `Use model: ${implementationModel}`,
    "",
    "## Rules",
    "",
    "- Do not ask clarifying questions. Implement what is specified.",
    "- Use `GITHUB_TOKEN` from the environment for all GitHub API calls.",
    "- If you are stuck and cannot proceed, stop gracefully without opening new PRs.",
  ].join("\n");
}

// ── Public API ────────────────────────────────────────────────────────────────

/**
 * Claim the review work for one draft-state in_review task and dispatch
 * Claude to address the open PR review comments.
 *
 * Claim protocol (first-push-wins):
 *   1. Checkout and reset the management-repo task branch.
 *   2. Guard: if the task log already has a `review_started` entry, skip.
 *   3. Append `review_started` to the task log and push.
 *      If the push is rejected, another agent won — return "claim_lost".
 *   4. Generate review agent context and call runClaude.
 *
 * @returns The outcome of the operation.
 */
export async function dispatchOneReview(
  opts: DispatchOneReviewOptions,
): Promise<DraftReviewOutcome> {
  const {
    workspaceRoot,
    featureId,
    taskId,
    taskBranch,
    implRepoRoot,
    gitAuthorEmail,
    gitAuthorName = gitAuthorEmail,
    sshKeyPath,
    workflowLocalPath,
    maxTurns,
    maxTokens,
    logSinkEnabled,
    implementationModel,
    emit,
  } = opts;

  const env = buildGitCommitEnv(gitAuthorEmail, gitAuthorName, sshKeyPath);
  const now = new Date().toISOString();

  // ── 1. Checkout and reset task branch in management repo ──────────────────────
  try {
    execSync(`git -C "${workspaceRoot}" fetch origin`, { env, stdio: "pipe" });
    execSync(
      `git -C "${workspaceRoot}" checkout "${taskBranch}"`,
      { env, stdio: "pipe" },
    );
    execSync(
      `git -C "${workspaceRoot}" reset --hard "origin/${taskBranch}"`,
      { env, stdio: "pipe" },
    );
  } catch (e) {
    emit({
      type: "review_claim_lost",
      task_id: taskId,
      feature_id: featureId,
      details: `Failed to checkout/reset management repo to task branch: ${String(e)}`,
    });
    return "claim_lost";
  }

  // ── 2. Read task and guard against duplicate claims ───────────────────────────
  let task: Task;
  try {
    task = readTask(workspaceRoot, featureId, taskId);
  } catch (e) {
    emit({
      type: "review_claim_lost",
      task_id: taskId,
      feature_id: featureId,
      details: `Failed to read task YAML: ${String(e)}`,
    });
    return "claim_lost";
  }

  // If the last log entry is review_started, another agent holds an active claim.
  // A prior review_started followed by blocked/in_review/etc means the cycle ended
  // and a new claim is valid (e.g. new comments after a previous review round).
  const lastEntry = task.log[task.log.length - 1];
  const alreadyClaimed = lastEntry?.action === "review_started";
  if (alreadyClaimed) {
    emit({
      type: "review_claim_lost",
      task_id: taskId,
      feature_id: featureId,
      details: "Last log entry is review_started — another agent currently holds the review claim.",
    });
    return "claim_lost";
  }

  // Guard against dispatch loops: count consecutive review cycles (review_started +
  // comments_addressed pairs) since the last non-review log entry. If >= 3, stop
  // dispatching — the agent has repeatedly attempted without fully resolving and
  // a human must inspect. Resets naturally whenever a human adds any other log entry.
  const REVIEW_CYCLE_ACTIONS = new Set(["review_started", "comments_addressed"]);
  const MAX_REVIEW_CYCLES = 3;
  let consecutiveReviewCycles = 0;
  for (let i = task.log.length - 1; i >= 0; i--) {
    if (!REVIEW_CYCLE_ACTIONS.has(task.log[i].action)) break;
    if (task.log[i].action === "review_started") consecutiveReviewCycles++;
  }
  if (consecutiveReviewCycles >= MAX_REVIEW_CYCLES) {
    emit({
      type: "review_loop_detected",
      task_id: taskId,
      feature_id: featureId,
      details: `${consecutiveReviewCycles} consecutive review cycles without resolution — human intervention required.`,
    });
    return "claim_lost";
  }

  // ── 3. Write review_started log entry and push (first-push-wins) ──────────────
  task.log.push({
    action: "review_started",
    by: gitAuthorEmail,
    at: now,
    note: "Review dispatch claimed; addressing open PR comments.",
  });
  task.execution.last_updated_by = gitAuthorEmail;
  task.execution.last_updated_at = now;

  writeTask(workspaceRoot, featureId, task);

  const relPath = taskYamlRelPath(featureId, taskId);
  try {
    execSync(`git -C "${workspaceRoot}" add "${relPath}"`, { env, stdio: "pipe" });
    execSync(
      `git -C "${workspaceRoot}" commit -m "chore(${taskId}): review_started — claim"`,
      { env, stdio: "pipe" },
    );
  } catch (e) {
    emit({
      type: "review_claim_lost",
      task_id: taskId,
      feature_id: featureId,
      details: `Failed to commit review_started claim: ${String(e)}`,
    });
    return "claim_lost";
  }

  const claimPush = spawnSync(
    "git",
    ["-C", workspaceRoot, "push", "origin", taskBranch],
    { env, encoding: "utf-8" },
  );

  if (claimPush.status !== 0) {
    emit({
      type: "review_claim_lost",
      task_id: taskId,
      feature_id: featureId,
      details: `Push rejected — another agent claimed the review first. stderr: ${claimPush.stderr}`,
    });
    return "claim_lost";
  }

  emit({
    type: "review_dispatching",
    task_id: taskId,
    feature_id: featureId,
    pr_url: task.pr.url,
  });

  // ── 4. Generate review agent context ─────────────────────────────────────────
  const agentContext = generateReviewAgentContext({
    taskId,
    featureId,
    taskTitle: task.title,
    taskBranch,
    taskRepo: task.repo,
    taskRepoRoot: implRepoRoot,
    workspaceRoot,
    prUrl: task.pr.url,
    gitAuthorEmail,
    gitAuthorName,
    implementationModel,
  });

  // ── 5. Run Claude ─────────────────────────────────────────────────────────────
  const runResult = await runClaude({
    taskId,
    featureId,
    workspaceRoot,
    taskRepoRoot: implRepoRoot,
    workflowLocalPath,
    agentContext,
    maxTurns,
    maxTokens,
    sshKeyPath,
    gitAuthorEmail,
    taskBranch,
    logSinkEnabled,
  });

  emit({
    type: "review_dispatch_complete",
    task_id: taskId,
    feature_id: featureId,
    outcome: runResult.outcome,
  });

  return "dispatched";
}

// ── Cycle-level orchestrator ──────────────────────────────────────────────────

/**
 * Iterate poll results where `hasOpenComments === true` and dispatch Claude
 * to address them. Triggered regardless of draft state — any in_review PR
 * with unresolved threads or unaddressed comments is eligible.
 * Called from `runOneCycle` in main.ts after the merge-conflict pass.
 */
export async function handleDraftReviews(
  opts: HandleDraftReviewsOptions,
): Promise<void> {
  const {
    prResults,
    workspaceRoot,
    resolveImplRepoRoot,
    resolveTaskRepoId,
    resolveImplementationModel,
    gitAuthorEmail,
    gitAuthorName,
    sshKeyPath,
    workflowLocalPath,
    maxTurns,
    maxTokens,
    logSinkEnabled,
    emit,
  } = opts;

  const draftTasks = prResults.filter((r) => r.hasOpenComments === true);

  for (const result of draftTasks) {
    const { taskId, featureId } = result;

    let repoId: string;
    try {
      repoId = resolveTaskRepoId(featureId, taskId);
    } catch (e) {
      emit({
        type: "review_dispatch_error",
        task_id: taskId,
        feature_id: featureId,
        details: `Cannot resolve repo ID: ${String(e)}`,
      });
      continue;
    }

    let implRepoRoot: string;
    try {
      implRepoRoot = resolveImplRepoRoot(repoId);
    } catch (e) {
      emit({
        type: "review_dispatch_error",
        task_id: taskId,
        feature_id: featureId,
        details: `Cannot resolve impl repo root: ${String(e)}`,
      });
      continue;
    }

    let implementationModel: string;
    try {
      implementationModel = resolveImplementationModel(featureId, taskId);
    } catch (e) {
      emit({
        type: "review_dispatch_error",
        task_id: taskId,
        feature_id: featureId,
        details: `Cannot resolve implementation model: ${String(e)}`,
      });
      continue;
    }

    const taskBranch = `feature/${featureId}-${taskId}`;

    try {
      await dispatchOneReview({
        workspaceRoot,
        featureId,
        taskId,
        taskBranch,
        implRepoRoot,
        gitAuthorEmail,
        gitAuthorName,
        sshKeyPath,
        workflowLocalPath,
        maxTurns,
        maxTokens,
        logSinkEnabled,
        implementationModel,
        emit,
      });
    } catch (e) {
      emit({
        type: "review_dispatch_error",
        task_id: taskId,
        feature_id: featureId,
        details: `Unexpected error in dispatchOneReview: ${String(e)}`,
      });
    }
  }
}

