/**
 * Tests for T5: run-claude.ts — writeBlockedAndPush writes blocked_context.
 *
 * Unit tests — node:child_process is fully mocked to avoid real git and
 * real claude invocations.
 *
 * Covers:
 *   1. blocked_context written with wip_branch, wip_sha, pushed_at on crash-block
 *   2. wip_branch matches the taskBranch passed to runClaude
 *   3. wip_sha falls back to "unknown" when git rev-parse throws
 *   4. blocked_context stays null when task reaches in_review (happy path)
 */

import { describe, it, expect, vi, afterEach } from "vitest";
import {
  mkdtempSync,
  mkdirSync,
  writeFileSync,
  readFileSync,
  rmSync,
} from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { EventEmitter } from "node:events";
import { execSync, spawn } from "node:child_process";
import { stringify as yamlStringify, parse as parseYaml } from "yaml";
import type { Task } from "../src/types/task.js";
import { runClaude } from "../src/loop/run-claude.js";

// ── Mock node:child_process ───────────────────────────────────────────────────

vi.mock("node:child_process", async (importOriginal) => {
  const actual = await importOriginal<typeof import("node:child_process")>();
  return {
    ...actual,
    spawn: vi.fn(),
    execSync: vi.fn(),
  };
});

// ── Fake child process factory ────────────────────────────────────────────────

/**
 * Returns a fake ChildProcess-like object whose close event fires asynchronously.
 * `onSpawn` is called synchronously so the caller can mutate the task YAML
 * before the close event resolves runClaude's Promise.
 */
function makeFakeChild(opts: {
  exitCode?: number | null;
  onSpawn?: () => void;
} = {}): ReturnType<typeof spawn> {
  const { exitCode = 0, onSpawn } = opts;
  const stdoutEmitter = Object.assign(new EventEmitter(), {
    setEncoding: vi.fn(),
  });
  const stderrEmitter = Object.assign(new EventEmitter(), {
    setEncoding: vi.fn(),
  });
  const childEmitter = new EventEmitter();

  const child = {
    stdout: stdoutEmitter,
    stderr: stderrEmitter,
    on: (event: string, handler: (...args: unknown[]) => void) => {
      childEmitter.on(event, handler);
      return child;
    },
  };

  // Emit close on the next microtask tick so callers can register handlers first.
  Promise.resolve().then(() => {
    onSpawn?.();
    childEmitter.emit("close", exitCode, null);
  });

  return child as unknown as ReturnType<typeof spawn>;
}

// ── Constants ─────────────────────────────────────────────────────────────────

const FEATURE_ID = "test-feature";
const TASK_ID = "T5";
const TASK_BRANCH = `feature/${FEATURE_ID}-${TASK_ID}`;
const GIT_AUTHOR_EMAIL = "test@example.com";
const FAKE_SHA = "abc123def456789deadbeef";

// ── Temp workspace helpers ────────────────────────────────────────────────────

const tmpDirs: string[] = [];

afterEach(() => {
  while (tmpDirs.length) {
    const d = tmpDirs.pop()!;
    try { rmSync(d, { recursive: true, force: true }); } catch { /* best-effort */ }
  }
  vi.clearAllMocks();
});

function makeTempWorkspace(
  initialStatus: Task["status"] = "in_progress",
): { workspaceRoot: string; taskYamlPath: string } {
  const dir = mkdtempSync(join(tmpdir(), "run-claude-test-"));
  tmpDirs.push(dir);
  const tasksDir = join(dir, "docs", "features", FEATURE_ID, "tasks");
  mkdirSync(tasksDir, { recursive: true });

  const task: Task = {
    id: TASK_ID,
    title: "Test task",
    repo: "test-repo",
    status: initialStatus,
    depends_on: [],
    blocked_reason: null,
    blocked_context: null,
    branch: TASK_BRANCH,
    execution: {
      actor_type: "agent",
      last_updated_by: GIT_AUTHOR_EMAIL,
      last_updated_at: "2026-04-15T10:00:00Z",
    },
    pr: { url: "", status: "not_created" },
    workspace_pr: null,
    log: [],
  };

  const taskYamlPath = join(tasksDir, `${TASK_ID}.yaml`);
  writeFileSync(taskYamlPath, yamlStringify(task), "utf-8");
  return { workspaceRoot: dir, taskYamlPath };
}

function readTask(workspaceRoot: string): Task {
  return parseYaml(
    readFileSync(
      join(workspaceRoot, "docs", "features", FEATURE_ID, "tasks", `${TASK_ID}.yaml`),
      "utf-8",
    ),
  ) as Task;
}

// ── Tests ─────────────────────────────────────────────────────────────────────

describe("runClaude — crash-block path (T5)", () => {
  it("writes blocked_context with wip_branch, wip_sha, pushed_at when task stays in_progress", async () => {
    const { workspaceRoot } = makeTempWorkspace("in_progress");

    // claude exits 0 but does NOT update task YAML (task remains in_progress)
    vi.mocked(spawn).mockReturnValueOnce(makeFakeChild({ exitCode: 0 }));

    // git rev-parse returns fake SHA; all other git commands are no-ops
    vi.mocked(execSync).mockImplementation((cmd: unknown) => {
      if (String(cmd).includes("rev-parse")) return `${FAKE_SHA}\n` as never;
      return "" as never;
    });

    const result = await runClaude({
      taskId: TASK_ID,
      featureId: FEATURE_ID,
      workspaceRoot,
      taskRepoRoot: workspaceRoot,
      workflowLocalPath: workspaceRoot,
      agentContext: "test context",
      maxTurns: 10,
      maxTokens: 5_000,
      sshKeyPath: undefined,
      gitAuthorEmail: GIT_AUTHOR_EMAIL,
      taskBranch: TASK_BRANCH,
      logSinkEnabled: false,
    });

    expect(result.outcome).toBe("blocked");
    if (result.outcome === "blocked") expect(result.reason).toBe("runtime_error");

    const task = readTask(workspaceRoot);
    expect(task.status).toBe("blocked");
    expect(task.blocked_reason).toBe("runtime_error");
    expect(task.blocked_context).not.toBeNull();
    expect(task.blocked_context?.wip_branch).toBe(TASK_BRANCH);
    expect(task.blocked_context?.wip_sha).toBe(FAKE_SHA);
    expect(task.blocked_context?.pushed_at).toBeTruthy();
    expect(new Date(task.blocked_context!.pushed_at).getTime()).toBeGreaterThan(0);
  });

  it("uses the taskBranch option as wip_branch", async () => {
    const { workspaceRoot } = makeTempWorkspace("in_progress");
    const customBranch = "feature/custom-feature-TX";

    vi.mocked(spawn).mockReturnValueOnce(makeFakeChild({ exitCode: 1 }));
    vi.mocked(execSync).mockImplementation((cmd: unknown) => {
      if (String(cmd).includes("rev-parse")) return `${FAKE_SHA}\n` as never;
      return "" as never;
    });

    await runClaude({
      taskId: TASK_ID,
      featureId: FEATURE_ID,
      workspaceRoot,
      taskRepoRoot: workspaceRoot,
      workflowLocalPath: workspaceRoot,
      agentContext: "test",
      maxTurns: 10,
      maxTokens: 5_000,
      sshKeyPath: undefined,
      gitAuthorEmail: GIT_AUTHOR_EMAIL,
      taskBranch: customBranch,
      logSinkEnabled: false,
    });

    const task = readTask(workspaceRoot);
    expect(task.blocked_context?.wip_branch).toBe(customBranch);
  });

  it("falls back to wip_sha 'unknown' when git rev-parse throws", async () => {
    const { workspaceRoot } = makeTempWorkspace("in_progress");

    vi.mocked(spawn).mockReturnValueOnce(makeFakeChild({ exitCode: 0 }));
    vi.mocked(execSync).mockImplementation((cmd: unknown) => {
      if (String(cmd).includes("rev-parse")) throw new Error("not a git repo");
      return "" as never;
    });

    await runClaude({
      taskId: TASK_ID,
      featureId: FEATURE_ID,
      workspaceRoot,
      taskRepoRoot: workspaceRoot,
      workflowLocalPath: workspaceRoot,
      agentContext: "test",
      maxTurns: 10,
      maxTokens: 5_000,
      sshKeyPath: undefined,
      gitAuthorEmail: GIT_AUTHOR_EMAIL,
      taskBranch: TASK_BRANCH,
      logSinkEnabled: false,
    });

    const task = readTask(workspaceRoot);
    expect(task.blocked_context?.wip_sha).toBe("unknown");
    // other fields still written
    expect(task.blocked_context?.wip_branch).toBe(TASK_BRANCH);
    expect(task.blocked_context?.pushed_at).toBeTruthy();
  });

  it("does NOT write blocked_context when task reaches in_review", async () => {
    const { workspaceRoot } = makeTempWorkspace("in_progress");

    // stub claude updates the task to in_review before close fires
    vi.mocked(spawn).mockReturnValueOnce(makeFakeChild({
      exitCode: 0,
      onSpawn: () => {
        const taskYamlPath = join(
          workspaceRoot, "docs", "features", FEATURE_ID, "tasks", `${TASK_ID}.yaml`,
        );
        const task = parseYaml(readFileSync(taskYamlPath, "utf-8")) as Task;
        task.status = "in_review";
        writeFileSync(taskYamlPath, yamlStringify(task), "utf-8");
      },
    }));

    vi.mocked(execSync).mockReturnValue("" as never);

    const result = await runClaude({
      taskId: TASK_ID,
      featureId: FEATURE_ID,
      workspaceRoot,
      taskRepoRoot: workspaceRoot,
      workflowLocalPath: workspaceRoot,
      agentContext: "test",
      maxTurns: 10,
      maxTokens: 5_000,
      sshKeyPath: undefined,
      gitAuthorEmail: GIT_AUTHOR_EMAIL,
      taskBranch: TASK_BRANCH,
      logSinkEnabled: false,
    });

    expect(result.outcome).toBe("in_review");

    // rev-parse must NOT have been called
    const revParseCalls = vi.mocked(execSync).mock.calls.filter(
      ([cmd]) => String(cmd).includes("rev-parse"),
    );
    expect(revParseCalls).toHaveLength(0);

    // blocked_context must stay null
    const task = readTask(workspaceRoot);
    expect(task.blocked_context).toBeNull();
  });
});

// ── RAG pre-flight audit ─────────────────────────────────────────────────────

describe("runClaude — RAG pre-flight audit", () => {
  it("appends a rag_pre_flight log entry before spawning claude", async () => {
    const { workspaceRoot } = makeTempWorkspace("in_progress");

    // claude moves the task to in_review on spawn
    vi.mocked(spawn).mockReturnValueOnce(makeFakeChild({
      exitCode: 0,
      onSpawn: () => {
        const taskYamlPath = join(
          workspaceRoot, "docs", "features", FEATURE_ID, "tasks", `${TASK_ID}.yaml`,
        );
        const task = parseYaml(readFileSync(taskYamlPath, "utf-8")) as Task;
        task.status = "in_review";
        writeFileSync(taskYamlPath, yamlStringify(task), "utf-8");
      },
    }));
    vi.mocked(execSync).mockReturnValue("" as never);

    const result = await runClaude({
      taskId: TASK_ID,
      featureId: FEATURE_ID,
      workspaceRoot,
      taskRepoRoot: workspaceRoot,
      workflowLocalPath: workspaceRoot,
      agentContext: "test",
      maxTurns: 10,
      maxTokens: 5_000,
      sshKeyPath: undefined,
      gitAuthorEmail: GIT_AUTHOR_EMAIL,
      taskBranch: TASK_BRANCH,
      logSinkEnabled: false,
      ragPreFlight: {
        query: "Test task test-feature",
        injected: true,
        summary: "Retrieved 3 chunks: docs/foo.md, docs/bar.md",
      },
    });

    expect(result.outcome).toBe("in_review");

    const task = readTask(workspaceRoot);
    const ragEntry = task.log.find((e) => e.action === "rag_pre_flight");
    expect(ragEntry).toBeDefined();
    expect(ragEntry?.rag_context_injected).toBe(true);
    expect(ragEntry?.rag_summary).toBe("Retrieved 3 chunks: docs/foo.md, docs/bar.md");
    expect(ragEntry?.rag_query).toBe("Test task test-feature");
    expect(ragEntry?.by).toBe(GIT_AUTHOR_EMAIL);
  });

  it("forces blocked outcome when the agent removes the rag_pre_flight entry", async () => {
    const { workspaceRoot } = makeTempWorkspace("in_progress");

    // claude finishes "successfully" but strips the rag_pre_flight log entry
    vi.mocked(spawn).mockReturnValueOnce(makeFakeChild({
      exitCode: 0,
      onSpawn: () => {
        const taskYamlPath = join(
          workspaceRoot, "docs", "features", FEATURE_ID, "tasks", `${TASK_ID}.yaml`,
        );
        const task = parseYaml(readFileSync(taskYamlPath, "utf-8")) as Task;
        task.status = "in_review";
        // simulate tampering: remove the rag_pre_flight entry the runtime wrote
        task.log = task.log.filter((e) => e.action !== "rag_pre_flight");
        writeFileSync(taskYamlPath, yamlStringify(task), "utf-8");
      },
    }));
    vi.mocked(execSync).mockImplementation((cmd: unknown) => {
      if (String(cmd).includes("rev-parse")) return `${FAKE_SHA}\n` as never;
      return "" as never;
    });

    const result = await runClaude({
      taskId: TASK_ID,
      featureId: FEATURE_ID,
      workspaceRoot,
      taskRepoRoot: workspaceRoot,
      workflowLocalPath: workspaceRoot,
      agentContext: "test",
      maxTurns: 10,
      maxTokens: 5_000,
      sshKeyPath: undefined,
      gitAuthorEmail: GIT_AUTHOR_EMAIL,
      taskBranch: TASK_BRANCH,
      logSinkEnabled: false,
      ragPreFlight: {
        query: "Test task test-feature",
        injected: true,
        summary: "Retrieved 2 chunks: docs/foo.md",
      },
    });

    expect(result.outcome).toBe("blocked");
    if (result.outcome === "blocked") {
      expect(result.reason).toBe("runtime_error");
      expect(String(result.details)).toContain("rag_audit_failed");
      expect(String(result.details)).toContain("missing");
    }

    const task = readTask(workspaceRoot);
    expect(task.status).toBe("blocked");
    expect(task.blocked_reason).toBe("runtime_error");
  });

  it("forces blocked outcome when the agent rewrites rag_summary", async () => {
    const { workspaceRoot } = makeTempWorkspace("in_progress");

    vi.mocked(spawn).mockReturnValueOnce(makeFakeChild({
      exitCode: 0,
      onSpawn: () => {
        const taskYamlPath = join(
          workspaceRoot, "docs", "features", FEATURE_ID, "tasks", `${TASK_ID}.yaml`,
        );
        const task = parseYaml(readFileSync(taskYamlPath, "utf-8")) as Task;
        task.status = "in_review";
        // simulate tampering: rewrite the summary to claim something different
        const ragEntry = task.log.find((e) => e.action === "rag_pre_flight");
        if (ragEntry) {
          ragEntry.rag_summary = "RAG context provided via system prompt";
        }
        writeFileSync(taskYamlPath, yamlStringify(task), "utf-8");
      },
    }));
    vi.mocked(execSync).mockImplementation((cmd: unknown) => {
      if (String(cmd).includes("rev-parse")) return `${FAKE_SHA}\n` as never;
      return "" as never;
    });

    const result = await runClaude({
      taskId: TASK_ID,
      featureId: FEATURE_ID,
      workspaceRoot,
      taskRepoRoot: workspaceRoot,
      workflowLocalPath: workspaceRoot,
      agentContext: "test",
      maxTurns: 10,
      maxTokens: 5_000,
      sshKeyPath: undefined,
      gitAuthorEmail: GIT_AUTHOR_EMAIL,
      taskBranch: TASK_BRANCH,
      logSinkEnabled: false,
      ragPreFlight: {
        query: "Test task test-feature",
        injected: false,
        summary: "tool_unavailable: MCP_RAG_URL not set",
      },
    });

    expect(result.outcome).toBe("blocked");
    if (result.outcome === "blocked") {
      expect(result.reason).toBe("runtime_error");
      expect(String(result.details)).toContain("rag_audit_failed");
      expect(String(result.details)).toContain("rag_summary mutated");
    }
  });

  it("passes audit when the agent appends entries after rag_pre_flight without touching it", async () => {
    const { workspaceRoot } = makeTempWorkspace("in_progress");

    vi.mocked(spawn).mockReturnValueOnce(makeFakeChild({
      exitCode: 0,
      onSpawn: () => {
        const taskYamlPath = join(
          workspaceRoot, "docs", "features", FEATURE_ID, "tasks", `${TASK_ID}.yaml`,
        );
        const task = parseYaml(readFileSync(taskYamlPath, "utf-8")) as Task;
        task.status = "in_review";
        // normal agent behavior: append a started entry
        task.log.push({
          action: "started",
          by: GIT_AUTHOR_EMAIL,
          at: "2026-04-28T16:30:00Z",
          note: "Implementation started.",
        });
        writeFileSync(taskYamlPath, yamlStringify(task), "utf-8");
      },
    }));
    vi.mocked(execSync).mockReturnValue("" as never);

    const result = await runClaude({
      taskId: TASK_ID,
      featureId: FEATURE_ID,
      workspaceRoot,
      taskRepoRoot: workspaceRoot,
      workflowLocalPath: workspaceRoot,
      agentContext: "test",
      maxTurns: 10,
      maxTokens: 5_000,
      sshKeyPath: undefined,
      gitAuthorEmail: GIT_AUTHOR_EMAIL,
      taskBranch: TASK_BRANCH,
      logSinkEnabled: false,
      ragPreFlight: {
        query: "Test task test-feature",
        injected: false,
        summary: "query_returned_no_chunks",
      },
    });

    expect(result.outcome).toBe("in_review");

    const task = readTask(workspaceRoot);
    expect(task.log.find((e) => e.action === "rag_pre_flight")).toBeDefined();
    expect(task.log.find((e) => e.action === "started")).toBeDefined();
  });

  it("does NOT write a rag_pre_flight entry when ragPreFlight option is omitted (review dispatch path)", async () => {
    const { workspaceRoot } = makeTempWorkspace("in_progress");

    vi.mocked(spawn).mockReturnValueOnce(makeFakeChild({
      exitCode: 0,
      onSpawn: () => {
        const taskYamlPath = join(
          workspaceRoot, "docs", "features", FEATURE_ID, "tasks", `${TASK_ID}.yaml`,
        );
        const task = parseYaml(readFileSync(taskYamlPath, "utf-8")) as Task;
        task.status = "in_review";
        writeFileSync(taskYamlPath, yamlStringify(task), "utf-8");
      },
    }));
    vi.mocked(execSync).mockReturnValue("" as never);

    const result = await runClaude({
      taskId: TASK_ID,
      featureId: FEATURE_ID,
      workspaceRoot,
      taskRepoRoot: workspaceRoot,
      workflowLocalPath: workspaceRoot,
      agentContext: "test",
      maxTurns: 10,
      maxTokens: 5_000,
      sshKeyPath: undefined,
      gitAuthorEmail: GIT_AUTHOR_EMAIL,
      taskBranch: TASK_BRANCH,
      logSinkEnabled: false,
      // ragPreFlight intentionally omitted
    });

    expect(result.outcome).toBe("in_review");

    const task = readTask(workspaceRoot);
    expect(task.log.find((e) => e.action === "rag_pre_flight")).toBeUndefined();
  });
});

